window.POEM_DB=window.POEM_DB||{};POEM_DB["song_032"]={"n":"司马光","dyn":"宋","poems":[{"t":"光诗首句云饱食复闲眠又成二章 其二 闲眠","f":"词","c":["秋怀一事无，暑尽昼凉初。","竹户静长闭，藜床安有馀。","逍遥化胡蝶，容易入华胥。","天上多官府，神仙恐不如。"]},{"t":"九日登麻蔺坂","f":"词","c":["客路逢佳节，无欢更益愁。","前山造云日，登陟不因游。"]},{"t":"二十七日邀子骏尧夫赏西街诸花","f":"词","c":["今年节物非常晚，春尽西街花尚多。","试问二三真率友，小车篮舁肯重过。"]},{"t":"二十六日作真率会伯康与君从七十八岁安之七十七岁正叔七十四岁不疑七十三岁叔达七十岁光六十五岁合五百一十五岁口号成诗用安之前韵 其二","f":"词","c":["经春无事连翩醉，彼此往来能几家。","切莫辞斟十分酒，尽从他笑满头花。"]},{"t":"二十六日作真率会伯康与君从七十八岁安之七十七岁正叔七十四岁不疑七十三岁叔达七十岁光六十五岁合五百一十五岁口号成诗用安之前韵 其一","f":"词","c":["七人五百有馀岁，同醉花前今古稀。","走马斗鸡非我事，纻衣丝发且相晖。"]},{"t":"二月六日初见待漏房前柳色微绿欣然成咏","f":"词","c":["宫城映出丝丝绿，顿觉皇州春意回。","从此不辞驱瘦马，六街终日踏尘埃。"]},{"t":"二月二十四日馆宿兴宗舍后桃花盛开偶书牖上","f":"词","c":["金马春寂寂，秾桃随意开。","夕风零落尽，不待主人来。"]},{"t":"十四日小园置茶招宗圣应之皆辞以醉为诗赠之","f":"词","c":["草树弄春晖，家家倒载归。","谁怜独醒客，日暝掩双扉。"]},{"t":"又七言","f":"词","c":["闻道山家门镇开，独驱瘦马出尘埃。","白云明月先无约，何事今宵亦此来。"]},{"t":"又即事二章上呈 其一","f":"词","c":["雨不成游半路归，逢花值柳倍依依。","朝来赖饮三杯酒，醉卧西斋昼掩扉。"]},{"t":"又即事二章上呈 其二","f":"词","c":["觉后追思气味长，欢情愁绪两俱忘。","近来方得醉中趣，熟寐沈沈是醉乡。"]},{"t":"又和上元日游南园赏梅花","f":"词","c":["中令园陪丞相游，百分劝酒不须愁。","春风陌上醒归去，只恐更为桃李羞。"]},{"t":"又和游吴氏园二首 其二","f":"词","c":["名园易主似行邮，美竹高松景自幽。","谁信本来天地物，长为已有固无由。"]},{"t":"又和游吴氏园二首 其一","f":"词","c":["天气清和无喘牛，花林烂熳竹林幽。","临风高咏足为乐，有勇知方笑仲由。"]},{"t":"又和董氏东园桧屏石床","f":"词","c":["密叶萧森翠幕纡，暂来犹恨不长居。","脱冠解带坐终日，花落石床春自如。"]},{"t":"又绝句","f":"词","c":["举首孤轮不似遥，尊前狂气出云霄。","常娥不惜惜丹桂，欲就高枝挂酒瓢。"]},{"t":"又寄","f":"词","c":["心目悠悠逐去鸿，别来容易四秋风。","莫嗟密密书连纸，万里经年信一通。"]},{"t":"寄题陟屺寺","f":"词","c":["郑南峰下寺前轩，反景分明见渭川。","为报十年容易别，于今愁悴不如先。"]},{"t":"又赠谓之 其二","f":"词","c":["篱下多新菊，渊明归思长。","主人方爱客，未得傲羲皇。"]},{"t":"又赠谓之 其三","f":"词","c":["君念东归日，应须昼绣荣。","当令故关吏，还识弃繻生。"]},{"t":"又赠谓之 其一","f":"词","c":["文藻兼名理，三吴第一贤。","乡心几千里，飞雁满秋天。"]},{"t":"三月二十五日安之以诗二绝见招作真率会光以无从者不及赴依韵和呈 其二","f":"词","c":["杯盘丰腆胜陶令，园沼繁华减白家。","惆怅佳辰掩蓬荜，不陪高会赏邻花。"]},{"t":"三月晦日登丰州故城","f":"词","c":["春尽芜城天一涯，白榆生荚柳生花。","满川战骨知谁罪，深属来人戒覆车。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其二","f":"词","c":["偃蹇登脩阪，高侵云日间。","几人征戍客，跋马望家山。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其一","f":"词","c":["岭上双流水，犹知会合时。","行人过于此，那得不相思。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其四","f":"词","c":["柳似妖饶舞，花如烂漫妆。","那堪陇头水，呜咽断人肠。"]},{"t":"大热","f":"词","c":["山泽欲焦枯，炎光满太虚。","不知天地外，暑气复何如。"]},{"t":"小诗招僚友晚游后园二首 其二","f":"词","c":["麦田小雨陇微青，草树欣欣照晚晴。","花下客来醒亦好，犹胜闭户过清明。"]},{"t":"小诗招僚友晚游后园二首 其一","f":"词","c":["五陵年少竞春晖，肥马银鞍白玉羁。","何似松间煮新茗，更来花底覆残棋。"]},{"t":"山家","f":"词","c":["林下脱双履，窗边挂幅巾。","闲堂风掩户，断岭月窥人。"]},{"t":"不寐","f":"词","c":["四远寂然群动收，只馀严鼓度坊楼。","无由更续三更梦，何处飞来一点愁。"]},{"t":"中秋陪张龙图宴射堂初夕阴云酒行顿解喜而成咏","f":"词","c":["飞盖共徘徊，西园高宴开。","秋云惜明月，留待庾公来。"]},{"t":"六十寄景仁","f":"词","c":["从来好与天争力，困竭方惭已力微。","见事晚于蘧伯玉，今知五十九年非。"]},{"t":"双井茶寄赠范景仁","f":"词","c":["春睡无端巧逐人，驱诃不去苦相亲。","欲凭洪井真茶力，试遣刀圭报谷神。"]},{"t":"太博同年叶兄以诗及建茶为贶家有蜀笺二轴辄敢系诗二章献于左右亦投桃报李之意也 其二","f":"词","c":["西来万里浣花笺，舒卷云霞照手鲜。","书笥久藏无可称，愿投诗客助新编。"]},{"t":"太博同年叶兄以诗及建茶为贶家有蜀笺二轴辄敢系诗二章献于左右亦投桃报李之意也 其一","f":"词","c":["闽山草木未全春，破颣真茶采撷新。","雅意不忘同臭味，先分畴昔桂堂人。"]},{"t":"归雁","f":"词","c":["亦知南国稻粱肥，水满春江努力归。","闻道楚人缯缴细，平沙短草尽藏机。"]},{"t":"石阁春望","f":"词","c":["极目千里外，川原绣画新。","方知平地上，见不尽青春。"]},{"t":"边将 其二","f":"词","c":["月白星稀霜气多，卷旗束甲涉葱河。","田家不觉官军度，夜半只闻风雨过。"]},{"t":"边将 其一","f":"词","c":["红旗一簇聚山椒，霁日清风看射雕。","脱帽少年遥稽首，汉家新将霍嫖姚。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其一","f":"词","c":["平湖漠漠芰荷稠，水国芳春不胜秋。","空有棹歌人不见，晚风一曲去悠悠。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其六","f":"词","c":["素舸朱篷青竹篙，棹歌风散近还遥。","斜阳借问归何处，家住水村郎姓萧。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其五","f":"词","c":["清江向晚采莲稀，独倚兰舟久未归。","目断可堪人不至，斜风细雨湿罗衣。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其二","f":"词","c":["越女行歌纵棹轻，苍茫别浦晚烟凝。","荷花折尽不归去，潋滟扁舟不易胜。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其三","f":"词","c":["荷底清涟照绮罗，长安公子旧情多。","踌躇不去知君意，重唱吴音白纻歌。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其四","f":"词","c":["贺监家居逸兴饶，枝分鉴水阔容舠。","穿荷宜去邀渔叟，共醉船头半榼醪。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其七","f":"词","c":["别殿无人梨自芳，玉阶朱槛绕金塘。","馆娃寂寞无西子，羞与吴宫竞晓妆。"]},{"t":"兴宗约游会灵久不闻问以诗趣之","f":"词","c":["胜地何妨行乐频，万双白璧不赊春。","腊醅已老久未压，杨柳青青不待人。"]},{"t":"兴宗许菊久之未得","f":"词","c":["菊栽许送定如何，庭下不堪秋草多。","九日无花更无酒，便携藜杖直相过。"]},{"t":"再呈宜甫","f":"词","c":["西家壶已倒，次第向东邻。","朱户如坚闭，黄花恶笑人。"]},{"t":"再和秉国约游石淙","f":"词","c":["上国分携十五秋，未尝偶坐捧茶瓯。","石淙今会须如约，彼此霜毛各满头。"]},{"t":"华严真师以诗见贶聊成二章纪其趣尚 其二","f":"词","c":["素发青眸七十馀，未尝游学只安居。","旁无几杖身轻健，应为心闲得自如。"]},{"t":"华严真师以诗见贶聊成二章纪其趣尚 其一","f":"词","c":["知足随缘处处安，一身温饱不为难。","禅房窄小才容榻，此外从他世界宽。"]},{"t":"同僚有独游东游者小诗寄之 其三","f":"词","c":["城楼传晚鼓，稍稍讼庭稀。","起拂衣中土，还骑款段归。"]},{"t":"同僚有独游东游者小诗寄之 其二","f":"词","c":["咫尺东园乐，无如簿领何。","春风连夜恶，闻道落花多。"]},{"t":"同僚有独游东游者小诗寄之 其一","f":"词","c":["车马东城路，芬芳数里尘。","风光不相待，愁杀未游人。"]},{"t":"夷齐","f":"词","c":["夷齐双骨已成尘，独有清名日日新。","饿死沟中人不识，可怜今古几何人。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其五","f":"词","c":["沙溆鹤争飞，波光可染衣。","松江异淇水，信美不如归。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其四","f":"词","c":["岫贴晴天阔，舟缘石岸深。","遥知作书处，缆袅绿波心。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其三","f":"词","c":["吴酿木兰春，红鲈白锦鳞。","玉盘聊下箸，初识紫丝莼。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其二","f":"词","c":["晓棹旌旗迥，暮河钲鼓喧。","商船极目避，汉使一何尊。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其一","f":"词","c":["韊矢迎山驿，轺车下帝台。","夜看牛斗分，应有使星来。"]},{"t":"庆历七年祀南郊礼毕贺赦","f":"词","c":["雷鼓千通破大幽，天开狱钥纵累囚。","驿书散出先飞鸟，一日恩流四百州。"]},{"t":"执酒","f":"词","c":["执酒劝君君尽之，今朝取醉不当疑。","好风好景心无事，闲利闲名何足知。"]},{"t":"早春 其一","f":"词","c":["梅梢柳萼未全开，日澹风和春意来。","雨后谁家有桃李，会须多买及时栽。"]},{"t":"早春寄景仁 其二","f":"词","c":["叠石溪上春，茅茨卜筑新。","前言如不践，山蝉又笑人。"]},{"t":"早春寄景仁 其一","f":"词","c":["辛夷花烂开，故人殊未来。","愁看柳渐绿，忍更折残梅。"]},{"t":"次前韵二首 其二","f":"词","c":["南园莫笑独追寻，明日未知晴与阴。","挥手一朝辞逆旅，满堂安用累千金。"]},{"t":"次前韵二首 其一","f":"词","c":["头白惜春情更深，花间独醉竞分阴。","泉声醒耳自可乐，不用歌抛满袖金。"]},{"t":"次韵和复古春日五绝句 其五","f":"词","c":["燕拂人衣絮扑头，红英满地绿阴稠。","残春举目多愁思，休上迢迢百尺楼。"]},{"t":"次韵和复古春日五绝句 其三","f":"词","c":["东城丝网蹴红毬，北里琼楼唱石州。","堪笑迂儒竹斋里，眼昏逼纸看蝇头。"]},{"t":"次韵和复古春日五绝句 其一","f":"词","c":["雪霜哀鬓拔还生，桃李新园长未成。","五十尚能胜六十，今年又灭去年情。"]},{"t":"次韵和复古春日五绝句 其四","f":"词","c":["家藏歌吹只西邻，吹落梅花歌落尘。","百叶桃开深院里，输他白发有情人。"]},{"t":"次韵和复古春日五绝句 其二","f":"词","c":["车如流水马如龙，花市相逢咽不通。","独闭柴荆老春色，任他陌上暮尘红。"]},{"t":"自都往馀杭怀聂之美","f":"词","c":["阁上新文卷，欲逢知已开。","相思不能已，攲枕梦君来。"]},{"t":"自渑至洛循谷水行百馀里","f":"词","c":["已烦谷水远相送，更得嵩峰遥见迎。","水碧峰青看未足，却愁前到洛阳城。"]},{"t":"自题写真","f":"词","c":["黄面霜须细瘦身，从来未识漫相亲。","居然不可市朝住，骨相天生林野人。"]},{"t":"观孙儿戏感怀","f":"词","c":["我昔垂髫今白头，中间万事水东流。","此心争得还如是，戏走阶前不识愁。"]},{"t":"观江上人壁许道宁画寒林","f":"词","c":["昔曾驱瘦马，冲雪过荥阳。","不悟当时景，萧然在此堂。"]},{"t":"过故洛阳城 其二","f":"词","c":["烟愁雨啸奈华生，宫阙簪蕖旧帝京。","若问古今兴废事，请君只看洛阳城。"]},{"t":"过故洛阳城 其一","f":"词","c":["四合连山缭绕青，三川滉漾素波明。","春风不识兴亡意，草色年年满故城。"]},{"t":"初春登兴国寺塔","f":"词","c":["雨过风清露气匀，林花变色柳条新。","为君作意登高处，试望皇州表里春。"]},{"t":"初夏独游南园二首 其二","f":"词","c":["桃李都无日，梧桐半死身。","那堪衰病意，更作独游人。"]},{"t":"初夏独游南园二首 其一","f":"词","c":["取醉非无酒，忘忧亦有花。","暂来疑是客，归去不成家。"]},{"t":"别用韵","f":"词","c":["坐中七叟推年纪，比较前人少几多。","花似锦红头雪白，不游不饮欲如何。"]},{"t":"吹箫","f":"词","c":["古人吹箫者，以和虞韶声。","后世不复贵，给丧仍卖饧。"]},{"t":"呈乐道","f":"词","c":["欢迎俛仰皆陈迹，薄宦须臾即色空。","试忆昔年双桂会，只如前日梦魂中。"]},{"t":"呈张子贱","f":"词","c":["近时洛社名真率，箪食壶浆取次游。","试问西来老朝散，可能同志便相收。"]},{"t":"园中书事二绝 其二","f":"词","c":["坐嗅白莲蕊，卧看青竹枝。","闲斋不成寐，起读圣俞诗。"]},{"t":"寿安杂诗十首 且游","f":"词","c":["游人恋山水，日晏澹忘归。","但爱云烟好，那知仆马饥。"]},{"t":"寿安杂诗十首 神林谷二首 其二","f":"词","c":["鸡帻奇峰云外横，青壁千寻不可上。","却羡樵儿轻险峡，腰绳操斧常来往。"]},{"t":"寿安杂诗十首 神林谷二首 其一","f":"词","c":["石下泉声蔓草深，石上露浓苍藓遍。","山禽惊起飞且鸣，叶坠空林人不见。"]},{"t":"寿安杂诗十首 灵山寺流泉","f":"词","c":["去寺犹一里，隔林闻水声。","安知客乘兴，山下远相迎。"]},{"t":"寿安杂诗十首 游神林谷寄邵尧夫","f":"词","c":["山人有山未尝游，俗客远来仍久留。","白云满眼望不见，可惜宜阳一片秋。"]},{"t":"应天院朝拜回呈景仁","f":"词","c":["鸡鸣上马过河桥，何异东都赴早朝。","红日已高犹熟寝，比君殊未得逍遥。"]},{"t":"花庵二首 其二","f":"词","c":["谁谓花庵陋，徒为见者嗤。","此中胜广厦，人自不能知。"]},{"t":"花庵二首 其一","f":"词","c":["谁谓花庵小，才容三两人。","君看宾席上，经月有凝尘。"]},{"t":"花庵诗寄邵尧夫 其二","f":"词","c":["自然天物胜人为，万叶无风绿四垂。","犹恨簪绅未离俗，荷衣蕙带始相宜。"]},{"t":"贡院中戏从元礼求酒","f":"词","c":["顾我虚罍耻，知君馀沥多。","庭前有春雪，如此薄寒何。"]},{"t":"走笔和君锡尧夫","f":"词","c":["先生洛社坐忘机，大尹朝天去佐时。","今日梅花浮别酒，青云早晚重来披。"]},{"t":"邵尧夫许来石阁久待不至","f":"词","c":["淡日浓云合复开，碧嵩清洛远萦回。","林间高阁望己久，花外小车犹未来。"]},{"t":"闲居","f":"词","c":["故人通贵绝相过，门外真堪置雀罗。","我已幽慵僮更懒，雨来春草一番多。"]},{"t":"饮吴之才家","f":"词","c":["京洛相逢设主人，富家鼎食不如贫。","解衣换酒同为乐，知是交情百倍亲。"]},{"t":"鸡","f":"词","c":["羽短笼深不得飞，久留宁为稻粱肥。","胶胶风雨鸣何苦，满室高眠正掩扉。"]},{"t":"其日雨中闻姚黄开戏成诗二章呈子骏尧夫 其一","f":"词","c":["谷雨后来花更浓，前时已是玉玲珑。","客来更说姚黄发，只在街西相第东。"]},{"t":"其日雨中闻姚黄开戏成诗二章呈子骏尧夫 其二","f":"词","c":["小雨留春春未归，好花虽有恐行稀。","劝君披取鱼蓑去，走看姚黄判湿衣。"]},{"t":"和之美舟行杂诗八首 水鸭","f":"词","c":["缡縰出短蒲，毰毸浴清水。","物忌太鲜明，何妨染泥滓。"]},{"t":"和之美舟行杂诗八首 鱼鹰","f":"词","c":["翩然下林表，不惮风湍恶。","得隽辄高飞，为君羞击搏。"]},{"t":"和之美舟行杂诗八首 船行遇风","f":"词","c":["蔡水仅成波，不若江湖浚。","诚无倾侧忧，缆弱终难进。"]},{"t":"和之美舟行杂诗八首 野花","f":"词","c":["喧喧桃李蹊，何妨笑幽草。","但愿保天真，徐共春风老。"]},{"t":"和之美舟行杂诗八首 罾鱼者","f":"词","c":["弱筱絓轻丝，尽日寒溪侧。","获少近知无，溪鱼皆尔识。"]},{"t":"和之美讽古 其二","f":"词","c":["海客久藏机，鸥知人未知。","如何毫末利，管鲍亦相欺。"]},{"t":"和之美讽古 其一","f":"词","c":["曲逆从汉祖，出奇谁与让。","一朝寄天下，不及王陵戆。"]},{"t":"和之美河洲四诗 其二","f":"词","c":["杳杳河洲晚，客行殊未返。","目随林鸟还，心共征鸿远。"]},{"t":"和之美河洲四诗 其一","f":"词","c":["冉冉河洲晓，晴霞登木杪。","稍见水烟开，孤舟天际小。"]},{"t":"和子华过王帅家见梅花盛开呈君实子骏兼简尧夫","f":"词","c":["去年与客尽清欢，今日重来立马看。","犹是携觞同醉在，只愁风雨横相干。"]},{"t":"和子华游君贶园 其一","f":"词","c":["甲第朱门久不开，春风潜入发江梅。","今朝丞相双车辙，碾破林间水畔苔。"]},{"t":"和任开叔观福严院旧题名","f":"词","c":["墨踪尘淡鬓华新，犹喜重来值故人。","二十二年如转目，洛阳不改旧时春。"]},{"t":"和安之今春于郑国相公及光处得缀珠莲各一本植之盆中仲夏始见一花喜而成咏末句云未知先合谢谁家","f":"词","c":["春冻消时种两芽，南风薰日见孤花。","先开必自陶钧力，且合归功丞相家。"]},{"t":"和尧夫先生相招游夏圃","f":"词","c":["野迥秋光满，径微朝露寒。","登高与行远，馀力尚桓桓。"]},{"t":"和次道奉慈斋宫见寄","f":"词","c":["去住邈如霄与尘，依依欲别更相亲。","虽知洛邑饶英俊，莫忘斋庐并直人。"]},{"t":"和君贶老君庙姚黄牡丹","f":"词","c":["芳菲触目已萧然，独著金衣奉老仙。","若占上春先秀发，千花万卉不成妍。"]},{"t":"和君锡雪后招探春 其一","f":"词","c":["莫嫌微雪压梅芽，已有归鸿泊浦沙。","天上诏来难久驻，直须早看洛阳花。"]},{"t":"和张伯常贺迁资政","f":"词","c":["不驾使车开汉关，不栖岩穴鍊金丹。","岂无开径三人友，分著垂緌五寸冠。","坐饱太仓犹自愧，谬跻秘殿益难安。","愿同野老嬉尧壤，长守先生苜蓿盘。"]},{"t":"和张推官同年春阴无绪偶成 其二","f":"词","c":["薄寒未去腊才过，春色先知在绿波。","不是宿云能作思，大都王粲自情多。"]},{"t":"和张推官同年春阴无绪偶成 其一","f":"词","c":["澹泊轻云寒不收，未成春雨只添愁。","风烟寂寞几何限，尽入凭高一寸眸。"]},{"t":"和李君锡惠书及诗勉以早归","f":"词","c":["书意勤渠诗意新，清如白雪暖如春。","西游不尽溪山乐，策马归来就故人。"]},{"t":"和秉国芙蓉五章 其五","f":"词","c":["但见涉江求水际，岂知胜木采霜中。","微红未肯全衰歇，正似酡颜鹤发翁。"]},{"t":"和秉国芙蓉五章 其四","f":"词","c":["后时独立诚难事，犹赖阶庭有菊丛。","绰约霜前弄姿态，非如群木万株红。"]},{"t":"和秉国芙蓉五章 其三","f":"词","c":["平昔低头避桃李，英华今发岁云秋。","盛时已过浑如我，醉舞狂歌插满头。"]},{"t":"和秉国芙蓉五章 其二","f":"词","c":["北方稀见诚奇物，笔界轻丝指捻红。","楚蜀可怜人不赏，墙根屋角数无穷。"]},{"t":"和秉国芙蓉五章 其一","f":"词","c":["清晓霜华漫自浓，独凭爱日养残红。","劝君秉烛须勤赏，阊阖难禁一夜风。"]},{"t":"和留守相公寄酒与景仁","f":"词","c":["想对白衣初满倾，执杯未饮已诗成。","怀贤孤坐悄无语，不是朝来困宿酲。"]},{"t":"和聂之美重游东郡","f":"词","c":["南湖重过又逢春，官柳虽疏亦解新。","台榭倾攲宾友散，临风愁杀独游人。"]},{"t":"和景仁七十一偶成","f":"词","c":["心地长闲为己物，年华不住是天时。","当时海上乘槎客，维楫都无任所之。"]},{"t":"和范景仁宿憩鹤寺","f":"词","c":["回廊复阁势萦纡，四岭中涵一气虚。","最爱欣欣向荣木，每来相见不相疏。"]},{"t":"和景仁游寿安","f":"词","c":["宜阳城下作游人，都为衣冠不系身。","众窍怒号成地籁，也胜终日在红尘。"]},{"t":"和景文议交绝句","f":"词","c":["迩来友义渐隳颓，直谅多闻贵不回。","势利相交何足道，已知馀耳愧陈雷。"]},{"t":"和道矩红梨花二首 其二","f":"词","c":["蜀江新锦濯朝阳，楚国纤腰傅薄妆。","何事白花零落早，同时不改斗芬芳。"]},{"t":"和道矩红梨花二首 其一","f":"词","c":["繁枝细叶互低昂，香敌酴醾艳海棠。","应为穷边太寥落，并将春色付秾芳。"]},{"t":"和潞公行及白马寺得留守相公书云名园例惜好花以候同赏诗二章 其二","f":"词","c":["相国东郊迓帝师，油幢交映碧参差。","都人共喜安舆到，正是馀花可惜时。"]},{"t":"和潞公行及白马寺得留守相公书云名园例惜好花以候同赏诗二章 其一","f":"词","c":["云汉成章湛露晞，都门宴饯羽觞飞。","谢安不复东山去，争似阿衡得谢归。"]},{"t":"和潞公招尧夫不至","f":"词","c":["东阁樽罍招共饮，后房罗绮约同观。","既无蓟子分身术，须欠车公一座欢。"]},{"t":"和懋贤闻道矩小园置酒助以酒果副之以诗","f":"词","c":["芙蓉幕下惜馀闲，不使芳华取次残。","珍果醇醪与新句，并将佳味助清欢。"]},{"t":"垂柳","f":"词","c":["天意清和二月初，春风不动整如梳。","陶潜宅外时无此，想更萧条不易居。"]},{"t":"奉和经略庞龙图延州南城八咏 其一 迎薰亭","f":"词","c":["华馆压清波，坐待南风至。","须知明牧贤，善达吾君意。"]},{"t":"奉和经略庞龙图延州南城八咏 其五 翠漪亭","f":"词","c":["雕檐日华动，滉瀁照漪涟。","四月芰荷满，不似在穷边。"]},{"t":"奉和经略庞龙图延州南城八咏 其八 禊堂","f":"词","c":["箫鼓震阳休，组练照芳洲。","意气坐中客，羞笑山阴游。"]},{"t":"宜甫家有金铃菊客未之识因代菊赠宜甫","f":"词","c":["主人倦邀客，寂寞委苍苔。","此日开无益，明年不复开。"]},{"t":"放鹦鹉二首 其二","f":"词","c":["虽道长安乐，争如在陇头。","林间祝圣主，万岁复千秋。"]},{"t":"放鹦鹉二首 其一","f":"词","c":["野性思归久，笼樊今始开。","虽知主恩厚，何日肯重来。"]},{"t":"昌言见督诗债戏呈绝句","f":"词","c":["学馁才贫杼轴劳，踰年避债负诗豪。","倒囊不惜偿虚券，未敌琼瑶旧价高。"]},{"t":"昌言有咏石发诗三章模写精楷殆难复加仆虽未睹兹物而已若识之久者辄复强为三诗以继其后非敢庶几肩差适足为前诗之舆台耳 其一","f":"词","c":["万古风涛浸石岩，老苔垂足细䰐鬖。","传闻海底珠无数，何事从来散不簪。"]},{"t":"昌言有咏石发诗三章模写精楷殆难复加仆虽未睹兹物而已若识之久者辄复强为三诗以继其后非敢庶几肩差适足为前诗之舆台耳 其三","f":"词","c":["琅菜来从若木边，非膏非沐绿宛延。","玉盘委积羞佳客，不是陶家无馔钱。"]},{"t":"昌言有咏石发诗三章模写精楷殆难复加仆虽未睹兹物而已若识之久者辄复强为三诗以继其后非敢庶几肩差适足为前诗之舆台耳 其二","f":"词","c":["金阙银城仙客居，欲传消息问麻姑。","蓬莱无物堪为信，剪寄苍龙一握须。"]},{"t":"昌言谪官符离有病鹤折翼舟载以行及还修注始平公以诗问之命光同赋二首 其二","f":"词","c":["相阁书传紫闼深，破缄先问九皋禽。","不令一物伤天理，仁爱方知真宰心。"]},{"t":"昌言谪官符离有病鹤折翼舟载以行及还修注始平公以诗问之命光同赋二首 其一","f":"词","c":["曾下青田啄玉苗，泥沙病羽久萧条。","谪仙不欲留尘世，依旧提携上碧霄。"]},{"t":"明日雨止复招子骏尧夫游南园 其二","f":"词","c":["遥思花寨交横锦，未分春心斗顿灰。","更与二三头白友，试携薄具上高台。"]},{"t":"明日雨止复招子骏尧夫游南园 其一","f":"词","c":["昨朝洛北阻游陪，惆怅中桥半醉回。","泼火既经寒食雨，解酲须拨冻醪醅。"]},{"t":"昔予尝权宰韦城今重过之二十五年矣慨然有怀","f":"词","c":["二十五年南北走，遗爱寂然民记否。","昔日婴儿今壮夫，昔日壮夫今老叟。"]},{"t":"武成致斋奉酬吴冲卿寺丞太学宿直见寄二首 其二","f":"词","c":["雪后馀冰尚缀檐，月华霜气入疏帘。","难堪琼玉惊心骨，坐觉清寒几倍添。"]},{"t":"武成致斋奉酬吴冲卿寺丞太学宿直见寄二首 其一","f":"词","c":["广文更直太常斋，咫尺无从尽素怀。","不及清风得随意，夜深容易过天街。"]},{"t":"河北道中作 其三","f":"词","c":["原上累累古冢高，昔时意气尽贤豪。","断碑名姓已磨灭，永日东风吹野蒿。"]},{"t":"河北道中作 其二","f":"词","c":["河势东回今几年，浓阴满目尽桑田。","川原变化无终极，一气不为常寂然。"]},{"t":"河北道中作 其一","f":"词","c":["绿柳阴中白浪花，河边日日暗风沙。","解鞍纵马悄无事，隐几看书随处家。"]},{"t":"河边晚望","f":"词","c":["高浪崩奔捲白沙，悠悠极望入天涯。","谁能脱落尘中意，乘兴东游坐石槎。"]},{"t":"河桥春别","f":"词","c":["河桥春尽送君归，又惜无欢度此时。","乱花满眼遮人望，不见行尘空酒旗。"]},{"t":"陜城桃李零落已尽硖石山中今方盛开马上口占","f":"词","c":["西望飞花千树暗，东来芳蕊一番新。","行人不惜泥涂倦，喜见年光两处春。"]},{"t":"前年春与楚正叔同游陟屺寺今兹已复周岁窅然思之","f":"词","c":["陟屺寺南山，曾陪半日闲。","春来梦携手，宛在白云间。"]},{"t":"居洛初夏作","f":"词","c":["四月清和雨乍晴，南山当户转分明。","更无柳絮随风起，惟有葵花向日倾。"]},{"t":"待诏 其二","f":"词","c":["待诏久公车，囊装半已虚。","雄文虽雅丽，未得似相如。"]},{"t":"待诏 其一","f":"词","c":["京洛风尘里，相逢眼尽青。","故人多密近，谁诵四隅铭。"]},{"t":"春","f":"词","c":["红桃素李竞年华，周偏长安万万家。","何事青青庭下柏，东风吹尽亦无花。"]},{"t":"春贴子词 太皇太后阁六首 其六","f":"词","c":["东宫归政五年馀，隐几时观黄老书。","禁闼无为民自化，熙熙不独在春初。"]},{"t":"春贴子词 太皇太后阁六首 其五","f":"词","c":["冰澌半解波先绿，柳叶未生条已黄。","四海澄清天子孝，朝回日奉万年觞。"]},{"t":"春贴子词 太皇太后阁六首 其三","f":"词","c":["长乐晓钟残，皇舆入问安。","东风犹料峭，冒絮禦馀寒。"]},{"t":"春贴子词 太皇太后阁六首 其二","f":"词","c":["种桃临玉井，裁胜刻金花。","借问此何处，昆山王母家。"]},{"t":"春贴子词 太皇太后阁六首 其一","f":"词","c":["盛德初临震，阳和已动坤。","发生天施大，厚载母仪尊。"]},{"t":"春贴子词 夫人阁四首 其四","f":"词","c":["圣主终朝勤万几，燕居专事养希夷。","千门永昼春岑寂，不用车前插竹枝。"]},{"t":"春贴子词 夫人阁四首 其三","f":"词","c":["绮窗绣户又东风，丹掖游陪岁岁同。","但愿太平无限乐，何须三十六离宫。"]},{"t":"春贴子词 夫人阁四首 其二","f":"词","c":["剪綵催花发，开帘望燕归。","藏阄新过腊，习舞竞裁衣。"]},{"t":"春贴子词 夫人阁四首 其一","f":"词","c":["壁带非烟润，金铺霁景鲜。","绣功添采缕，和气入繁弦。"]},{"t":"春贴子词 皇太后阁六首 其六","f":"词","c":["裁缝大练成春服，慈俭由来性所钟。","肯使外家矜侈靡，车如流水马如龙。"]},{"t":"春贴子词 皇太后阁六首 其五","f":"词","c":["玉漏声残金殿开，乘舆清跸问安来。","尽将草木欣欣意，同与新春入寿杯。"]},{"t":"春贴子词 皇太后阁六首 其四","f":"词","c":["钗上花开海燕飞，红缯剪萼蜡粘枝。","风前飘荡参差羽，还似瑶箱呈瑞时。"]},{"t":"春贴子词 皇太后阁六首 其二","f":"词","c":["暖日初添刻，柔风乍袭衣。","弄孙时哺果，观织屡临机。"]},{"t":"春贴子词 皇太后阁六首 其一","f":"词","c":["母德思齐盛，天心奋豫初。","青晖凝辇路，佳气拥宸居。"]},{"t":"春贴子词 皇后阁五首 其四","f":"词","c":["宝胜金幡巧斗功，綵花蜡燕飏和风。","玉盘翠苣映红蓼，捧案朝来献两宫。"]},{"t":"春贴子词 皇后阁五首 其三","f":"词","c":["沟暖冰初断，窗晴雪半消。","馀寒不足畏，涂壁尽芳椒。"]},{"t":"春贴子词 皇后阁五首 其二","f":"词","c":["樛木犹藏叶，夭桃未作花。","六宫歌逮下，四海咏宜家。"]},{"t":"春贴子词 皇帝阁六首 其五","f":"词","c":["浮阳满野白溶溶，泽底山椒淑气通。","草木岂能知造化，一华一叶尽天功。"]},{"t":"春贴子词 皇帝阁六首 其四","f":"词","c":["候雁来归北，寒鱼陟负冰。","相乌风色改，旸谷日华升。"]},{"t":"春贴子词 皇帝阁六首 其三","f":"词","c":["盛德方迎木，柔风渐布和。","省耕将效驾，击壤已闻歌。"]},{"t":"春贴子词 皇帝阁六首 其二","f":"词","c":["鸾路迎长日，农祥正晓天。","九垓同燠沐，万物向蕃鲜。"]},{"t":"春贴子词 皇帝阁六首 其一","f":"词","c":["肇履璿玑历，重飞缇室灰。","寒随土牛尽，暖应斗车回。"]},{"t":"春晓","f":"词","c":["钟漏初传晓，满窗风雨寒。","东冈行可种，攲枕不成安。"]},{"t":"春游","f":"词","c":["人物竞纷华，骊驹逐钿车。","此时松与柏，不及道傍花。"]},{"t":"柳枝词十三首 其十三","f":"词","c":["宣阳门前三月初，家家杨柳绿藏乌。","欢似白花飘荡去，忍能弃掷博山炉。"]},{"t":"柳枝词十三首 其十二","f":"词","c":["白雪虽然比絮花，艳阳不得共繁华。","为君故入乌衣巷，飞舞风流谢傅家。"]},{"t":"柳枝词十三首 其十一","f":"词","c":["五柳先生门乍开，宅边植杖久徘徊。","陌头遥认颜光禄，诘旦先乘瘦马来。"]},{"t":"柳枝词十三首 其十","f":"词","c":["行人白马去遥遥，初上金堤欲过桥。","望尘不见遮人眼，苦怨无情万万条。"]},{"t":"柳枝词十三首 其九","f":"词","c":["多愁尤是别离深，折条相赠各沾襟。","留住不住居人意，欲去未去行人心。"]},{"t":"柳枝词十三首 其八","f":"词","c":["新丰道上灞陵头，又送夫君去远游。","借问柳枝能寄否，古今共有几多愁。"]},{"t":"柳枝词十三首 其七","f":"词","c":["舞腰缤纷长乐东，柳间怅饮送春风。","请君试望邯郸道，青门袅袅彻新丰。"]},{"t":"柳枝词十三首 其六","f":"词","c":["双双春燕飏云霄，楚国宫深乐事饶。","会待急管繁弦际，试取纤条并舞腰。"]},{"t":"柳枝词十三首 其五","f":"词","c":["长门宫晓未成妆，结雨萦风蔽琐窗。","莫令透入华梁燕，那堪负汝更双双。"]},{"t":"柳枝词十三首 其四","f":"词","c":["属车隐隐远如雷，陈后愁眉久不开。","杨花都不知人意，故入长门宫里来。"]},{"t":"柳枝词十三首 其三","f":"词","c":["君王游豫赏青春，折柳为弮赐侍臣。","莫怪长条低拂地，只缘供扫属车尘。"]},{"t":"柳枝词十三首 其二","f":"词","c":["依依高树出宫墙，摇曳青丝百尺长。","愿与宣温万年树，年年岁岁奉君王。"]},{"t":"柳枝词十三首 其一","f":"词","c":["烟满上林春未归，三三两两雪花飞。","柳条别得东皇意，映堤拂水已依依。"]},{"t":"独乐园二首 其二","f":"词","c":["客到暂冠带，客归还上关。","朱门客如市，岂得似林间。"]},{"t":"独乐园二首 其一","f":"词","c":["独乐园中客，朝朝常闭门。","端居无一事，今日又黄昏。"]},{"t":"独步至洛滨 其二","f":"词","c":["草软波清沙径微，手携筇竹著深衣。","白鸥不信忘机久，见我犹穿岸柳飞。"]},{"t":"独步至洛滨 其一","f":"词","c":["拜表归来抵寺居，解鞍纵马罢传呼。","紫衣金带尽脱去，便是林间一野夫。"]},{"t":"看花四绝句 其一","f":"词","c":["洛阳相望尽名园，墙外花胜墙里看。","手摘青梅共挼酒，何须一一具杯盘。"]},{"t":"看花四绝句 其二","f":"词","c":["洛阳相识尽名流，骑马游胜下马游。","乘兴东西无不到，但逢青眼即淹留。"]},{"t":"看花四绝句 其四","f":"词","c":["南园桃李近方栽，浇水未乾花已开。","山果野蔬随分有，交游不厌但频来。"]},{"t":"看花四绝句 其三","f":"词","c":["洛阳春日最繁华，红绿阴中十万家。","谁道群花如锦绣，人将锦绣学群花。"]},{"t":"贻夸者","f":"词","c":["我乐非君乐，君忧非我忧。","蓬蒿与溟渤，终老不同游。"]},{"t":"送伯淳监汝州酒","f":"词","c":["惟知负米乐，不觉抱关卑。","出处两得意，是非皆自知。"]},{"t":"送酒与邵尧夫因戏之","f":"词","c":["林下虽无忧可消，许由闻说挂空瓢。","请君呼取孟光饮，共插花枝煮药苗。"]},{"t":"送酒与邵尧夫","f":"词","c":["红樱零落杏花开，春物相催次第来。","莫作林间独醒客，任从花笑玉山颓。"]},{"t":"送景仁至丁正臣园寄主人","f":"词","c":["客到暂开扃，春芜生满庭。","主人殊不顾，修竹为谁青。"]},{"t":"重九日忆菊","f":"词","c":["节物都何晚，佳辰容易过。","黄花不足念，当奈酒杯何。"]},{"t":"闻正叔与客过赵园欢饮戏成小诗","f":"词","c":["吾庐寂寞类荒村，但有林间鸟雀喧。","不似楚家多乐事，笙歌拾得醉邻园。"]},{"t":"夏日西斋书事","f":"词","c":["榴花映叶未全开，槐影沉沉雨势来。","小院地偏人不到，满庭鸟迹印苍苔。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其五","f":"词","c":["弊居橘亦自南移，爱护栽培费岁时。","前此实成酸苦甚，应由与德不相宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其四","f":"词","c":["物不须多且赏奇，禦寒相见结庵时。","江南江北徒虚语，尽信前书是不宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其三","f":"词","c":["君从好事不知疲，种子成株凡几时。","摘献帝师三取二，自尝两颗且随宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其二","f":"词","c":["圆小香黄珠颗垂，结成洛邑重霜时。","相公和气陶群物，不是寒温变土宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其一","f":"词","c":["宜春果结洛阳枝，正遇耆明会客时。","更引轻舟倚芦岸，香粳鲜鲙雅相宜。"]},{"t":"效赵学士体成口号十章献开府太师 其八","f":"词","c":["首夏清和新雨晴，绿莎细软不妨行。","园夫遮道白何事，栀子花开斑笋生。"]},{"t":"效赵学士体成口号十章献开府太师 其九","f":"词","c":["矮帽长绦紫縠衫，朱门深静似重岩。","莫言永日浑无事，种药移花一一监。"]},{"t":"效赵学士体成口号十章献开府太师 其五","f":"词","c":["公厨敕许酿芳樽，屡唤宾朋醉后园。","谑浪略无名位间，谁人知道太师尊。"]},{"t":"效赵学士体成口号十章献开府太师 其三","f":"词","c":["归来甫可及春残，丞相频邀赏牡丹。","远处名园多不到，尊前日献百馀盘。"]},{"t":"效赵学士体成口号十章献开府太师 其四","f":"词","c":["洛阳风俗重繁华，荷担樵夫亦戴花。","贪看二公同宴会，游人昏黑忘还家。"]},{"t":"效赵学士体成口号十章献开府太师 其二","f":"词","c":["东郊车马走红尘，城外多于城里人。","谁信今朝还政后，过如前岁下车新。"]},{"t":"效赵学士体成口号十章献开府太师 其十","f":"词","c":["八十聪明强健身，况从壮岁秉鸿钧。","功名富贵古亦有，无事归来能几人。"]},{"t":"效赵学士体成口号十章献开府太师 其一","f":"词","c":["都人共喜太师回，比户争迎不得催。","正值土楼滩水浅，大家出手挽船来。"]},{"t":"效赵学士体成口号十章献开府太师 其七","f":"词","c":["东田小籍选新声，歌吹胡琴色色精。","客少有时全不用，天然水竹湛馀清。"]},{"t":"晓霁","f":"词","c":["梦觉繁声绝，林光透隙来。","开门惊乌鸟，馀滴堕苍苔。"]},{"t":"留别东郡诸僚友 其一","f":"词","c":["际日浮空涨海流，虫沙龙蜃各优游。","津涯浩荡虽难测，不见惊澜曾覆舟。"]},{"t":"留别东郡诸僚友 其四","f":"词","c":["祖帐飘扬堤柳边，北来飞盖复连翩。","追随不忍轻言别，回首城楼没晚烟。"]},{"t":"留别东郡诸僚友 其三","f":"词","c":["楚国良金百鍊精，深藏求售价连城。","岂徒丰狱吹毛利，兼有秦台照胆明。"]},{"t":"留别东郡诸僚友 其五","f":"词","c":["空府同来贤大夫，短亭门外即长涂。","不辞烂醉樽前倒，明日此欢重得无。"]},{"t":"留别东郡诸僚友 其二","f":"词","c":["白璧紫金为世宝，贤愚知贵莫能名。","庙堂祭器杯盘物，随处得之光彩生。"]},{"t":"留客","f":"词","c":["酒烟漠漠自生春，舞袖飘飖拍拍新。","须信客归丝竹散，清风白月解愁人。"]},{"t":"病酒呈晋州李八丈","f":"词","c":["身如五岭炎蒸里，心似三江高浪中。","谁道醉乡风土好，舟车常愿不相通。"]},{"t":"秦人","f":"词","c":["楚旗猎猎盖山红，回首咸阳一炬空。","惆怅秦人虚用意，几年辛苦得山东。"]},{"t":"读颍公清风集 其二","f":"词","c":["人生百岁隙中光，唯有高名久不忘。","千古但令编简在，清风养物一何长。"]},{"t":"读颍公清风集 其一","f":"词","c":["伊皋垂训皆王度，周召陈诗尽国风。","非独立言方不朽，相君功业自无穷。"]},{"t":"读颍公清风集 其四","f":"词","c":["一言华衮足为荣，况托文编久愈明。","邹湛不逢羊叔子，世间何处复知名。"]},{"t":"得菊并诗","f":"词","c":["黄花小垡和烟斸，野兴萧萧已相逐。","同来更得兼诗句，久立看诗忘栽菊。"]},{"t":"晚行后园见菊戏宜甫","f":"词","c":["野菊荒无数，班班初见花。","径须求一醉，试遣问东家。"]},{"t":"晚秋洛中思归东园","f":"词","c":["不利不名空去国，雁飞叶落未归来。","秋风肯待主人至，篱下黄花随意开。"]},{"t":"晚晖亭","f":"词","c":["俯临城市厌諠哗，回顾园林景更加。","醉立斜阳头似雪，往来误认白公家。"]},{"t":"梅花 其三","f":"词","c":["驿使何时发，凭君寄一枝。","陇头人不识，空向笛中吹。"]},{"t":"梅花 其二","f":"词","c":["塞北为君戍，江南是妾家。","遥知关外雪，只似岭头花。"]},{"t":"梅花 其一","f":"词","c":["从与夫君别，寒花几度春。","坐愁芳树老，况乃鉴中人。"]},{"t":"梦与之美为寒食游","f":"词","c":["寒食无佳赏，芳菲半已空。","夜来逢胜友，末至负东风。"]},{"t":"深夜","f":"词","c":["疏星映户月流天，群动收声四寂然。","嗟尔寒蛬怨何事，悲吟彻曙亦无眠。"]},{"t":"野轩","f":"词","c":["黄鸡白酒田间乐，藜杖葛巾林下风。","更若食芹仍暴背，野怀并在一轩中。"]},{"t":"阏逢敦牂二月十一日与一二僚友游叔礼园亭以诗戏呈","f":"词","c":["下马久徘徊，林芳殊未开。","春风真有意，须待主翁来。"]},{"t":"喷玉潭","f":"词","c":["千尺崖头一派清，古今不绝坠峥嵘。","长风卷起散岩壑，此日方知喷玉名。"]},{"t":"寒食游南园独饮","f":"词","c":["寒食良辰无赏心，杂花烂熳柳成阴。","若非独酌酬佳景，一日风光直万金。"]},{"t":"普明寺荷塘上置酒","f":"词","c":["菡萏飘零水寂寥，败荷疏柳共萧条。","烟斜雨细愁无限，醇酒千分不易消。"]},{"t":"景仁思归雨未克行以诗留之","f":"词","c":["嘉客念归程，泥深未可行。","今朝阴又重，春雨亦多情。"]},{"t":"游喷玉潭 其一","f":"词","c":["惊风动地起，游客望山行。","若待佳辰去，应无好事名。"]},{"t":"游喷玉潭 其二","f":"词","c":["万木吼穹谷，驽骀屹不前。","犹胜望尘客，伫立九衢边。"]},{"t":"登长安见山楼","f":"词","c":["到官今十日，才得一朝闲。","岁晚愁云合，登楼不见山。"]},{"t":"集句诗","f":"词","c":["年去年来来去忙，暂偷闲卧老僧床。","惊回一觉游仙梦，又逐流莺过短墙。"]},{"t":"叠石溪 其二","f":"词","c":["山鸟劝人饮，山蝉笑我狂。","归时兴未尽，不得看斜阳。"]},{"t":"叠石溪 其一","f":"词","c":["道傍行采药，石底卧题名。","野老相迎拜，溪童乍见惊。"]},{"t":"感怀","f":"词","c":["昨日春冰破水边，今朝腊雪坠风前。","岁华过目疾飞鸟，壮志如何不着鞭。"]},{"t":"数日不至后圃今晚偶来芳物都尽率然成诗","f":"词","c":["烂漫不解赏，飘零空惨悽。","残红正满地，不忍踏芳蹊。"]},{"t":"虞部刘员外约游金明光以贱事失期刘惠诗见嘲以诗四首谢之 其二","f":"词","c":["绛阙朝归散玉珂，不游不饮奈春何。","皇仁听使欢娱极，白简从君冷峭多。"]},{"t":"虞部刘员外约游金明光以贱事失期刘惠诗见嘲以诗四首谢之 其一","f":"词","c":["丝管嘈嘈耳不分，绮罗杂踏自成春。","不唯汉帝昆明小，更觉唐家曲水贫。"]},{"t":"虞部刘员外约游金明光以贱事失期刘惠诗见嘲以诗四首谢之 其三","f":"词","c":["碧柳红桃照眼春，绮肴芳醴集朝绅。","自嫌林野疏顽迹，难预风流席上宾。"]},{"t":"酬王安之谢药栽二章 其二","f":"词","c":["护根带土我亲移，荷锸汲泉君自种。","悦目宁将恶草殊，扶危或比兼金重。"]},{"t":"酬王安之谢药栽二章 其一","f":"词","c":["洛人栽花不栽药，吾属好尚何其偏。","服之虽能已百疾，爱闲成僻无由痊。"]},{"t":"酬尧夫招看牡丹 其一","f":"词","c":["君家牡丹深浅红，二十四枝为一丛。","不唯春光占七八，才华自是诗人雄。"]},{"t":"酬次道板桥晚望见寄","f":"词","c":["春来曾约醉河桥，深负垂杨千万条。","今日都门相望处，西风乱叶正萧萧。"]},{"t":"静夜","f":"词","c":["午夜空斋四悄然，清寒透骨不成眠。","秋风故揭疏帘起，正漏月华来枕前。"]},{"t":"潮水 其二","f":"词","c":["淋淋出海门，百里雪花喷。","坐看东归去，平沙空有痕。"]},{"t":"潮水 其一","f":"词","c":["平江欲上潮，古木自萧萧。","两岸饶葭苇，寒波浸寂寥。"]},{"t":"醉","f":"词","c":["厚于太古暖于春，耳目无营见道真。","果使屈原知醉趣，当年不作独醒人。"]},{"t":"鹭鸶","f":"词","c":["清闲自合无忧累，白发何因更飒然。","遥望孤飞下秋水，雪花一片落晴天。"]},{"t":"丁尚书挽词二首 其二","f":"词","c":["丹阙晨趋退，萧然忘世荣。","闲斋虚自白，永日澹无营。","脱落簪缨累，沈冥丘壑情。","贪夫诚有激，千载素风清。"]},{"t":"丁尚书挽词二首 其一","f":"词","c":["凤跸游汾曲，非熊得伟人。","闺台尤显重，训诰愈深淳。","论道参黄阁，横经侍紫宸。","如何天不整，志业未全伸。"]},{"t":"九日怀聂之美 其一","f":"词","c":["钱唐江里扁舟上，别后篱花几度黄。","忧患萦心何缭绕，风光满目尽凄凉。","谁同凿落杯中酒，独系茱萸肘后囊。","可复无书道情素，云间空有雁南翔。"]},{"t":"九日怀聂之美 其二","f":"词","c":["太室横山蔽十里，相思空复上高台。","瓮头白酒行当熟，篱下黄花稍复开。","陶令不无同醉兴，孟君况有解嘲才。","欲凭西北高风势，飞度轘辕劝一杯。"]},{"t":"二十八日会不疑家席上纪实","f":"词","c":["召客客俱来，赏花花正开。","寒暄方得所，风雨不相催。","席上柳飞雪，门前车隐雷。","主人意仍厚，安得不徘徊。"]},{"t":"二月二日太常致斋晨起呈景仁次道二同舍","f":"词","c":["官舍春萧瑟，朝来尚薄寒。","人虽繁陌上，尘不近门端。","已负踏青约，仍无举白欢。","凭君御沟上，试折柳条看。"]},{"t":"二月三十日与同舍宴李氏园晚归马上赋诗","f":"词","c":["门前蹀躞金羁满，坐上连翩玉斝飞。","数尺游丝留客醉，一行垂柳送人归。","同邀胜友时难得，重到名园花已稀。","莫惜芳辰剩行乐，无端风雨横相违。"]},{"t":"八月十五日夜陪留守宣徽登西楼值雨待月久不见","f":"词","c":["经岁侍佳节，无如阴霭何。","果然时雨足，安用月华多。","未免银缸进，空闻玉漏过。","庾公兴不浅，久为驻鸣珂。"]},{"t":"八月五日夜省直","f":"词","c":["大火已西落，温风犹袭人。","留连惜纨扇，散诞脱纱巾。","蟾影夜色浅，蛩声秋意新。","图书足自适，何物更关身。"]},{"t":"八月七日夜省直苦雨三首 其三","f":"词","c":["菊蕊如排粟，青青见叶心。","未尝窥白日，何以散黄金。","攲侧疏篱短，绵延蔓草深。","寒蛩尔何与，终夕亦悲吟。"]},{"t":"八月七日夜省直苦雨三首 其二","f":"词","c":["怅望中秋月，于今已上弦。","明生圭样小，影露桂花偏。","幽思邈难致，浮云去不还。","何当出阴翳，清彻照中天。"]},{"t":"八月七日夜省直苦雨三首 其一","f":"词","c":["夜色槐阴重，雨声官舍寒。","野农安敢问，环堵未能完。","尽日流云度，何时大块乾。","正愁开霁晚，霜雾满红栏。"]},{"t":"又云新铸釜斛与今太府寺尺及权衡若合符契复次前韵","f":"词","c":["裁筒累黍久研精，况复新修釜斛成。","岂校忽微争口语，本期淳古变人情。","既言乐律符今尺，但恐箫韶似郑声。","若欲世人俱信服，凤凰再集颍川城。"]},{"t":"又代孙检讨作二首 其二","f":"词","c":["人为天地客，处世若浮休。","岂有生长在，祗知名可留。","露沾寒草晚，风啸白杨秋。","地下求文友，应从顾陆游。"]},{"t":"又击毬","f":"词","c":["肃奉乘轺命，仍陪戏马游。","朋分初迥出，势合复相收。","顾盼华星激，萦回紫电流。","良因重嘉好，礼接使臣优。"]},{"t":"又和二月五日夜风雪","f":"词","c":["春风正豪怒，夜雪复飘扬。","勿使羁愁乱，自知清兴长。","帘疏声淅沥，灯冷晕微茫。","此夕牛衣客，成名不可忘。"]},{"t":"又和六日四老会","f":"词","c":["萸房迎令节，菊蕊入芳筵。","华烛初长夜，清霜未冷天。","悲风咽横吹，骤雨送繁弦。","聊附邹枚客，敢希园绮贤。"]},{"t":"又和开叔","f":"词","c":["寒梅犯雪荣，大隐久专名。","异种生江渚，何年到洛城。","色如虚室白，香似主人清。","响使吴儿见，不思菰菜羹。"]},{"t":"又和安国寺及诸园赏牡丹","f":"词","c":["洛邑牡丹天下最，西南土沃得春多。","一城奇品推安国，四面名园接月波。","山相著书称上药，翰林弄笔作新歌。","人间朱粉无因学，浪把菱花百遍磨。"]},{"t":"又和来韵","f":"词","c":["年老逢春无用惊，对花弄笔眼犹明。","不嫌贫舍旧来燕，唤起醉眠何处莺。","一仆相随幅巾出，群童聚看小车行。","人间万事都损去，莫遣胸中气不平。"]},{"t":"又和留题定襄驿","f":"词","c":["按节羊肠阪，褰帷并塞州。","仁风熙爱日，清德凛高秋。","甘泽随征盖，华星近戍楼。","佗年叱驭事，直笔寄歆彪。"]},{"t":"又和雪霁","f":"词","c":["南宫来几时，挟纩易春衣。","意谓花将晚，何言雪尚飞。","夜声通旅枕，晓色弄晴晖。","继日劳王事，离离雁已归。"]},{"t":"又寄献","f":"词","c":["承明共直庐，瞬息八年馀。","幸托屏星驾，前迎使者车。","迹虽殊贵贱，心不置亲疏。","青眼披情素，犹如相见初。"]},{"t":"上巳日与太学诸同舍饮王都尉园","f":"词","c":["冠盖郁相依，名园花未稀。","游丝萦复展，狂絮堕还飞。","积弩遗风陋，兰亭旧俗微。","何如咏沂水，春服舞雩归。"]},{"t":"上元书怀","f":"词","c":["老去春无味，年年觉病添。","酒因脾积断，灯为目阿嫌。","势位非其好，纷华已久厌。","唯馀读书乐，暖日坐前檐。"]},{"t":"与乐道约会超化寺比至乐道以疾先归涂中有诗见寄","f":"词","c":["颠毛种种齿浮摇，屈指交游渐寂寥。","时较半朝非是晚，路无数里不为遥。","子猷垂到复归去，安道虽知未易邀。","古寺徘徊久东望，青春云日冷萧萧。"]},{"t":"久雨效乐天体","f":"词","c":["雨多虽可厌，气凉还可喜。","欲语口慵开，无眠身懒起。","一榻有馀宽，一饭有馀美。","想彼庙堂人，正应忧燮理。"]},{"t":"之美举进士寓京师此诗寄之","f":"词","c":["结发声华盛，无疑屈未伸。","何妨久垂翅，从此欲惊人。","鹰击天风壮，鹏飞海浪春。","行当解故褐，不惜化京尘。"]},{"t":"子高有徐浩诗碑昌言借摹其文甫及数本石有微衅惧而归之子高答简有碎珊瑚之戏昌言以诗赠子高同舍皆和","f":"词","c":["徐公精笔老生神，石刻犹能妙夺真。","几为通书翻丧宝，愈令好事惜传人。","锋铓半折犹能健，圭璧微瑕自足珍。","直使尽随如意碎，石家玉树未全贫。"]},{"t":"山中早春","f":"词","c":["山木欣欣意，春光次第催。","攲巾望归雁，伏槛听新雷。","岩静闻冰折，巢空喜燕来。","涧花从寂寞，亦向草堂开。"]},{"t":"山头春色","f":"词","c":["天意欲回煦，群生稍郁蒸。","平田犹未遍，绝岭独先升。","翠色添崖柏，寒声折涧冰。","谁为物外友，挈手共同登。"]},{"t":"出塞","f":"词","c":["边草荒无路，星河秋夜明。","卷旗遮远塞，歇马受降城。","霜重征衣薄，风高战鼓鸣。","将军功未厌，士卒不须生。"]},{"t":"马病","f":"词","c":["羸病何其久，仁心到栈频。","须怜苜蓿歉，当认主人贫。","客舍同萧索，山程共苦辛。","未能逢伯乐，且可自相亲。"]},{"t":"中秋夕始平公命与考校诸君置酒赋诗","f":"词","c":["月华秋色雨鲜新，万里澄空不受尘。","兔濯素毛腾浩露，桂飘香实下飞轮。","光侵酒面寒无力，清入诗豪健有神。","坐客何须辞醉倒，相君应不惜车茵。"]},{"t":"书事","f":"词","c":["志士喜功业，感时心易劳。","蘖栽终栝柏，荒蔓任蓬蒿。","梁竦慵为吏，萧咸耻诣曹。","风霜果不变，会见出云高。"]},{"t":"书楼","f":"词","c":["使君有书癖，记览浩无涯。","况此孤楼迥，端无外物哗。","横肱攲曲几，搔首落乌纱。","此趣人谁识，长吟窗日斜。"]},{"t":"云际亭","f":"词","c":["高齐杳冥际，迥与世尘违。","席上山河近，天边桑柘微。","人间已飘洒，栋里始纷霏。","草树收残照，逍遥久未归。"]},{"t":"五哀诗 马伏波","f":"词","c":["汉令班南海，蛮兵避郁林。","天涯柱分界，徼外贡输金。","坐失奸臣意，谁明报国心。","一棺忠勇骨，漂泊瘴烟深。"]},{"t":"五哀诗 李牧","f":"词","c":["椎牛飨壮士，拔距养奇材。","虏帐方惊避，秦金已闇来。","旌旗移幕府，荆棘蔓丛台。","部曲依稀在，犹能话郭开。"]},{"t":"五哀诗 屈平","f":"词","c":["白玉徒为洁，幽兰未谓芳。","穷羞事令尹，疏不忘怀王。","冤骨消寒渚，忠魂失旧乡。","空馀楚辞在，犹与日争光。"]},{"t":"五哀诗 晁大夫","f":"词","c":["人主恩犹盛，谗夫弄舌端。","旋闻就斧质，不得解衣冠。","反贼齿才冷，谋臣心尽寒。","晁宗噍类尽，汉室泰山安。"]},{"t":"仁宗皇帝挽歌词二首 其二","f":"词","c":["雾晓铜鱼跃，霜寒阊阖开。","哀声际海发，灵仗拂天来。","别寝严虚位，重阍閟夜台。","柏城空有路，无复属车回。"]},{"t":"仁宗皇帝挽歌词二首 其一","f":"词","c":["声教万馀里，文明四十春。","茂勋留信史，盛德满生民。","共适禽鱼乐，安知橐籥仁。","百年龙驭远，空复仰威神。"]},{"t":"六月十八日夜大暑","f":"词","c":["老柳蜩螗噪，荒庭熠耀流。","人情正苦暑，物怎已惊秋。","月下濯寒水，风前梳白头。","如何夜半客，束带谒公侯。"]},{"t":"双竹","f":"词","c":["双干标枯腹，青青凡几霜。","龙腾双角直，鲸喷两须长。","但欲寻支遁，安能问辟疆。","屡来非别意，未与此君忘。"]},{"t":"太皇太后挽歌词二首 其二","f":"词","c":["四纪袆衣盛，两朝长乐尊。","九州贡甘旨，万乘问晨昏。","明辟归元子，嘉谋赉孝孙。","群生资后土，难答化光恩。"]},{"t":"太皇太后挽歌词二首 其一","f":"词","c":["麟阁承家庆，轩星应德晖。","帝猷阴有补，嫔则动无违。","遽就苍梧野，空馀大练衣。","只应彤管在，万古播鸿徽。"]},{"t":"忆庞之道","f":"词","c":["畴昔两垂髫，知音结久要。","何言半涂别，不待岁寒彫。","幸有才名在，非随气运消。","英灵犹彷佛，宿草已萧萧。"]},{"t":"文太师挽歌三首 其三","f":"词","c":["夏屋封何处，山田有卧牛。","蟠根走伊水，回首负嵩丘。","忠孝家风备，哀荣礼秩优。","龙鸾舞宸翰，万古照松楸。"]},{"t":"文太师挽歌三首 其二","f":"词","c":["美化流民物，薰然遗爱多。","栾公当日社，邵父至今歌。","庭有三鳣集，门容驷马过。","欲知馀庆在，公鼎格平和。"]},{"t":"文太师挽歌三首 其一","f":"词","c":["汾晋地形美，古今多钜贤。","况承勋烈后，宜有庆灵传。","著位登朝古，声华出众先。","起家从此始，圭组遂蝉联。"]},{"t":"田横墓","f":"词","c":["昔时南面并称孤，今日还为绛灌徒。","忍死祗能添屈辱，偷生不足爱须臾。","一朝从殉倾群客，千古生风激懦夫。","直使强颜臣汉帝，韩彭未必免同诛。"]},{"t":"月下小饮","f":"词","c":["美景赏心相值难，良宵四座尽儒冠。","月华过冷衣襟润，酒力易消樽俎寒。","自有笑谈供逸气，不须丝竹借馀欢。","坊楼五鼓欲催曙，桂影长先高兴阑。"]},{"t":"王金吾北园","f":"词","c":["丞相后园天籞邻，年年分借上林春。","目前但识禽鱼乐，门外何妨车马尘。","花蘤祗疑名品尽，图书方验古今贫。","将军朝下无馀事，端为风烟作主人。"]},{"t":"长安送李尧夫同年","f":"词","c":["昔岁琼林花气曛，今朝长乐柳梢春。","事随流水滔滔度，鬓结繁霜戢戢新。","世路饱谙都是梦，人生可贵莫如身。","会须筑室临清洛，相与携筇戴葛巾。"]},{"t":"风","f":"词","c":["陇首红旌急，樽前翠幕重。","林端翻远刹，花外转疏钟。","夜寂清机发，春阑别意浓。","如何玉琴韵，并欲在青松。"]},{"t":"风雪数日不见叔度晚约公明共诣之 其一","f":"词","c":["云雪连朝闇，朋从叹坐违。","临文与谁共，开卷为君稀。","趣扫六花散，聊通一径微。","当携兔园赋，同映读书帏。"]},{"t":"东窗","f":"词","c":["临风梳短发，萧飒晚凉新。","不识市朝客，何如江海人。","沈吟凭棐几，攲侧带纱巾。","浊世事无尽，东窗聊放神。"]},{"t":"乐","f":"词","c":["吾心自有乐，世俗岂能知。","不及老莱子，多于荣启期。","缊袍宽称体，脱粟饱随宜。","乘兴辄独往，携筇任所之。"]},{"t":"乐轩","f":"词","c":["繁弦凝绿水，叠鼓掺渔阳。","风结舞初急，尘飞歌正长。","凫鹥争上下，栋宇为低昂。","太守且安坐，新声未遽央。"]},{"t":"代叔礼作使北诗","f":"词","c":["人主爱民物，心无彼此情。","约欢同一国，蒙福遍群生。","玉帛遥相望，风波寂不惊。","熙熙南北海，所至尽升平。"]},{"t":"北轩老杏其大十围春色向晚止开一花予悯其憔悴作诗嘲之","f":"词","c":["春木争秀发，嗟君独不材。","须惭一花少，强逐众芳开。","顽艳人谁采，微香蝶不来。","直为无用物，空尔费栽培。"]},{"t":"北京留守王太师挽歌词二首 其二","f":"词","c":["昔日程文士，中间侍坐宾。","游陪惭晚辈，待遇过它人。","方叹龙门远，俄惊马鬣新。","西园行乐处，引领但沾巾。"]},{"t":"北京留守王太师挽歌词二首 其一","f":"词","c":["卢肇时推重，终军众共贤。","何如夺标日，未及弃繻年。","官历清涂遍，名居美事先。","人间福有五，视履岂非全。"]},{"t":"去春与景仁同至河阳谒晦叔馆于府之后园既去晦叔名其馆曰礼贤梦得作诗以纪其事光虽愧其名亦作诗以继之","f":"词","c":["蓬飞匏系十馀年，并荫华榱出偶然。","郭隗金台虽见礼，华歆龙尾岂能贤。","浮云世味闲先薄，寒柏交情老更坚。","明日河梁即分首，人生乐事信难全。"]},{"t":"古松","f":"词","c":["摧颓岩壑间，磊落得天顽。","香叶低渐水，馀根倒挂山。","白猿窥子落，黄鹤认巢还。","不久应为石，莓苔旧已班。"]},{"t":"司徒开府韩国富公挽辞四首 其四","f":"词","c":["杖屦还私第，精诚在本朝。","爱君老不懈，忧国没方昭。","东阁秋牢落，西芒夜寂寥。","只应忠亮志，气运不能消。"]},{"t":"司徒开府韩国富公挽辞四首 其三","f":"词","c":["大吕功名重，鸿毛轩冕轻。","闲居客愈盛，暂出市皆倾。","溟海涵容大，龙门谒见荣。","谦光俨在目，恸哭望佳城。"]},{"t":"司徒开府韩国富公挽辞四首 其二","f":"词","c":["松漠骄无信，渔阳广聚兵。","移书侮中国，决意背齐盟。","直气轻轺入，英辞左衽惊。","虏归烽火灭，宇县复升平。"]},{"t":"司徒开府韩国富公挽辞四首 其一","f":"词","c":["天祐休明祚，时生隽杰臣。","贤科首多士，宰府泽生民。","焕烂三台正，冲融四海春。","欲知甄冶力，试问白头人。"]},{"t":"四月十三日立夏呈安之","f":"词","c":["留春春不住，昨夜的然归。","欢趣何妨少，闲游勿怪稀。","林莺欣有托，丛蝶怅无依。","窗下忘怀客，高眠正掩扉。"]},{"t":"平日游园常策筇杖秋来发箧复出貂褥二物皆景仁所贶睹物思人斐然成诗","f":"词","c":["筇杖携已久，貂褥展犹新。","渐染岷山雪，拂除京国尘。","危扶醉归路，稳称病来身。","赖此斋中物，时如见故人。"]},{"t":"归田诗 其一","f":"词","c":["秋水风波大，嗟嗟未可游。","渔樵自应乐，圭组为谁忧。","直木知先伐，明珠忌暗投。","果然钩可曲，不惜取封侯。"]},{"t":"归田诗 其四","f":"词","c":["松菊陶潜宅，蓬蒿仲蔚家。","行游筇杖瘦，啸傲幅巾斜。","屋小疏茅覆，门深乱柳遮。","村童迎客至，竹帚扫桃花。"]},{"t":"归田诗 其三","f":"词","c":["圣哲虽云远，遗文幸未亡。","沈冥观礼乐，彷佛见虞黄。","鸡黍延三径，琴书乐一堂。","逍遥名教内，富贵亦微茫。"]},{"t":"归田诗 其二","f":"词","c":["绂冕诚虚器，簪裳悉畏途。","触机身未保，好直道先孤。","甔石曾何有，田园浪更无。","可能推两耜，沮溺共为徒。"]},{"t":"正月二十四日夜雪","f":"词","c":["叠瓦浮轻雪，参差粉画难。","苦欺初变柳，故压未生兰。","夜色微分白，春容不受寒。","即为花卉夺，犹得暂供看。"]},{"t":"汉宫词","f":"词","c":["苜蓿花犹短，昌蒲叶未齐。","更衣过柏谷，走马宿棠梨。","逆旅聊怀玺，田间共斗鸡。","犹思饮云露，高举出虹蜺。"]},{"t":"玉徽亭","f":"词","c":["房公昔漂泊，置酒此鸣琴。","人事有忧乐，山光无古今。","风流俱寂寞，结构尚萧森。","松竹含虚籁，犹疑弦上音。"]},{"t":"龙门","f":"词","c":["石楼临晴空，南眺出千里。","人怜山气佳，予叹禹功美。","想彼未凿时，极目皆洪水。","谁知耕桑民，幸免鲂与鲤。"]},{"t":"仲庶同年兄自成都移长安以诗寄贺","f":"词","c":["蚕丛龟印解，鹑野隼旟新。","借问锦江乐，何如兴庆春。","骊歌遮去辙，竹马望行尘。","惠政如膏雨，遥知彼此均。"]},{"t":"伏蒙留守相公赐示陪太师潞公东田宴集诗辄敢属和","f":"词","c":["舞雩新雨浃公田，水满东溪上下天。","行径乍迂初见笋，浮舟正好未生莲。","弦收裂帛胡琴阕，袖结清风楚舞妍。","相国火城光满路，夜归不假玉蟾圆。"]},{"t":"伫月亭","f":"词","c":["灯火动鱼矶，湖边过鸟稀。","孤蟾久未上，五马不成归。","长啸风生座，高吟露满衣。","闲情无日厌，岸帻对清晖。"]},{"t":"先春亭","f":"词","c":["园林近铃阁，旦夕被仁风。","自得芳菲早，岂将疏远同。","冰开半塘绿，雨借数枝红。","会待韶光遍，还应到野丛。"]},{"t":"光诗首句云饱食复闲眠又成二章 其一 饱食","f":"词","c":["钱少何须万，杯多不过三。","龟肠本易足，熊掌讵宜贪。","散步竹斋外，高吟柳径南。","此心无所用，脱粟亦深惭。"]},{"t":"光顷为诸生常受经于钱丈学赋于张丈今乃叨忝同为侍臣蒙钱丈置酒张丈赐诗不胜愧悚之深言志为谢","f":"词","c":["畴昔胜冠日，曾为绛帐生。","九言闻至教，一顾得虚声。","不意叨严近，于今接老成。","宁须诗酒赐，侍坐导知荣。"]},{"t":"光皇祐二年谒告归乡里至治平二年方得再来怆然感怀诗以纪事","f":"词","c":["十六载重归，顺涂歌式微。","青松弊庐在，白首故人稀。","外饰服章改，流光颜貌非。","巫咸旧山色，相见尚依依。"]},{"t":"送龚章判官之卫州","f":"词","c":["几砚昔年游，于今成十秋。","松坚终发石，鱼变即辞流。","近郡无飞檄，清时不借筹。","淇园春竹美，军宴日椎牛。"]},{"t":"再和邵尧夫年老逢春","f":"词","c":["年老逢春犹解狂，行歌南陌上东冈。","晴云高鸟各自得，白日游丝相与长。","草色无情尽眼绿，花林多思袭人香。","吾侪幸免簪裾累，痛饮闲吟乐未央。"]},{"t":"再和伯常见寄","f":"词","c":["诛茅宋玉宅边人，知醉宜城几瓮春。","细雨短蓑渔向市，孤村极浦鼓迎神。","遍游七泽身忘倦，更赋千篇意转新。","不必沧浪羡清泚，向来缨上已无尘。"]},{"t":"华清宫","f":"词","c":["新丰鸡犬稀，蓟北马秋肥。","金殿翠华去，玉阶红叶飞。","荒林上路废，温谷旧流微。","嗟此非人事，何须问是非。"]},{"t":"同次道元日宿尚书省听戒誓寄常州卲不疑","f":"词","c":["椒花献岁新，瑄玉侍祠频。","此夕同华省，非才愧后尘。","江风迎茜旆，沙雨待朱轮。","不比斋宫冷，端居弃掷春。"]},{"t":"同宋次道陪宴琼林","f":"词","c":["冠盖连翩数里尘，帝家全借上林春。","鹓行不动烟霞秀，龙角正高雷雨新。","喜气晴曛宫树绿，飞花醉堕玉卮频。","蒲萄卢橘应相识，半是当年举酒人。"]},{"t":"吕宣徽挽歌二首 其二","f":"词","c":["维岳人皆仰，长城众所依。","远猷方克壮，昭世忽长违。","象设俨如在，英灵窅不归。","唯应令名久，竹素蔼馀辉。"]},{"t":"吕宣徽挽歌二首 其一","f":"词","c":["奕世台衡贵，盈门绂冕荣。","遐方流惠化，殊俗詟威声。","宥密资忠力，安平寄老成。","遽骑箕尾去，何以慰苍生。"]},{"t":"吕禄庙","f":"词","c":["赤帝祚四百，徒然诸吕谋。","出游逢友卖，未返见家收。","弊冢昔无记，遗祠今幸留。","士心俱左袒，何怨曲周侯。"]},{"t":"安之令子河阳官舍作蛙乐轩安之有诗寄题辄敢继和","f":"词","c":["鼓吹娱俗耳，蛙鸣惬雅怀。","最宜凉雨歇，更与晚风偕。","骥子方长骛，云衢偶未谐。","功名当努力，留此遗吾侪。"]},{"t":"安之朝议哀辞二首 其二","f":"词","c":["乐易春阳暖，孤高秋气清。","老惟知自适，贫不问为生。","京兆开阡贵，延陵题墓荣。","如何帝师笔，纯孝纪名卿。"]},{"t":"安之朝议哀辞二首 其一","f":"词","c":["场屋推声价，朝绅仰典型。","朱衣老卿列，白首恋亲庭。","舟壑一朝失，泉台万古扃。","音容宛在目，争免净飘零。"]},{"t":"庆文公八十会口号","f":"词","c":["元勋茂德古无伦，海内高闲第一人。","台席已酬调鼎志，磻溪还作钓鱼身。","师臣首冠三旌贵，岁历行开九十新。","愿过期颐跻上寿，飞觞四十有馀春。"]},{"t":"戏书宋子才止足堂","f":"词","c":["举世恋荣禄，夜行无乃劳。","独君年未至，止足一何高。","矮制乌纱帽，宽裁白氎袍。","华榱坐终日，闲按紫檀槽。"]},{"t":"戏呈尧夫","f":"词","c":["近来朝野客，无坐不谈禅。","顾我何为者，逢人独懵然。","羡君诗既好，说佛众谁先。","只恐前身是，东都白乐天。"]},{"t":"早行","f":"词","c":["寒犬吠柴门，荒鸡鸣远村。","河声空自急，月影不曾浑。","木末星犹白，榛中露已繁。","客心独惆怅，四顾与谁言。"]},{"t":"早春 其二","f":"词","c":["璿霄转斗车，春意逼梅花。","熟寐侵街鼓，闲情到酒家。","晴阳浮地末，寒色敛天涯。","归雁空馀迹，朝来印浦沙。"]},{"t":"早春寄东郡旧同僚","f":"词","c":["楼台带馀雪，寒色未全收。","久负入关意，空为同舍羞。","清樽接胜友，飞盖从贤侯。","应恨春来晚，烟林已数游。"]},{"t":"早朝书事","f":"词","c":["太白明如李，东方三丈高。","晨光孤照阙，雾气湿侵袍。","槐柳经霜惨，骅骝得路豪。","素餐无小补，俛仰愧金鳌。"]},{"t":"资善堂宴饯应诏","f":"词","c":["士论归清德，皇心重老成。","陈谟侍经席，得谢解尘缨。","坐密金章并，行徐玉醴清。","都门昔供帐，疏傅未为荣。"]},{"t":"次韵和王胜之十二月十五日朝退马上作","f":"词","c":["瓦沟微白雪光清，阙角初红海日腾。","尘息长街千骑入，鞘鸣深殿六龙升。","云岩有客空回首，圭荜何人尚曲肱。","自笑鲰生章绶缚，不容逃去正如罾。"]},{"t":"次韵和冲卿中秋胧月","f":"词","c":["岂无锦幄翠帘垂，匝树明灯正赫曦。","共惜月华方满夜，更当秋色中分时。","乌皮几稳风侵鬓，白玉楼高冷透肌。","千里浮云何处断，北来试问雁应知。"]},{"t":"次韵和江邻几九月五日省直","f":"词","c":["群驺布路歆，瘦马解鞍回。","雨阕虫声乐，秋深菊意催。","图书纷自适，僚友邈谁陪。","何以消寒夜，残醪不满杯。"]},{"t":"次韵谢杜祁公借观五老图","f":"词","c":["脱遗轩冕就安闲，笑傲丘园纵倒冠。","白发忧民虽种种，丹心许国尚桓桓。","鸿冥得路高难慕，松老无风韵自寒。","闻说优游多唱和，新篇何惜画图看。"]},{"t":"祁国正献公挽歌三首 其三","f":"词","c":["先子同乌府，知音诚皦然。","脱缞来拜伏，抚首辱哀怜。","迨此泉扃掩，空悲尘网牵。","无由怀酒絮，撇涕望新阡。"]},{"t":"祁国正献公挽歌三首 其二","f":"词","c":["钧玉吴台旧，诛茅梁苑新。","位登华衮贵，家似布衣贫。","直道高当世，清风遗后人。","千秋寒照目，竹帛不栖尘。"]},{"t":"祁国正献公挽歌三首 其一","f":"词","c":["舟楫才猷大，冰霜德操坚。","陶钧成茂业，书史乐高年。","瞻望簪绅共，吁嗟馆舍捐。","举时无异论，方信令名全。"]},{"t":"竹坞","f":"词","c":["二何迹相继，竹坞日阴森。","欲识养民意，先观爱物心。","低垂樽俎冷，密映管弦深。","勿怪湖光少，年来碧影侵。"]},{"t":"自嘲","f":"词","c":["英名愧终贾，高节谢巢由。","直取云山笑，空为簪组羞。","浮沈乖俗好，隐显拙身谋。","惆怅临清鉴，霜毛不待秋。"]},{"t":"自嘲","f":"词","c":["盘飧罗新蔬，充腹不求馀。","穷巷昼扃户，闲轩卧读书。","有心齐塞马，无意羡川鱼。","世道方邀逐，如君术已疏。"]},{"t":"致政王侍郎挽歌二首 其二","f":"词","c":["振鹭辞灵沼，冥鸿翔太虚。","清朝解鸣玉，旧里挂安车。","诗酒江山胜，园林俸禄馀。","所忠今不往，谁奏茂陵书。"]},{"t":"致政王侍郎挽歌二首 其一","f":"词","c":["弱冠献奇策，居然终贾才。","赋成平乐馆，歌奉柏梁杯。","丽藻留昭世，英游隔夜台。","土中埋美玉，谁见不兴哀。"]},{"t":"西湖","f":"词","c":["佳丽三吴国，湖光荡日华。","鱼惊动蘋叶，燕喜掠杨花。","云过山腰黑，风驱雨脚斜。","烟波遥尽处，彷佛见渔家。"]},{"t":"西溪公宴 其二","f":"词","c":["谢守爱山水，军城况不赊。","鱼惊避落叶，鸟倦立浮查。","古柏依冈远，垂杨带岸斜。","秋风吹急管，一曲度荷花。"]},{"t":"西溪公宴 其一","f":"词","c":["五马非从乐，西城念劝功。","翠帷低映水，红旆不胜风。","叶脱青山静，云归碧落空。","淹留尽佳兴，新月渐朦胧。"]},{"t":"初到洛中书怀","f":"词","c":["三十馀年西复东，劳生薄宦等飞蓬。","所存旧业惟清白，不负明君有朴忠。","早避喧烦真得策，未逢危辱好收功。","太平触处农桑满，赢取闾阎鹤发翁。"]},{"t":"别一章改韵同五诗呈尧夫","f":"词","c":["家虽在城阙，萧瑟似山阿。","远去名利窟，自称安乐窝。","云归白石洞，鹤立碧松柯。","得丧非吾事，何须更寤歌。"]},{"t":"别聂之美","f":"词","c":["客宦常漂泊，离怀徒自劳。","贫无衣换酒，空有涕沾袍。","木叶寒犹在，江湖暮更豪。","行舟远不见，赖有片帆高。"]},{"t":"别韵一首","f":"词","c":["风日虽寒昼景长，探春远访白莲庄。","岸冰犹在水先绿，柳叶未生条已黄。","老木根侵苔径窄，新梅花入酒卮香。","天真不必人修饰，得趣勿嫌台馆荒。"]},{"t":"君贶环溪","f":"词","c":["地胜风埃外，门深花竹间。","波光冷于玉，溪势曲如环。","荣路回翔厌，华轩啸咏闲。","堪羞谢太傅，不复到东山。"]},{"t":"吴正肃公挽歌辞三首 其三","f":"词","c":["念昔少年日，谬登君子堂。","重言何以称，厚德不能忘。","玉麈声容在，泉台岁月长。","凭谁寄清泪，为我洒松冈。"]},{"t":"吴正肃公挽歌辞三首 其二","f":"词","c":["辞华已独步，政治复无前。","吏不容三穴，民皆戴二天。","于今知和寡，自古愧才偏。","惆怅棠阴下，仁风尚蔼然。"]},{"t":"吴正肃公挽歌辞三首 其一","f":"词","c":["皇家延茂异，鹗立迥无伦。","高议谁能夺，英才自有真。","骅骝宁受絷，水鉴不栖尘。","试为咨清论，风流第几人。"]},{"t":"宋相国公挽辞二首 其二","f":"词","c":["邦光华衮襚，家宝素书陈。","东阁簪裾散，西芒宅兆新。","泉台无复晓，柏径不知春。","独有高文在，芬芳继古人。"]},{"t":"宋相国公挽辞二首 其一","f":"词","c":["仁圣初承绪，敷天吁隽贤。","得人兹最盛，射策独居先。","禁省英声远，岩廊至化宣。","辞荣还故第，三事究高年。"]},{"t":"张元常挽歌二首 其二","f":"词","c":["秀眉无足验，结轖遽为灾。","乡曲三年别，江山万里回。","林闾飞旐入，书剑逐舟来。","坟草枯还绿，重泉不复开。"]},{"t":"张元常挽歌二首 其一","f":"词","c":["为吏文无害，临民政不苛。","浑金生自美，古井澹无波。","方喜风鹏举，旋闻隙驷过。","善人宜寿考，报施定如何。"]},{"t":"李花","f":"词","c":["嘉李繁相倚，园林淡泊春。","齐纨剪衣薄，吴纻下机新。","色与晴光乱，香和露气匀。","望中皆玉树，环堵不为贫。"]},{"t":"杏解嘲","f":"词","c":["造物本非我，荣枯那足言。","但馀良干在，何必艳花繁。","壮丽华林苑，欢娱梓泽园。","芳菲如可采，岂得侍君轩。"]},{"t":"沉阴欲雪与同列会饮南斋","f":"词","c":["簿领日沈迷，从容乐事稀。","宾朋幸相值，樽酒不须违。","惨澹愁云积，参差远树微。","淹留勿轻散，待取雪花飞。"]},{"t":"花庵多牵牛清晨始开日出已瘁花虽甚美而不堪留赏","f":"词","c":["望远云凝岫，妆馀黛散钿。","缥囊承晓露，翠盖拂秋烟。","响慕非葵比，彫零在槿先。","才供少顷玩，空废日高眠。"]},{"t":"花庵独坐","f":"词","c":["荒园才一亩，意足已为多。","虽不居丘壑，常如隐薜萝。","忘机林鸟下，极目塞鸿过。","为问市朝客，红尘深几何。"]},{"t":"苏才翁子美有赠扶沟白鹤观黄道士诗纪于屋壁岁久漫灭今县宰周同年得完本于民间抵予求诗","f":"词","c":["潦倒黄冠无足论，白头嗜酒住荒村。","狂名偶为留诗著，陈迹仍因好事存。","金石锵洋虚殿寂，龙蛇洒落古墙昏。","飞黄灭没浮云外，疲马何能望骏奔。"]},{"t":"运使虞部按行洛西诸县因游所过名山有诗百馀首合为一编蒙赐宠示俾之继作一首","f":"词","c":["属城穷僻地，揽辔遍周流。","弊政已更化，名山不废游。","鸣驺留谷口，轻屐历岩幽。","聚看官仪者，相扶半白头。"]},{"t":"还陈殿丞原人论","f":"词","c":["品物芸芸游太虚，不知谁氏宰洪炉。","一株花落分荣辱，万窍风号见有无。","觉后共占犹是梦，衣中所得亦非珠。","何如鼓瑟浴沂水，春服成时咏舞雩。"]},{"t":"还张景昱景昌秀才兄弟诗卷","f":"词","c":["韡韡新诗卷，青春映棣华。","机云今继美，载协旧承家。","幸托仁人里，时回长者车。","白虹光乱眼，何敢议瑜瑕。"]},{"t":"邵尧夫先生哀辞二首 其二","f":"词","c":["慕德闻风久，论交倾盖新。","何须半面旧，不待一言亲。","讲道切磋直，忘怀笑语真。","重言蒙蹠实，佩服敢书绅。"]},{"t":"邵尧夫先生哀辞二首 其一","f":"词","c":["菽藿一箪乐，蒿莱三亩宽。","蒲轮不能起，瓮牖有馀安。","高节去圭角，久要敦岁寒。","今朝郊外客，谁免涕汍澜。"]},{"t":"闰正月十五日夜监直对月怀诸同舍 其二","f":"词","c":["澹薄春云散，低昂北斗横。","微分汉津雁，静识建章更。","浊酒怜虚爵，高文忆友生。","前轩空不掩，怅息负孤清。"]},{"t":"闲中有富贵","f":"词","c":["闲中有富贵，迥与俗尘殊。","水净齐纨展，花繁蜀锦纡。","竹风寒扣玉，荷雨急跳珠。","可笑公孙衍，酣歌誇丈夫。"]},{"t":"闲来","f":"词","c":["闲来观万物，在处可逍遥。","鱼为贪钩得，蛾因赴火焦。","碧梧饥鸑鷟，白粒饱鹪鹩。","带索谁家子，行歌复采樵。"]},{"t":"闲居呈复古","f":"词","c":["闲居虽懒放，未得便无营。","伐木添山色，穿渠擘水声。","经霜收芋美，带雨接花成。","前日邻翁至，柴门扫叶迎。"]},{"t":"依前韵奉送才元和甫使北","f":"词","c":["析木带天津，华星随去人。","扬旌踰绝漠，负弩候前尘。","出塞风霜苦，归涂杨柳春。","会书专对美，烨烨满秋筠。"]},{"t":"依韵和仲庶省壁画山水","f":"词","c":["画工执笔已心游，稍稍蘅皋引杜洲。","堆案烦文犹倦暑，满轩新意忽惊秋。","天生贤者非无谓，官遇明时未易休。","正恐怒飞朝暮事，丹青难得久淹留。"]},{"t":"其夕宿独乐园诘朝将归赋诗","f":"词","c":["平晓何人汲井华，辘轳声急散春鸦。","开园更有四五日，映叶尚馀三两花。","宿病岑岑犹带酒，无眠耿耿不禁茶。","自嫌行乐妨年少，遽索蓝舆且向家。"]},{"t":"到任明年旨罢官有作","f":"词","c":["恬然如一梦，分竹守长安。","去日冰犹壮，归时花未阑。","风光经目少，惠爱及民难。","可惜终南色，临行子细看。"]},{"t":"到并州已复数月率尔成诗","f":"词","c":["忽忽此何地，经时更自猜。","深疑醉里得，复似梦中来。","薄宦真何益，浮生信可咍。","鹏蜩定有分，不若寸心灰。"]},{"t":"和子华应天院行香归过洛川","f":"词","c":["印节传呼洛北还，府庭无讼不妨闲。","度桥寒色侵春服，按辔晴光露晓山。","香穗徘徊凝广殿，花篮繁会满通阛。","自知白雪高难和，忍愧谁能寄我颜。"]},{"t":"和子华招潞公暑饮","f":"词","c":["朱门近在府园东，杖屦过从跬步中。","避暑连翩投辖宴，析酲萧洒满襟风。","闲来高韵浑如鹤，醉里朱颜却变童。","剪烛添香欢未极，但惊铜漏太匆匆。"]},{"t":"和子骏约游一二园亭看花遇雨而止","f":"词","c":["行乐及佳时，官闲无所羁。","只知花正发，不共雨为期。","浅草碧无际，浓云冷四垂。","陪游兴未尽，安得不相思。"]},{"t":"和子骏洛中书事","f":"词","c":["西都自古繁华地，冠盖优游萃五方。","比户清风人种竹，满川浓绿土宜桑。","凿龙山断开天阙，导洛波回载羽觞。","况有耆英诗酒乐，问君何处不如唐。"]},{"t":"和子骏新荷","f":"词","c":["懒不窥园久，元非效仲舒。","新荷满沼密，蓝舁出门疏。","借问含烟晚，能胜裛露初。","愧无鱼戏句，弄翰白纷如。"]},{"t":"和子渊元夕","f":"词","c":["神岳嶕峣阙角齐，银蟾无影玉绳低。","风传丝管交加发，灯滉星河上下迷。","清醴横飞金凿落，香尘不染锦障泥。","谁知此夕斋祠客，近在宫城槐柳西。"]},{"t":"和子渊除夜","f":"词","c":["缇室重飞玉琯灰，物华全与斗杓回。","依依残腊无情别，历历新春满眼来。","强取酒卮浮翠柏，懒开粽叶觅杨梅。","男儿努力平生志，肯使功名落草莱。"]},{"t":"和公廙喜雪","f":"词","c":["向来河洛久愆阳，祷祀徒劳罄肃庄。","林雪飞花欣暂白，麦田濡叶未全黄。","城中稍觉桑薪贵，村外时闻社瓮香。","八使孜孜悯茕独，斯民那复畏凶荒。"]},{"t":"和王少卿十日与留台国子监崇福宫诸官赴王尹赏菊之会","f":"词","c":["儒衣武弁聚华轩，尽是西都冷落官。","莫叹黄花过佳节，且将素发共清欢。","红牙板急弦声咽，白玉舟横酒量宽。","青眼主公情不薄，一如省闼要人看。"]},{"t":"和王安之题独乐园","f":"词","c":["草浓初过雨，林静远含烟。","燕引新飞鷇，荷承半坠莲。","朋来惟有月，山见不须钱。","谁与同其乐，壶中浊酒贤。"]},{"t":"和乐道再以诗见寄","f":"词","c":["谏垣簪笔接英游，今日华颠昔日忧。","邂逅升沈皆是命，逍遥出处本无愁。","衡门不羡金门贵，藿食焉知肉食谋。","溟海榆枋各安分，蓬莱未必胜嵩丘。"]},{"t":"和乐道自河外南辕过宜芳雨晴和气景物可爱马上偶成","f":"词","c":["京洛春应老，河边初解颜。","碧浮烟际草，翠滴雨馀山。","目极褰帷外，诗成揽辔间。","满川桃李色，共喜传车还。"]},{"t":"和史诚之谢送张明叔梅台三种梅花","f":"词","c":["别后相惊两鬓霜，可怜梅蕊为谁芳。","台头日暖分三色，林下风清共一香。","正烂漫时游不足，忽离披去乐难常。","慇勤手折遥相赠，不欲花前独举觞。"]},{"t":"和白都官见赠","f":"词","c":["齿疏鬓白两眸昏，万事无堪老病身。","脱粟犹沾太仓禄，法官仍忝外台臣。","直缘迂僻求闲地，岂是孤高慕古人。","英俊满朝皆稷契，太山何少一飞尘。"]},{"t":"和冲卿喜雨偶成","f":"词","c":["万里风随快雨来，尘昏消伏旱光开。","物情濯热参差喜，天意为仁容易回。","帘映薄寒灯有晕，窗含虚白麝成煤。","君侯雅有江湖兴，萧洒何须气象催。"]},{"t":"和刘伯寿陪潞公禊饮","f":"词","c":["旌幢车骑满沙头，鼓吹喧繁画鹢浮。","十里罗纨光照地，千家帘幕远临流。","觞随洛水周公事，月映凤楼裴相游。","令典久堕今更举，行闻美俗遍中州。"]},{"t":"和同舍对菊无酒","f":"词","c":["黄花倚秋色，晔晔为谁开。","更使窥残榼，空令洗旧杯。","嗅香行缭绕，撚蕊立徘徊。","尽日柴门外，白衣来不来。"]},{"t":"和宇文公南涂中见寄","f":"词","c":["骢马乌纱游洛尘，未能全得自由身。","深惭白首恋微禄，不向青山为散人。","斥鴳卑飞聊取适，冥鸿高举益难亲。","蜀都迢递千馀里，徒诵新诗妙入神。"]},{"t":"和安之久雨","f":"词","c":["秋霖逢甲子，禾耳恐须生。","流俗幸无验，高田犹有成。","润唯藜莠得，烂与蕙兰并。","早晚浮云豁，逍遥赋晚晴。"]},{"t":"和尧夫见寄 其二","f":"词","c":["仁政如慈父，蒲人得所依。","教条前后接，风迹古今稀。","试郡才书最，还朝必奋飞。","西台旧班列，犹望绣衣归。"]},{"t":"和尧夫见寄 其一","f":"词","c":["志趣苦难合，伥伥何所依。","逢君始相照，知我信为稀。","忽报除书下，徒瞻征盖飞。","相思千里远，洛浦又春归。"]},{"t":"和尧夫首尾吟","f":"词","c":["尧夫非是爱吟诗，安乐窝中无所为。","古道白头无外用，今时青眼几人知。","嵩山洛水长相见，秋月春风不失期。","筋力虽衰才思壮，递年比较未尝亏。"]},{"t":"和次道大庆殿上元迎驾","f":"词","c":["凤律年华到尚新，九重气象已成春。","晓云低拂羽林仗，宿雨先清紫陌尘。","玉殿鸣鞘传警跸，彤庭委佩集簪绅。","阙前无复鱼龙戏，自有驩谣亿万人。"]},{"t":"和宋次道西都元日怀不疑并见寄","f":"词","c":["露冕优分竹，题舆佐画圻。","比年携手乐，兹日赏心违。","斋祀春来并，娱游别后稀。","谁怜从窭卒，草际犯寒归。"]},{"t":"和邠守宋度支来卜居与南园为邻","f":"词","c":["弱冠交游鬓发苍，饱谙官况好深藏。","闲居共买一廛地，尽老常依数仞墙。","虽喜卜邻同晏子，尚惭推宅异周郎。","何时税此凭熊驾，倚仗相迎立路傍。"]},{"t":"和伯常自郢州见寄","f":"词","c":["西郊去岁揖行人，柳暗花浓又一春。","坐想高风清入骨，沉吟佳句健生神。","潺湲杳霭烟波古，散诞逍遥兴趣新。","应笑洛阳车马道，缁衣未免化红尘。"]},{"t":"和伯镇再入馆","f":"词","c":["甘泉献赋人，流落浙江滨。","自叹三年谪，归来万事新。","铨衡时进对，户牖日相亲。","明主方思贾，非徒问鬼神。"]},{"t":"和君贶少林寺","f":"词","c":["达磨自云传佛心，绪言迷世到于今。","既携只履归西域，安得遗灵在少林。","孤月正明高殿冷，清风不断老松深。","谢公自爱山泉美，肯为幽禅此访寻。"]},{"t":"和君贶寄河阳侍中牡丹","f":"词","c":["真宰无私妪煦同，洛花何事占全功。","山河势胜帝王宅，寒暑气和天地中。","尽日玉盘堆秀色，满城绣毂走香风。","谢公高兴看春物，倍忆清伊与碧嵩。"]},{"t":"和君贶任少师园赏梅","f":"词","c":["寒压春头草未芽，喜闻置酒赏新葩。","官仪赫奕三川守，野意萧疏四皓家。","不用管弦妨淡泊，岂容桃李竞繁华。","昏鸦散乱传呼出，归路林间烛影斜。"]},{"t":"和君贶暮秋四日登石家寺阁晓泛洛舟 登阁","f":"词","c":["嬉游乘晓霁，登览犯秋寒。","不出埃尘外，安知在壤宽。","宫前断山碧，林表落霞丹。","欲下惜佳趣，相留更倚栏。"]},{"t":"和君贶题潞公东庄","f":"词","c":["嵩峰远叠千重雪，伊浦低临一片天。","百顷平皋连别馆，两行疏柳拂清泉。","国须柱石扶丕构，人待楼航济巨川。","萧相方如左右手，且于穷僻置闲田。"]},{"t":"和君锡雪后招探春 其二","f":"词","c":["繁霙回夜色，凌乱落春云。","虚幌寒相袭，华堂静不闻。","玉卮深可敌，银烛近微分。","谁念牛衣客，穷经白发纷。"]},{"t":"和吴仲庶寄吴瑛比部安道之子壮年致政归隐蕲春","f":"词","c":["负米承亲愿已赊，耻随鸡鹜啄泥沙。","一朝投绂真高士，万卷藏书旧世家。","齿发未衰非药物，山林不返为云霞。","庞眉尚有郎潜者，徇禄忧生直可嗟。"]},{"t":"和吴辨叔知凤翔见寄","f":"词","c":["岐阳府舍始相逢，四十馀春屈指中。","昔日布衣今露冕，当时小吏亦衰翁。","醉吟久作藏身计，条教应多及物功。","惟是綵衣难再著，长林极目起悲风。"]},{"t":"和宋子才致仕后岁旦见赠","f":"词","c":["闲官逢献岁，拜揖亦纷然。","须信家居日，方为已有年。","劬劳中外遍，名迹始终全。","伯玉空搔首，蹉跎愧在前。"]},{"t":"和张文裕初寒十首 其十","f":"词","c":["何处初寒好，初寒福善居。","长宵对灯火，满室聚诗书。","暂息登山屐，休脂下泽车。","所安容膝地，何必更多馀。"]},{"t":"和张文裕初寒十首 其九","f":"词","c":["何处初寒好，初寒游弈园。","林间叶未尽，篱底菊犹存。","结竹为庵小，开炉构火温。","谁言处城市，岑寂似丘樊。"]},{"t":"和张文裕初寒十首 其八","f":"词","c":["何处初寒好，初寒肃政台。","官闲免簿领，门静少尘埃。","天借风霜气，人无鹰隼猜。","庭荒馀老柏，尚有夕乌来。"]},{"t":"和张文裕初寒十首 其七","f":"词","c":["何处初寒好，初寒叠石溪。","山斜改昏晓，路曲失东西。","拾栗走村稚，凿垣巢乳鸡。","我来闲拥褐，曝背草檐低。"]},{"t":"和张文裕初寒十首 其六","f":"词","c":["何处初寒好，初寒喷玉泉。","折冰流谷口，飞溜落云边。","雀噪聚林杪，樵歌下石巅。","寻幽不思返，坐啸夕阳偏。"]},{"t":"和张文裕初寒十首 其五","f":"词","c":["何处初寒好，初寒禹凿门。","遥天露崖口，轻浪漱山根。","万佛龛苔老，一灯林霭昏。","渔梁杳相望，石濑夜声喧。"]},{"t":"和张文裕初寒十首 其四","f":"词","c":["何处初寒好，初寒太室山。","晴空烟澹泊，返照雪孱颜。","极目雁稍没，无心云自还。","犹馀拜表累，不得坐松间。"]},{"t":"和张文裕初寒十首 其三","f":"词","c":["何处初寒好，初寒洛水桥。","沙痕水清浅，风叶柳萧条。","关塞长涂直，嵩丘倒影遥。","凤楼虽在北，车马不尘嚣。"]},{"t":"和张文裕初寒十首 其二","f":"词","c":["何处初寒好，初寒洛汭宫。","翠华虽脉脉，佳气自葱葱。","阙角月华白，苑墙霜叶红。","都人心望幸，注目不离东。"]},{"t":"和张文裕初寒十首 其一","f":"词","c":["何处初寒好，初寒郏鄏城。","垂绅多俊彦，列第尽公卿。","裘马过从盛，门阑洒扫清。","谁家拥兽炭，尽日管弦声。"]},{"t":"和李八丈小雪同会有怀邻几","f":"词","c":["天禄淹回德齿尊，暂留汾曲两朱轓。","闲轩坐啸正飞雪，同舍倦游来及门。","空叹高歌如郢客，愧无佳赋似文园。","坐中犹欠邻几在，深负棋枰与酒樽。"]},{"t":"和李殿丞仓中对菊 其三","f":"词","c":["凉风正萧瑟，好月复徘徊。","幽兴眇不尽，芳樽时一开。","馀英盖红叶，坠露湿苍苔。","从此东篱下，应忘归去来。"]},{"t":"和李殿丞仓中对菊 其二","f":"词","c":["文案渐消散，仓闲吏已稀。","庭空数蝶下，夜静一萤飞。","爱赏忽成句，淹留时忘归。","高情虽不系，遇此独依依。"]},{"t":"和李殿丞仓中对菊 其一","f":"词","c":["高士寄朝市，迥然心迹殊。","秋风太仓里，黄菊满庭隅。","陶令成诗后，王公送酒无。","遥知厌俗事，未免强踌蹰。"]},{"t":"和杨卿中秋月","f":"词","c":["秋气平分夜，沈阴乍散天。","窥林初淡薄，照席忽孤圆。","泠入诗毫健，光浮醉弁偏。","嘉宾勿轻去，桂影正娟娟。"]},{"t":"和运使舍人北园饯别行憩三交僧舍冒雪宿百井关见寄","f":"词","c":["骊驹北上雪孱颜，韊矢前驱度汉关。","僧室松杉清照眼，驿亭烟火迥依山。","马衔边草枯犹瘦，雁怯胡云冷未还。","贱子不须回首问，鬓毛萧飒簿书间。"]},{"t":"和邵尧夫安乐窝中职事吟","f":"词","c":["灵台无事日休休，安乐由来不外求。","细雨寒风宜独坐，暖天佳景即闲游。","松篁亦足开青眼，桃李何妨插白头。","我以著书为职业，为君偷暇上高楼。"]},{"t":"和邵尧夫年老逢春","f":"词","c":["年老逢春春莫咍，朱颜不肯似春回。","酒因多病无心醉，花不解愁随意开。","荒径倦游从碧草，空庭慵扫自苍苔。","相逢谈笑犹能在，坐待牵车陌上来。"]},{"t":"和江邻几金铃菊","f":"词","c":["何处见佳菊，秋风汶水阳。","酒浮金铎细，露泛蜜房香。","不谓红尘地，相逢君子堂。","依然故人意，不减旧芬芳。"]},{"t":"和国子夏主簿李花","f":"词","c":["儒宫岑寂觉春闲，仙李繁花重压栏。","碎锦不飞蒙树合，素云攲亚举枝难。","能诗此日当推谢，捧赐他年足继桓。","更约雕盘荐秋实，岂徒秾艳一朝看。"]},{"t":"和始平公长句寄汉州何学士","f":"词","c":["势交倏忽易萧条，赖有伊人尚建标。","须信松筠凌雪茂，肯为蒲柳望秋凋。","钦贤高馆三年别，广汉专城百舍遥。","书纸如云诗叩玉，数凭疾翼度青霄。"]},{"t":"和始平公郡斋偶书二首 其二","f":"词","c":["平安候火出云间，区脱无尘刁斗闲。","汉相威声遥制敌，胡兵远迹夜开关。","赤松雅意思轻举，黄阁群心望复还。","玉帐牙旗空壮观，谢公高兴在东山。"]},{"t":"和始平公郡斋偶书二首 其一","f":"词","c":["文武从容两有馀，公槐将幕往来居。","已安四海如三杰，欲散千金比二疏。","今日监边亲跪毂，佗年入殿赐乘车。","武侯暂为苍生起，长忆隆中卧旧庐。"]},{"t":"和始平公梦中有怀归之念作诗始得两句而寤因足成一章","f":"词","c":["元宰抚洪钧，四海可熏灼。","至人养天真，视此犹婴缚。","出入金鼓威，寤寐琴樽乐。","乃知伊吕心，未始忘丘壑。"]},{"t":"和昌言官舍十题 其四 萱草","f":"词","c":["叶濯宿露翠，花迎朝日黄。","昔谁封殖此，俨列侍高堂。","达士隐于吏，孰为行与藏。","逍遥玩永日，自无忧可忘。"]},{"t":"和明叔九日","f":"词","c":["不奈衰须白，羞看朝鉴明。","聊凭佳节酒，强作少年情。","雨冷弊裘薄，风高醉帽倾。","如何不行乐，况复值秋成。"]},{"t":"和明叔游白龙溪","f":"词","c":["溪深荒径微，寻胜不知疲。","寒月影随马，晓风冰满髭。","行歌被褐叟，聚戏拾薪儿。","外野饶真趣，令人怀抱夷。"]},{"t":"和范景仁谢寄西游行记 其二","f":"词","c":["八水三川路渺茫，翠微深处白云乡。","目■懒拭如松液，领发频抓似栗房。","林壑不嫌无用物，形骸难入少年场。","缘苔蹑蔓知多少，千里归来屐齿苍。"]},{"t":"和范景仁谢寄西游行记 其一","f":"词","c":["洛川秦野郁相望，风物山河旧帝乡。","涧底逢人问樵径，松间系马宿僧房。","恨无同好携三雅，共讲前闻醉百场。","历遍胜游翻怅望，日边回首远烟苍。"]},{"t":"和复古小园书事","f":"词","c":["饱食复闲眠，风清雨霁天。","叶深时坠果，岸曲乍藏莲。","波面秋光净，林梢夕照鲜。","东家近亦富，满地布苔钱。"]},{"t":"和赵子舆龙州吏隐堂","f":"词","c":["四望逶迤万叠山，微通云栈落尘寰。","谁知吏道自可隐，未必仙家有此闲。","酒熟何人能共醉，诗成无事复相关。","浮生适意即为乐，安用腰金鼎鼐间。"]},{"t":"和吴朝议同年谢光与景仁同年见过","f":"词","c":["结绶东堂同发策，白头相值益相亲。","却思景祐无多日，共见元丰有几人。","天下高名归广受，古来交道重雷陈。","谢公身老才方壮，落笔成章字字新。"]},{"t":"和留守相公九月八日与潞公宴赵令园有怀去年与景仁秉国游赏","f":"词","c":["今岁台星聚洛中，甘棠前后雨阴浓。","英辞唱和诗千首，高宴游陪禄万钟。","木末霜繁花未落，云间字小雁相从。","西湖在望亲朋远，节物那堪处处逢。"]},{"t":"和聂之美雁","f":"词","c":["汲汲复栖栖，往来谁与期。","映云才可见，入雾杳难追。","羁枕梦初断，寒闺涕已危。","冥冥远缯缴，愧尔独知时。"]},{"t":"和钱学士呈邵兴宗","f":"词","c":["霜露苍苍宰树高，累茵列鼎重鸿毛。","蒹葭自幸犹依玉，髋髀何能学奏刀。","才薄无由禆覆焘，命奇不得报劬劳。","平生念此心先乱，蓼蓼难分莪与蒿。"]},{"t":"和景仁卜居许下","f":"词","c":["壮齿相知约岁寒，索居今日鬓俱斑。","拂衣已解虞卿印，筑室何须谢傅山。","许下田园虽有素，洛中花卉足供闲。","他年决意归何处，便见交情厚薄间。"]},{"t":"和范景仁夜读试卷","f":"词","c":["案前官烛堕花频，满目高文妙入神。","勇气先登势无敌，巧心后发语尤新。","好贤何啻三薰贵，求宝方知百汰真。","愚鲁自非凭骥发，昆山千里到无因。"]},{"t":"和景仁闻蝉","f":"词","c":["春林满岩绿，谁信已鸣蝉。","叶上正多露，山中别有天。","心闲宁感物，道合况忘年。","坐听生秋思，何须膝上弦。"]},{"t":"和景仁琼林席上偶成","f":"词","c":["念昔琼林赐宴归，綵衣绿绶正相宜。","将雏虽复慰心喜，负米翻成触目悲。","殿角花犹红胜火，樽前发自白如丝。","桂林衰朽何须恨，幸有新枝续旧枝。"]},{"t":"和景仁答才元寄示花图","f":"词","c":["高士闲居旧，名花独步今。","移从洛浦远，濯自锦江深。","传得巫山貌，非因延寿金。","不须天女散，已解动禅心。"]},{"t":"和道矩送客汾西村舍杏花盛开置酒其下","f":"词","c":["田家繁杏压枝红，远胜桃夭与李秾。","何事偏宜闲处植，无端复向别时逢。","林间暂系黄金勒，花下聊飞码碯钟。","会待重来醉嘉树，只愁风雨不相容。"]},{"t":"和王道粹垂拱早朝王范二直阁班列在前戏成小诗","f":"词","c":["霁日扶霜仗，祥烟覆晓班。","帝居回北斗，天阙竦南山。","紫殿鸿鸾肃，金门虎豹环。","蓬莱两仙伯，迥立白云间。"]},{"t":"和道粹春寒趋馆马上口占","f":"词","c":["残腊尚要春，清寒更著人。","雪华犹惜别，物意倍添新。","云压宫城重，风调玉漏匀。","行游宜结辔，九陌未多尘。"]},{"t":"和道粹雪夜直宿","f":"词","c":["天禄凝严近紫台，书帏夜对雪华开。","层楼直倚寒空出，清漏还从深殿来。","薄梦不成冰柱折，晓光先到玉花催。","兔园终是诸侯事，虚费相如能赋才。"]},{"t":"和潞公与昌言正叔游独乐园徘徊久之主人不至","f":"词","c":["茂勋成亮采，胜赏寄风流。","闲引翘林客，同为独乐游。","厌居华宇盛，翻爱弊庐幽。","愧不先操彗，迎尘立道周。"]},{"t":"和潞公真率会诗","f":"词","c":["洛下衣冠爱惜春，相从小饮任天真。","随家所有自可乐，为具更微谁笑贫。","不待珍羞方下箸，只将佳景便娱宾。","庾公此兴知非浅，藜藿终难继主人。"]},{"t":"咏史 其三","f":"词","c":["春风三阁上，珠翠日纷纷。","乐饮陶江月，清歌遏海云。","醉中失陈国，梦里入隋军。","玉树庭花曲，凄凉不可闻。"]},{"t":"咏史 其一","f":"词","c":["不事王侯者，翛然郑子真。","开田谷口美，荷锸白渠春。","德化移乡曲，声光动搢绅。","一时钟鼎贵，磨灭彼何人。"]},{"t":"咏史 其二","f":"词","c":["延陵腰利剑，上国使初通。","待我周游遍，逢君遣奠终。","晶荧系高树，萧瑟动寒风。","谁敢欺生死，苍苍照尔衷。"]},{"t":"咏寒士","f":"词","c":["洋洋泌水侧，蓬室苦萧条。","衣薄难胜夜，厨闲空过朝。","笑谈东郭履，歌诵买臣樵。","但问才何似，无疑卿相遥。"]},{"t":"夜发长垣","f":"词","c":["长涂暑气剧，永日卧邮亭。","画伏如墙鼠，宵行似野萤。","歇鞍沙月白，拂面柳风醒。","历历瞻云汉，谁为二使星。"]},{"t":"奉同运使陈殿丞惜洛阳牡丹为霜风所损","f":"词","c":["名花多种欲纷敷，一夕霜风非所虞。","节物偶然何足道，人情遗恨不能无。","飘飖健笔诗千首，惆怅东风酒百壶。","纵使前春满朱槛，使车那复滞西都。"]},{"t":"奉同道矩谢始平公惠砚","f":"词","c":["爵台今已倾，飘瓦出芜城。","还入缣缃用，尤资笔墨精。","相君怜古物，内史擅书名。","聊用飞军檄，何愁楯鼻平。"]},{"t":"奉和始平公忆东平 其一","f":"词","c":["相印东临汶水阳，两看春叶与秋霜。","登山置酒延邹湛，上马回鞭问葛强。","溪竹低垂寒滴翠，露荷相倚净交香。","宵衣深念长城固，肯得从容傲醉乡。"]},{"t":"奉和始平公忆东平 其二","f":"词","c":["千岩秀色拥晴川，万顷陂光上下天。","委地鱼盐随处市，蔽空桑柘不容田。","讼庭虚静官曹乐，儒服宽长邑里贤。","不为从知方负羽，独乘鱼艇老风烟。"]},{"t":"奉和始平公喜闻昌言修注","f":"词","c":["凤口除书下九阍，簪绅拭目仰殊恩。","晓提麟笔依华盖，日就螭坳记圣言。","桃李新阴方蔼蔼，骅骝老志更轩轩。","主人喜见相如达，趣召邹枚洗玉樽。"]},{"t":"奉和御制龙图等阁观三圣御书","f":"词","c":["积厚丕丕业，重光郁郁文。","宝书垂列宿，玉字切浮云。","散帙鸣銮驻，充庭杂佩分。","愿移天纵艺，似续圣功勤。"]},{"t":"和景仁西湖泛舟","f":"词","c":["满船歌吹拂春湾，天外晴霞水底斑。","谁信飞觞临绮席，独能回首望青山。","东门车马匆匆别，西洛风烟寂寂闲。","叠石溪头应更好，却输野叟坐林间。"]},{"t":"始平公以光得免使北赐之以诗谨依韵酬和","f":"词","c":["皇华将命得人难，专对非才辄自言。","幸免驱车涉沙漠，尚容载笔侍宣温。","不唯羞屈穹庐膝，无奈常游魏阙魂。","衮职区区未能补，何时馀论奉清樽。"]},{"t":"始平公新作双樗庵命光为诗","f":"词","c":["间气生王佐，多才秉国钧。","栋隆凭杞梓，节劲仰松筠。","底绩承平业，遗荣寿考身。","结庐依散木，退让乐天真。"]},{"t":"宜甫东楼晚饮","f":"词","c":["宾主俱欢醉，高楼迥倚空。","形忘羁检外，酒散笑谈中。","晚市烟初白，秋园叶半红。","登临不厌数，朝夕是寒风。"]},{"t":"忝职谏垣日负忧畏缅思云夫处士老兄萧然物外何乐如之因成浮槎诗寄献以抒鄙怀","f":"词","c":["秋水浮槎客，漂如一叶轻。","鸥群须仗信，鲸口几忘生。","耿耿天津阔，滔滔海浪惊。","何时还故土，怀糈问君平。"]},{"t":"或谓光嗤景仁谈禅而自谈又因用前韵为景仁解禅","f":"词","c":["贱子悟已久，景仁迷自今。","良因拯溺急，是致涉波深。","到岸何须筏，挥锄不见金。","浮云任来往，明月在天心。"]},{"t":"枇杷洲","f":"词","c":["周官敛珍味，汉苑结芳根。","何意荒洲上，犹馀嘉树存。","犯寒花已发，迎暑实尤繁。","愿逐蒲萄使，离宫奉至尊。"]},{"t":"苦雨","f":"词","c":["积雨欲侵旬，朝晡漫不分。","苍凉微露日，惨澹已生云。","地半成泥滓，天应厌垢氛。","时闻度鸧鸹，空外自为群。"]},{"t":"英宗皇帝挽歌辞三首 其三","f":"词","c":["谏省臣无状，龙鳞昔屡婴。","恩深忘位贱，义重觉生轻。","不正诛锄法，仍蒙奖叹荣。","百身何足报，天造固难名。"]},{"t":"英宗皇帝挽歌辞三首 其二","f":"词","c":["虹瑞流朱邸，童髦侍紫宸。","简心天与子，授位帝知人。","学古功时敏，钩深道日新。","宜然三百载，民物仰威神。"]},{"t":"英宗皇帝挽歌辞三首 其一","f":"词","c":["盛德师尧舜，英姿肖祖宗。","太阳光遍照，沧海量兼容。","鸿业知能继，齐民望可封。","如何未五载，已上鼎湖龙。"]},{"t":"虎牢关","f":"词","c":["天险限西东，难知造化功。","路邀三晋会，势压两河雄。","馀雪沾枯草，惊飙卷断蓬。","徒观争战处，今古索然空。"]},{"t":"诗寄云夫处士老兄兼呈知府待制八丈","f":"词","c":["一鹗曾飞奏，中林下鹤书。","今乘使君马，重到逸人居。","松竹过从久，闾阎惠爱馀。","只应棠树影，比旧更扶疏。"]},{"t":"郑侍郎挽歌辞","f":"词","c":["云梦气回复，比肩生隽豪。","司农家学富，廷尉里门高。","骐骥昔千里，凤凰今一毛。","即邱馀庆在，终应吕虔刀。"]},{"t":"金山寺","f":"词","c":["香刹冠嵯峨，松门络薜萝。","风清尘不到，岸阔鸟难过。","欲雨江声怒，新晴海气多。","行舟未摇棹，回望隔烟波。"]},{"t":"南园杂诗六首 莲房","f":"词","c":["莲房前后熟，供啖不须齐。","肉嫩山蜂子，棱深天马蹄。","尚连馀蕊在，深映乱荷低。","脆美知新采，近根犹带泥。"]},{"t":"南园杂诗六首 萤","f":"词","c":["林塘荒湿地，向夕已飞萤。","月没蛩吟砌，露凉人在庭。","随风疑落烬，过水乱疏星。","学子灯前寝，谁将尔照经。"]},{"t":"南园饮罢留宿诘朝呈鲜于子骏范尧夫彝叟兄弟","f":"词","c":["园僻青春深，衣寒积雨阕。","中宵酒力散，卧对满窗月。","旁观万象寂，远听群动绝。","只疑玉壶冰，未足比明洁。"]},{"t":"南湖 其二","f":"词","c":["海雁长桥北，乘闲日日来。","游鱼自应乐，宿鸟不相猜。","弱柳周遭合，芳花次第开。","梁王昔游集，后乘列邹枚。"]},{"t":"南湖 其一","f":"词","c":["宋都南野水，花柳媚名园。","鸟起沙留迹，鱼惊浪结痕。","朱桥通别岛，白路出荒村。","城邑虽云迩，常无车马喧。"]},{"t":"复古诗首句云独步复静坐辄继二章 其一 独步","f":"词","c":["踽踽出东轩，徐徐步小园。","何须从吏卒，亦不引儿孙。","蹑屐寻莎径，携筇拨水源。","愁闻俗客到，唯说市朝喧。"]},{"t":"复古诗首句云独步复静坐辄继二章 其二 静坐","f":"词","c":["一榻仅容膝，身心俱寂然。","直缘知乐内，亦不为安禅。","棐几陈编掩，竹窗残局捐。","尚馀喧噪在，野鸟与林蝉。"]},{"t":"复用三公燕集韵酬子骏尧夫","f":"词","c":["官闲虚室白，粟饱太仓红。","朝夕扫三径，往来从二公。","蒹葭徒倚玉，燕雀岂知鸿。","相遇辄同醉，惟愁樽酒空。"]},{"t":"宣徽使河东经略使郑文肃公挽歌 其二","f":"词","c":["柳翣丧容盛，江山故国遥。","清时独长往，何日重来朝。","事与秋云断，荣如晓梦消。","西风虎丘路，马鬣又嶕峣。"]},{"t":"宣徽使河东经略使郑文肃公挽歌 其一","f":"词","c":["璿玑敷帝命，金节护边兵。","尽付将军制，真为儒者荣。","扶摇方上击，濛汜忽西倾。","罢市人相吊，纷纷满百城。"]},{"t":"侍读王文公挽歌二首 其二","f":"词","c":["杖底潜蛇影，门阴集戴鵀。","玉楼新记就，石椁旧铭沈。","箧有封峦札，籯无遗子金。","寂寥封马鬣，秋色净松林。"]},{"t":"侍读王文公挽歌二首 其一","f":"词","c":["石室书编富，金华讲席重。","荐神归博洽，鸣玉称雍容。","贰负累囚象，尸臣古瑑踪。","老成今已矣，咨访欲谁从。"]},{"t":"故侍读学士张公哀辞二首 其二","f":"词","c":["凶梦歌洹水，妖巢集戴鵀。","未尝馀俸禄，无以具衣衾。","袁涣分仓谷，翁归赐府金。","佗年纯固传，宁使令名沈。"]},{"t":"故侍读学士张公哀辞二首 其一","f":"词","c":["喜愠与荣枯，居之悉晏如。","稍门多执笔，至老不抛书。","常愧无能极，曾沾清论馀。","秋风郭门外，雨泣望丧车。"]},{"t":"故相国颍公挽歌辞三首 其三","f":"词","c":["沧波与邓林，鱼鸟久飞沉。","一旦成陈迹，何人识寸心。","高山亡景行，流水失知音。","泪尽离东阁，归来破故琴。"]},{"t":"故相国颍公挽歌辞三首 其二","f":"词","c":["铭旌远明灭，骑吹去低昂。","三鼎功名大，重泉日月长。","鹤飞来吊客，牛卧卜连冈。","车马还城郭，悲风满白杨。"]},{"t":"故相国颍公挽歌辞三首 其一","f":"词","c":["儒衣临绝塞，庙略运奇兵。","缓带羌尘静，灵旗海雾清。","公心结明主，阴德庇群生。","名遂身仍退，人间五福并。"]},{"t":"故绛城","f":"词","c":["文公恢霸略，征讨辅周衰。","奕世为盟主，诸侯听会期。","山河表里在，朝市古今移。","欲访虒祁处，乡人亦不知。"]},{"t":"故翰林彭学士挽歌 其三","f":"词","c":["祖奠垂将撤，笳箫俨欲行。","野寒嘶故马，树转出新旌。","泉路幽无底，鱼灯暧不明。","如何赍美志，郁郁向佳城。"]},{"t":"故翰林彭学士挽歌 其一","f":"词","c":["夙昔游清贯，时流籍重名。","雠书石渠秘，视草玉堂荣。","吉兆虚三鳝，凶期告两楹。","子云思故国，坟树必西倾。"]},{"t":"春日思景仁","f":"词","c":["去岁洛城中，嬉游处处同。","从离崿岭北，常梦潩泉东。","草绕春街碧，花繁夕市红。","临风默惆怅，想像白眉翁。"]},{"t":"春祠致斋寄呈景仁次道","f":"词","c":["比日聚官舍，笑言曾未厌。","暂成挥手别，各有侍祠严。","晴景朝朝丽，春容物物添。","解斋当共醉，莫遣此期淹。"]},{"t":"春猎","f":"词","c":["小苑微寒春雁飞，石关宫外草萋萋。","汉家旌旆连围合，秦国山川入望低。","花色才临珠缀发，柳阴欲傍金堤齐。","韩嫣承恩来视兽，飞尘遥出建章西。"]},{"t":"柳溪对雪","f":"词","c":["春风不胜雪，散漫度龙沙。","密映缘溪柳，争飞乱眼花。","鸱夷赊美酒，油壁系轻车。","塞下芳菲晚，聊将当物华。"]},{"t":"泉水诗送吴都官分司归和州","f":"词","c":["泉水出幽谷，原流本自清。","萦回遍中国，浩荡入东瀛。","峡口春雷怒，潭心晓鉴平。","悠悠随所值，行止两无情。"]},{"t":"独乐园新春","f":"词","c":["春风与汝不相关，何事潜来入我园。","曲沼揉蓝通底绿，新梅剪綵压枝繁。","短莎乍见殊堪喜，鸣鸟初闻未觉喧。","凭仗东君徐按辔，旋添花卉伴芳樽。"]},{"t":"相国广平文简程公挽歌二首 其二","f":"词","c":["帝诰封泥紫，皇坟杀简青。","坐谈安玉垒，专对詟龙庭。","黼黻昭文理，冰霜瑩典刑。","英灵入箕尾，终古作天星。"]},{"t":"相国广平文简程公挽歌二首 其一","f":"词","c":["明直君臣合，安危将相兼。","金章四辅贵，玉帐万兵严。","禦侮长城隐，临繁利刃铦。","南山霣岩石，何以慰民瞻。"]},{"t":"神宗皇帝挽词五首 其四","f":"词","c":["鳌禁叨承诏，金华侍执经。","微生轻草芥，圣泽阔沧溟。","鹿性安林野，葵心注阙庭。","尧云不可望，白首涕飘零。"]},{"t":"神宗皇帝挽词五首 其三","f":"词","c":["至德成无象，徽名避不居。","期门弋猎绝，步辇宴游疏。","钱列金釭暗，兵严武帐虚。","蓬莱日晏仗，犹望驾宫车。"]},{"t":"神宗皇帝挽词五首 其二","f":"词","c":["听政涉中昃，观书达夜分。","周王忘自逸，汉祖不知勤。","棣萼因心友，云章落笔文。","它年紬石室，光大继皇坟。"]},{"t":"秋日寄山中友人","f":"词","c":["昨夜听秋风，霜崖几树红。","心随新雁去，宛至碧溪东。","圣主搜渔钓，林岩今已空。","胡为执高节，憔悴久山中。"]},{"t":"秋日登观信亭","f":"词","c":["西风连夜雨，草树已萧条。","宿霭稍零落，寒山更寂寥。","林红犹带日，岸白欲生潮。","新雁来何处，离离天际遥。"]},{"t":"秋夜","f":"词","c":["城上调秋角，烟间发暝钟。","风枝摇宿鸟，霜草覆寒蛬。","久负观书乐，端愁束带恭。","暂因群吏散，还得遂幽慵。"]},{"t":"秋夜","f":"词","c":["浮云一消散，星斗粲长天。","浩露洒翠柏，清香生白莲。","体凉犹衣葛，耳静已无蝉。","坐久群动息，秋空唯寂然。"]},{"t":"秋夜望月","f":"词","c":["万里氛昏歇，金波秋更明。","星连河渚闇，风绕桂枝生。","鳷鹊临华馆，新丰落故城。","古今佳赏尽，殊自有馀清。"]},{"t":"秋雨新霁游水北马上偶成","f":"词","c":["秋色与秋声，萧然满洛城。","未霜林叶赤，新雨野风清。","水气侵肌冷，岚光刮眼明。","谁云景如画，但恐画难成。"]},{"t":"胡太傅挽歌二首 其二","f":"词","c":["裴回游内禁，密勿赞鸿枢。","阴德加民物，清名服士夫。","天方遗一老，星忽陨三吴。","疑从龙髯去，乘云在帝都。"]},{"t":"胡太傅挽歌二首 其一","f":"词","c":["行冠乡人品，文为学者师。","黄裳蕴厚德，玉律俨清规。","大节人难夺，嘉谟世莫知。","仪型不可见，遗烈满丰碑。"]},{"t":"贻宋四行简迪","f":"词","c":["离群如几辰，屈指十青春。","不意轮蹄迹，共兹京洛尘。","文场投漆契，客路转蓬身。","别易相逢阔，过从莫厌频。"]},{"t":"送丁正臣知蔡州","f":"词","c":["䟃?汝水滨，千骑拥朱轮。","悬瓠遗基古，鞶囊吉梦新。","丹心留紫闼，清耳远红尘。","须识明君意，先应试治民。"]},{"t":"送丁正臣通判复州","f":"词","c":["得失固有命，世人空自劳。","冬温少霜雪，松短没蓬蒿。","孤宦千里远，荣名一旦高。","回看碌碌者，太华与秋毫。"]},{"t":"送二同年使北 吕济叔","f":"词","c":["华缨下玉除，天子宠匈奴。","虽复夷风陋，犹知汉使殊。","夜烽沈不举，秋柝寂无虞。","何必燕然刻，苍生肝脑涂。"]},{"t":"送二同年使北 李公素","f":"词","c":["云愁雪欲零，四牡出郊坰。","古塞烟华紫，寒沙日气青。","金门秘鸡树，朱节耀龙庭。","几夜天街北，遥占汉使星。"]},{"t":"送人为闽宰","f":"词","c":["万里东瓯外，溪山秀出群。","乡人皆嗜学，太守复工文。","正用慈良化，居无牒诉纷。","谁云远京国，佳政日相闻。"]},{"t":"送才元守广安军归成都觐省","f":"词","c":["皂盖五骅骝，今来异昔游。","箪壶交里舍，铙吹下瀛州。","寿酒行当举，归鞭不可留。","春光久相待，先在锦江头。"]},{"t":"送云卿知卫州","f":"词","c":["汗简成新令，褰帷刺剧州。","韦平家法在，邵杜治声优。","野竹交淇水，秋瓜蔓帝邱。","三年归奉计，肯顾石渠游。"]},{"t":"送元待制出牧福唐","f":"词","c":["瓯越东南美，田肥果稼饶。","况怀新赐绶，重过旧题桥。","食足奸回熄，风移狱犴销。","长才报政速，铃阁日逍遥。"]},{"t":"送王书记之官永兴","f":"词","c":["白发添新镊，红尘满弊衣。","人生适未值，吾道岂云非。","巩洛风烟远，函秦草树微。","长安春酒美，行乐勿令希。"]},{"t":"送王伯初通判婺州","f":"词","c":["煜爚屏星驾，迢遥婺女区。","岚光晴向背，溪溜暖萦纡。","万室鸣机杼，千艘隘舶舻。","若逢耆旧问，能说隐侯无。"]},{"t":"送王校理守琅琊","f":"词","c":["金门倦鸣玉，千骑出东方。","封略依沧海，枌榆近故乡。","秦碑苔蚀字，鄅稻日翻芒。","国吏遥应识，当年丞相郎。"]},{"t":"送王都官官满还都","f":"词","c":["粹美清庙器，可嗟沉下僚。","优游仲举坐，洋溢海沂谣。","奏课应居首，知音况满朝。","从今黄鹄举，眼冷看青霄。"]},{"t":"送王著作西京签判","f":"词","c":["古来都邑美，孰与雒阳先。","况复元侯贵，兼之从事贤。","玦离横阙塞，珠曲逗伊川。","慰眼登临乐，送君空惘然。"]},{"t":"送王殿丞西京签判","f":"词","c":["清白世风存，王公复有孙。","挺生如玉树，不竭似淮源。","日背嵩峰紫，春添洛水喧。","幕中多胜友，肯使负芳樽。"]},{"t":"送王殿丞知眉山县 其一","f":"词","c":["畴昔侍严亲，俱为綵服人。","游兰已多益，得桂复同春。","风树悲欢异，萍波聚散频。","峡中尽遗事，何处不沾巾。"]},{"t":"送王瓘同年河南府司录","f":"词","c":["綵服昔为儿，随亲宦洛师。","至今馀梦想，常记旧游嬉。","佐史头应白，书楼树已攲。","闻君行有日，使我泪交颐。"]},{"t":"送冯状元归鄂州","f":"词","c":["夙昔负奇节，琅然为众殊。","下韝连得俊，出手尽成卢。","喜气兼邻曲，荣名溢道涂。","风云俱动色，非复旧江湖。"]},{"t":"送史馆任祠部河东转运使","f":"词","c":["问望簪绅旧，恩华雨露重。","图书周内史，汾浍晋全封。","秀发千寻壁，寒生百鍊锋。","归时门有戟，惜别更从容。"]},{"t":"送田校理知晋州","f":"词","c":["铨筦萃贤豪，夫君主剧曹。","长才沛馀裕，众论蔚推高。","逮此分符贵，知无顿刃劳。","公卿如有缺，不独赐金褒。"]},{"t":"送白都官归长安","f":"词","c":["丈夫那肯浪低眉，薄宦空添鬓里丝。","泸水归来山浩荡，都门辞去菊离披。","黄鸡白酒五陵乐，杜曲樊川九谷宜。","复见夫君行直道，崆峒气俗未应衰。"]},{"t":"送仲更归泽州","f":"词","c":["太行横拥巨川回，三晋由来产异才。","展墓乘春走乡陌，负书拂晓下兰台。","河阳路侧花应合，天井关头雪未开。","会使乡人惊六印，莫羞今日弊裘来。"]},{"t":"送光禄王卿致仕归荆南","f":"词","c":["九列谁云非显涂，人生已不负为儒。","拂衣长揖夔龙贵，散发还为黄绮徒。","白鹤归飞心自远，青霞高举势何孤。","千金尽与乡人费，不向江头买木奴。"]},{"t":"送冲卿通判河中府","f":"词","c":["闻道名都行有期，依然想见昔游时。","寒光一曲秋河转，翠岭三条夕照移。","孤竹旧风民有让，重华馀教俗无疵。","不须到日方登历，已在君家十二诗。"]},{"t":"送刘仪先辈大名尉","f":"词","c":["潭潭相府开，旌骑拥三台。","闻道廷中吏，无非天下才。","策名新振拔，把板尚低回。","勿为卑飞困，青冥尽此来。"]},{"t":"送刘仲通赴京师","f":"词","c":["圣朝方考牧，蕃育寄才能。","屡别良可叹，闲游不复曾。","行尘遵洛汭，朝骑对觚棱。","瀍上秋台迥，归来正好登。"]},{"t":"送刘观察知洺州","f":"词","c":["汉家英俊士，衮衮出金阊。","久袭通侯籍，新腰太守章。","畛封连故赵，庐井带清漳。","春色迎铙吹，应忘道路长。"]},{"t":"送华亭沈主簿","f":"词","c":["执袂青门道，萧萧马欲东。","暮云零落翠，远树浅深红。","楚泽吟声里，吴山醉眼中。","相思杳何许，野鹤唳高风。"]},{"t":"送向防禦知陈州","f":"词","c":["千骑去翩翩，专城上少年。","韦平家好学，阴马世称贤。","官用才能进，恩非雨露偏。","想闻河润远，封畛帝畿连。"]},{"t":"送尧夫知河中府二首 其二","f":"词","c":["河抱城根曲，山侵地势斜。","周馀古楼观，舜俗旧人家。","回首游从阔，装怀牒诉哗。","何时重载酒，同醉洛阳花。"]},{"t":"送尧夫知河中府二首 其一","f":"词","c":["耆老承风旧，丝纶锡命新。","展禽安屡黜，原宪乐常贫。","执志穷通壹，论交表里真。","但祈深自重，膏泽望斯民。"]},{"t":"送师道知长溪因归觐省","f":"词","c":["羁旅帝城久，逢人青眼稀。","闻君又当去，使我益思归。","佳色邻乡树，高堂望綵衣。","春流先自疾，心出片帆飞。"]},{"t":"送杨太祝知长洲县","f":"词","c":["三吴佳县首，民物旧熙熙。","专用清谈治，非如俗吏为。","林疏丹橘迥，稻熟白芒攲。","宜使民无忘，严修太伯祠。"]},{"t":"送朱校理知潍州","f":"词","c":["东国连年水伤稼，使君到部即行春。","茫茫四野潢污竭，郁郁万行桑柘新。","俗不好奢田器贵，狱无留系吏家贫。","齐人忽怨归朝速，自是承明侍从臣。"]},{"t":"送朱职方提举江淮运盐","f":"词","c":["熬漉沧波耗，征输泽国贫。","婴罗矜赤子，运筴借能臣。","拜手觚棱晓，浮舟狼汤春。","东南待苏息，别酒莫逡巡。"]},{"t":"送次道知太平州","f":"词","c":["狼汤春流满，芜湖候吏迎。","旌旟晓日丽，钲鼓野风清。","暂喜红尘远，休嗟素发生。","专城方四十，自古以为荣。"]},{"t":"送计先辈尉宗城","f":"词","c":["红尘久帝城，高价动公卿。","竹柏寒方茂，骅骝老更成。","冰霜驱马瘦，书剑束装轻。","丞相虚东阁，遥知倒屣迎。"]},{"t":"送齐学士知荆南","f":"词","c":["汉家太守治才高，楚国山川气象豪。","旗旆逶迤蟠梦泽，楼船赑屃压江涛。","雄名谁复知宣武，遗爱犹应祀叔敖。","何必三年求奏计，诏书朝夕赐金褒。"]},{"t":"送何万下第归蜀 其二","f":"词","c":["失意流年老，残春对夕阳。","可堪临远道，更复举离觞。","花柳已萧索，云山复渺茫。","西风如有意，音信勿相忘。"]},{"t":"送何万下第归蜀 其一","f":"词","c":["十上终无就，才高定复论。","清时守儒术，白首在丘园。","远树隐残日，孤烟生暮村。","扬鞭万里去，几许不销魂。"]},{"t":"送何济川为庞公使庆阳席上探得冬字","f":"词","c":["幕府遥三舍，传车乘一封。","忠深轻远道，醉暖失严冬。","圁水犹飞檄，芦阕未灭烽。","贤侯虽喜士，难得久从容。"]},{"t":"送吴仲庶知江宁","f":"词","c":["江南佳丽地，人物自风流。","青骨灵祠在，黄旗王气收。","衣冠馀旧俗，歌颂乐贤侯。","正恐还朝速，江山未遍游。"]},{"t":"送吴驾部知真州","f":"词","c":["向托屏星驾，同随丞相车。","终朝容懒拙，经岁庇迂疏。","共此趋云阙，旋闻建隼旟。","江淮一都会，游刃必多馀。"]},{"t":"送吴辨叔大名司户 其二","f":"词","c":["致远必自近，如君岂椽曹。","鱼龙试春浪，松栝露秋毫。","错落辞华富，䃘?气节高。","垂天起肤寸，无叹走尘劳。"]},{"t":"送吴辨叔大名司户 其一","f":"词","c":["元宰司宫钥，旌旄压大河。","敢言趋府倦，私叹折腰多。","机发何妨避，光尘未免和。","艰难方远到，庆阀肯蹉跎。"]},{"t":"送宋郎中知凤翔府","f":"词","c":["昔解陈仓印，于今二十秋。","双凫久东上，五马重西游。","铙骑行关外，壶浆拥道周。","民心已化服，条教不更修。"]},{"t":"送张寺丞知富顺监","f":"词","c":["汉家五尺道，置吏抚南夷。","欲使文翁教，兼令孟获知。","盘羞蒟酱实，歌杂竹枝辞。","取酒须勤醉，乡关不可思。"]},{"t":"送张学士两浙提点刑狱","f":"词","c":["朝家重典刑，书府借时英。","钲鼓喧江下，云山拂眼清。","秋风鲈鲙美，书日锦衣荣。","勿似朱翁子，空令守邸惊。"]},{"t":"送张秘校知分宁","f":"词","c":["百里大夫官不轻，莫嗟领上发垂星。","人生谷禄偏宜晚，世路艰难不厌经。","数曲秋江萦县白，几峰霁色入帘青。","于公向日多阴德，已有鹓雏在帝庭。"]},{"t":"送张都官江南东路提刑","f":"词","c":["楚俗号难治，司刑尤择贤。","危疑片言决，舒惨一方专。","松不彫寒色，丝曾断直弦。","清风过江外，应在下车前。"]},{"t":"送张景淳知邵武军","f":"词","c":["闽岭窅何在，东南千里遥。","仳离伤草草，会合更迢迢。","隋岸微吹絮，吴江欲上潮。","肯无同舍念，回首弭轻桡。"]},{"t":"送李学士使北","f":"词","c":["征盖霜空迥，飘飘迎塞鸿。","虏牙侵海角，汉节下天中。","酒薄阴山雪，裘寒易水风。","边声不可听，归思浩无穷。"]},{"t":"送李益之侍郎致政归庐山 其二","f":"词","c":["水底元无月，衣中自有珠。","六尘皆外物，万法尽迷涂。","瀑布寒云湿，觚棱瑞气扶。","遥知至乐地，不异在京都。"]},{"t":"送李益之侍郎致政归庐山 其一","f":"词","c":["儒业金华贵，归心白鹤孤。","江山依旧在，轩冕向来无。","啸咏谁当共，登临未索扶。","浩然知此乐，迥与世人殊。"]},{"t":"送杨秘丞通判扬州","f":"词","c":["苦闻小杜说扬都，当昔豪华今在无。","江势横来控南楚，地形前不瞰东吴。","万商落日船交尾，一市春风酒并垆。","得意莫忘京国友，踏尘冲雪奉朝趋。"]},{"t":"送沈寺丞知南昌县","f":"词","c":["长江湛湛带枫林，古木寒云县寺深。","老吏不能容狡狯，细民无复有冤侵。","洪崖丹井闻犹在，徐孺衡门说可寻。","宁复淹留如宝剑，更令牛斗气沈沈。"]},{"t":"送苏屯田知单州","f":"词","c":["佳郡望都城，相闻击柝声。","宾朋才执别，耆旧已前迎。","綵服当年戏，骊驹此日荣。","弦歌应尽在，琴调不须更。"]},{"t":"送周寺丞畋知洛南","f":"词","c":["太华指商于，中间百里馀。","稍行山驿远，渐与世尘疏。","楚塞参差接，秦民错杂居。","惜哉非綮肯，不足试投虚。"]},{"t":"送昌言舍人得告还蜀三首 其三","f":"词","c":["富贵动归思，由来光里闾。","戒门羞主父，负弩笑相如。","外物有荣悴，中心无戚疏。","遥知见亲旧，不改布衣初。"]},{"t":"送昌言舍人得告还蜀三首 其二","f":"词","c":["悽怆怀桑梓，劬劳咏蓼莪。","树风今远矣，鼎食奈悲何。","剑阁登车近，秦关屈指过。","腾装才首路，夕梦已江沱。"]},{"t":"送昌言舍人得告还蜀三首 其一","f":"词","c":["迢递铜梁道，凝严青琐闱。","负书当日去，鸣玉此时归。","乡树迎朱毂，江花照锦衣。","临邛不足并，荣耀古今稀。"]},{"t":"送昌言知宿州","f":"词","c":["炜炜符离守，中流簇鼓旂。","柳阴浓不断，舟势激如飞。","魏阙行归奏，承明秪暂违。","星轺晨夜度，尺素勿令稀。"]},{"t":"送魏寺丞赴辟秦州判官","f":"词","c":["征西大府开，后乘得高才。","区脱烽烟静，渠搜职贡来。","陇云低玉帐，羌舞奉金罍。","信美从军乐，脩梧茂帝台。"]},{"t":"送罗郎中管勾玉局观","f":"词","c":["官名为玉局，已与俗尘疏。","钟出寒松迥，香疑古殿虚。","乡闾非甚远，俸禄岂无馀。","谁道神仙乐，神仙恐不如。"]},{"t":"送郑推官赴邠州 其三","f":"词","c":["骄虏已归计，圣朝方寝兵。","时闻候火入，非复塞尘惊。","秋岭无南牧，春田恣北耕。","休穷西海路，辛苦学甘英。"]},{"t":"送郑推官赴邠州 其二","f":"词","c":["百榼行春乐，千弓从猎豪。","苦吟边月冷，飞镝野风高。","奇策鞭殊俗，长缨系不毛。","输君跃马贵，一等着青袍。"]},{"t":"送郑推官赴邠州 其一","f":"词","c":["形便豳公国，旌旗拥将坛。","秦云低落日，塞树怯春寒。","草檄无留思，投壶不废欢。","还应笑黄卷，寂寂守儒官。"]},{"t":"送峡州陈廉秘丞 其三","f":"词","c":["地险三巴口，江流百折蟠。","驺珂通峡响，门戟照秋寒。","翠壁虎牙石，素花狼尾滩。","孙刘置栅处，细为写图看。"]},{"t":"送峡州陈廉秘丞 其二","f":"词","c":["郡府猿声外，旌旗鸟道边。","楼高出楚塞，烟霁识巴船。","襦裤嗟来暮，簪绅惜外迁。","皇仁矜远俗，非谓意疏贤。"]},{"t":"送峡州陈廉秘丞 其一","f":"词","c":["宜都贤太守，治迹古人齐。","虎负众子去，凤环群鸟栖。","行增颍川秩，别降武都泥。","正恐还朝速，春林未子规。"]},{"t":"送昭远兄归陜","f":"词","c":["种种亲头白，帝城难少留。","倚门应有望，列鼎本无求。","清夜多归梦，红尘厌久游。","此行殊捧檄，辕下五骅骝。"]},{"t":"送济川知汉州二首 其二","f":"词","c":["千骑拥朱轓，青霞昼绣还。","复寻题柱迹，重过弃繻关。","晓栈流云湿，秋湖脱叶殷。","久游今得意，真不愧江山。"]},{"t":"送济川知汉州二首 其一","f":"词","c":["金马从容乐，问君何所之。","客心彯若梗，亲发皓如丝。","旧学已孤陋，素交仍别离。","执经时有问，使我复从谁。"]},{"t":"送皇甫寺丞知蓝田县","f":"词","c":["南山三辅剧，百里古诸侯。","谁为弦歌小，不分宵旰忧。","烟横辋川暝，云照武关秋。","安得无羁束，从君一纵游。"]},{"t":"送祖择之","f":"词","c":["人生荣与辱，百变似浮云。","自有穷通定，徒劳得丧分。","消愁唯有酒，娱意莫如文。","方寸常萧散，其馀何足云。"]},{"t":"送茹屯田知无为军","f":"词","c":["叠鼓鸣铙迎候新，军牙孑孑倚淮津。","聊应衣绣过乡曲，不作引章惊故人。","荻迸短芽淝水暖，荷浮圆叶漅湖春。","使君此去荣多少，犹是当年书剑身。"]},{"t":"送赵殿丞归成都","f":"词","c":["蜀栈锦衣来，高堂绶笥开。","恩辉同日至，喜色共春回。","驷马过邻社，朝裾捧寿杯。","吾生无此乐，空使寸心摧。"]},{"t":"送晁校理知怀州","f":"词","c":["鸡犬相闻桑柘春，风光明润帝乡邻。","群峰斜转太行角，万谷同趋马颊津。","簪组倾都邀别袂，壶浆满路候行尘。","非君厌薄承明直，天子方今重治人。"]},{"t":"送晁秘丞通判雄州","f":"词","c":["少傅名德重，蔚然人物师。","群孙满丹穴，嘉瑞尽长离。","勿叹毛羽短，已惊文采奇。","勉哉勤志业，馀庆未应衰。"]},{"t":"送聂秘丞宰桐城二首 其二","f":"词","c":["七载一相见，恍然如路衢。","形骸渐枯槁，志业转荒芜。","往事云过眼，新愁雪染须。","明朝又分首，上马即重湖。"]},{"t":"送聂秘丞宰桐城二首 其一","f":"词","c":["问子青云器，胡为不少留。","未能充禄养，安散及身谋。","卓尔千人俊，居然百里忧。","连城价终在，自是玉工羞。"]},{"t":"送致仕朱郎中令孙","f":"词","c":["世间荣利无穷物，奔走劳劳何所之。","仕宦为郎非不达，功名有命待无时。","橐中虽乏千金直，膝下常携两绶儿。","细校人生能此少，好从闾里乐期颐。"]},{"t":"送惠思归钱塘","f":"词","c":["孤岫平湖外，禅房老柏阴。","倦游谙浊世，独往遂初心。","夜雨灯窗迥，秋苔屐齿深。","勿锄山径草，便有俗人寻。"]},{"t":"送程端明知成都","f":"词","c":["高阳将幕开，濯锦使旌来。","欲识关头雪，正如江上梅。","宵衣矜远俗，露冕寄良才。","岂待三年最，脩梧茂帝台。"]},{"t":"送谢都官知光化军","f":"词","c":["厩吏整车马，匆匆办晓装。","青緺出阊阖，朱旆指沧浪。","野店杏初发，津亭柳已黄。","行行不可驻，犹及劝耕桑。"]},{"t":"送韩太祝知钱塘","f":"词","c":["冠佩郁相映，由来积德家。","一时推隽异，四海走声华。","图籍添舟重，江山忘路赊。","夷涂指霄汉，局骥不须嗟。"]},{"t":"送蒲中舍霜致政归蜀 其一","f":"词","c":["厌苦折腰久，飘然黄鹄飞。","田园未芜没，邻曲有光辉。","昔奋儒衣去，今纡朝绂归。","人生贵知足，得此已为稀。"]},{"t":"送蒲中舍霜致政归蜀 其二","f":"词","c":["念昔两髦日，乌奴同燕游。","随时自有乐，何物可为愁。","岂意今头白，相逢欲涕流。","凭君访题壁，好在水西楼。"]},{"t":"送雷章秘丞知芮城","f":"词","c":["西伯昔断讼，令名存迄今。","南临大河曲，北倚首阳岑。","俗被圣贤化，人多礼让心。","夫君老经术，终日想鸣琴。"]},{"t":"送僧归吴","f":"词","c":["高枕聊成梦，晴空忽见花。","浮生尽是客，何处得为家。","旅食帝城久，归舟泽国赊。","勿因菰菜味，回首浩无涯。"]},{"t":"京送僧聪归蜀","f":"词","c":["翠柏老精舍，红尘倦帝城。","千山一锡远，万里片云轻。","江栈纡还直，天星纵复横。","听猿应更喜，还是故乡声。"]},{"t":"送裴中舍赴太原幕府","f":"词","c":["元戎台鼎旧，大府节旄新。","边候正无事，宾筵况得人。","山寒太行晓，水碧晋祠春。","斋酿蒲萄熟，飞觞不厌频。"]},{"t":"送燕谏议知潭州","f":"词","c":["长沙地饶美，贾谊独伤悲。","自古临荣辱，几人无怨咨。","使君拥符节，大舰出江湄。","意气陶然乐，应无吊屈辞。"]},{"t":"送薛水部十丈通判并州","f":"词","c":["十万貔貅士，旌旗晋水阳。","元戎倚耆硕，别乘选才良。","秀直寒松节，精明利剑铓。","知君留滞久，从此欲腾骧。"]},{"t":"送瀛州签判苏秘丞","f":"词","c":["高阳十万兵，幕府藉时英。","塞上风犹劲，关南春未生。","投壶边柝静，倚马檄书成。","不忘尘中客，征鸿可寄声。"]},{"t":"送稻醴与子才","f":"词","c":["昔贤尊道谊，置醴待嘉宾。","今我乐闲放，提壶饷故人。","蚁浮杯面白，味撇瓮头醇。","何以助高兴，篱边菊蕊新。"]},{"t":"重过华下","f":"词","c":["昔辞莲幕去，三十四炎凉。","旧物三峰雪，新悲一镊霜。","云低秦野阔，木落渭川长。","欲问当时事，无人独叹伤。"]},{"t":"闻龚伯建下第","f":"词","c":["文章真长物，堪叹又遗贤。","利器空埋土，灵光久照天。","赵锥犹未出，荆璧会须传。","道在虽穷困，知君不慨然。"]},{"t":"首夏二章呈诸邻 其一","f":"词","c":["首夏木阴薄，清和自一时。","笋抽八九尺，荷生三四枝。","新服裁蝉翼，旧扇拂蛛丝。","莎径热未剧，晨昏往来宜。"]},{"t":"哭马承之","f":"词","c":["平生千里别，书问亦常来。","隼拂秋云击，鸾兼霏雾回。","向无高世艺，安见出伦才。","有纸盈箱箧，扃封不忍开。"]},{"t":"哭刘仲原 其一","f":"词","c":["天下才无几，夫君独患多。","高文粲列宿，英辩泻长河。","荣宦成朝梦，浮生度尺波。","旧僚空执酒，相与泪滂沱。"]},{"t":"哭刘仲原 其二","f":"词","c":["昔醉金明渚，今来慧辩祠。","当年笑相视，此日哭殊悲。","天迥川原净，风高草木衰。","江梅灵气在，泉下复相知。"]},{"t":"哭尚颍","f":"词","c":["操业五常备，艰难六极全。","仲尼难语命，禆灶不知天。","弱女飘何许，遗文散莫传。","官轻史不录，后世孰称贤。"]},{"t":"夏日","f":"词","c":["穷边已深夏，气色耿清秋。","鲜旭开山郭，凉烟澹戍楼。","兜铃烽火息，区脱虏尘收。","迨此军中暇，无妨文雅游。"]},{"t":"射堋","f":"词","c":["叠鼓花前急，红旌竹外高。","惊飙分白羽，馀响振乌号。","壮观倾春陌，欢声涌夜涛。","因兹刑礼俗，岂独事游遨。"]},{"t":"旅宿睢阳南湖","f":"词","c":["梁王弃宫馆，时世古今违。","犹有南湖水，春来雁鹜飞。","楼台沈倒影，林薄挂馀晖。","豪侈终何在，行人得暂依。"]},{"t":"晋阳三月未有春色","f":"词","c":["天心均煦妪，物态异芬芳。","上国花应烂，边城柳未黄。","清明空改火，元已漫浮觞。","仍说秋寒早，年年八月霜。"]},{"t":"晓思","f":"词","c":["束带朝尚早，蓬门未脱扃。","短篱潜落月，老树带孤星。","隐几貂裘黑，开编竹简青。","子云非执戟，何以得穷经。"]},{"t":"朔会堂","f":"词","c":["朔旦集俺吏，兹堂簪组繁。","舞空孤鹤下，映日两凫翻。","花散东方骑，萍浮北海樽。","须知太守贵，铙吹引朱轮。"]},{"t":"浮醳亭","f":"词","c":["曲水华榱下，浮觞去复还。","浪摇花影碎，日射酒缸殷。","灭没遥寻客，徘徊怯度湾。","穷欢不知醉，清泚照心颜。"]},{"t":"留别友生","f":"词","c":["野际共为别，客亭芳草新。","何心更执酒，满目尽伤春。","今古无穷路，东西相背尘。","行行复回首，不欲着鞭频。"]},{"t":"留别逢吉","f":"词","c":["君念承明臭味稀，相逢惜别重依依。","会稽太守方坐啸，东郭先生还步归。","乐饮林塘留节物，饯行里舍动光辉。","双旌回去行人发，一带长皋烟雨微。"]},{"t":"致政杨侍郎挽歌 其二","f":"词","c":["忧国心如石，当朝有古风。","挂冠虽在远，遗札不忘忠。","飞旐西归洛，新阡背倚嵩。","还令往来客，下马白杨中。"]},{"t":"致政杨侍郎挽歌 其一","f":"词","c":["时论归清德，皇心重老臣。","祖风终鲠直，家学本深淳。","便殿谈经久，安车就第新。","如何金未尽，奄忽弃乡人。"]},{"t":"致政邵少卿挽词","f":"词","c":["北固启佳城，东吴霣德星。","穗帷长寂寞，羽扇遂飘零。","泉烛千年碧，霜松数寸青。","馀庆知有在，玉树满阶庭。"]},{"t":"读汉武帝纪","f":"词","c":["方士陈仙术，飘飘意不疑。","云浮仲山鼎，风降寿宫祠。","上药行当就，殊庭庶可期。","蓬莱何日返，五利不吾欺。"]},{"t":"逍遥四章呈钦之尧夫 其四","f":"词","c":["六合旷无际，逍遥好纵游。","放怀同一贯，瞬目即千秋。","丸遇区臾止，萍随波浪流。","所之皆自得，何惧亦何忧。"]},{"t":"逍遥四章呈钦之尧夫 其一","f":"词","c":["结发读经史，疲精非一朝。","于今成濩落，所幸得逍遥。","不韪狂心息，难平客气消。","巢林易为足，窃敢比鹪鹩。"]},{"t":"郭氏园送张仲通出刺棣州","f":"词","c":["名园送嘉客，冠盖去倾朝。","小雨尘微敛，馀寒酒易消。","雁归春近塞，日上海生潮。","北道平如掌，东风五马骄。"]},{"t":"钱子高挽歌二首 其二","f":"词","c":["象设如平昔，升堂不见君。","尚疑言笑在，忽念死生分。","清论千秋雪，浮荣一片云。","泉台多少路，何处复修文。"]},{"t":"钱子高挽歌二首 其一","f":"词","c":["炜烨传家学，连翩射策荣。","走丸过省阁，破竹取公卿。","埋玉嗟何早，为山惜未成。","空令泽宫友，相顾泪纵横。"]},{"t":"陪子华燕醮厅酒半过赵中令园","f":"词","c":["簪裾丞相阁，林沼令君家。","烟曲香寻篆，杯深酒过花。","霏微烬沈水，馥郁渍榠柤。","愧乏相如赋，陪游托后车。"]},{"t":"陪始平公燕柳溪","f":"词","c":["溪光不动柳风轻，玉帐森沈拥万兵。","鸥入烟中闲自舞，鱼翻波面喜相迎。","楼船下视晴天碧，鼓吹前驱远陌清。","桃李归时应盛发，薰然和气满春城。"]},{"t":"陪致政开府太师留守相公致政内翰燕集辄歌盛美为三公寿皆用公字为韵 内翰","f":"词","c":["眉似高僧秀，颜如童子红。","忠纯汲长孺，高洁夏黄公。","矫矫辽东鹤，冥冥塞北鸿。","自誇新酒量，像想百分空。"]},{"t":"陪致政开府太师留守相公致政内翰燕集辄歌盛美为三公寿皆用公字为韵 太师","f":"词","c":["独佐成康世，高年有毕公。","神心降维岳，龟兆告非熊。","黄阁遵成范，太常书茂功。","归来保眉寿，恩礼享优隆。"]},{"t":"陪致政开府太师留守相公致政内翰燕集辄歌盛美为三公寿皆用公字为韵 相公","f":"词","c":["东阁延髦士，西都守别宫。","不忘如卫武，难老似僖公。","位貌今虽远，官僚旧忝同。","开怀尽卮酒，足以厚时风。"]},{"t":"陪诸君北园乐饮","f":"词","c":["浩歌纵饮任天机，莫使欢娱与性违。","玉枕醉人从独卧，金羁倦客听先归。","须知会府闲时少，况复边城乐事稀。","花卉正浓风日好，今年已不负春晖。"]},{"t":"假山","f":"词","c":["广汉土平远，已嫌丘壑疏。","呼工刻岩洞，应手出庭除。","缥渺神仙宅，嵌空虎豹居。","人功与天力，秀绝两何如。"]},{"t":"寄成都吴龙图同年","f":"词","c":["照席烛花暖，随车剑骑寒。","江山资秀句，风月助清欢。","政简坤维静，仁深井络安。","行歌与独酌，岂得并闲官。"]},{"t":"寄扬州侯都监","f":"词","c":["木落淮南树，秋风日夜高。","月临扬子渡，雪捲广陵涛。","不得同萧散，何因破郁陶。","空凭尺书速，未解梦魂劳。"]},{"t":"寄陜西提刑江学士","f":"词","c":["明主于庶狱，选才从本朝。","酂侯三尺律，汉使一封轺。","郡国清名满，关河古意饶。","凄凉乘障客，华发日萧萧。"]},{"t":"寄唐州吴辨叔二兄","f":"词","c":["方城古称险，远在豫州南。","近岁污莱辟，新民秦晋参。","当官诚近厚，获谴亦无惭。","但惜墙阴竹，归辕几日骖。"]},{"t":"寄聂之美","f":"词","c":["去岁双毛白，今春一齿零。","人生浮似叶，客宦泛如萍。","塞上貂裘弊，天涯海气腥。","何当占箕颍，萧散并柴扃。"]},{"t":"寄清逸魏处士","f":"词","c":["乡树三摇落，临风歌式微。","徒嗟俗缘重，端使素心违。","茅阁松杉冷，山园药草肥。","不能如海燕，岁岁一西飞。"]},{"t":"寄题兴州晁都官东沼沼上有唐郑都官诗刻石","f":"词","c":["名郎游胜地，心迹继风流。","昔为题诗著，今因好事修。","四山相照映，五马屡淹留。","想见波光净，依然一片秋。"]},{"t":"寄题刁景纯藏春坞","f":"词","c":["藏春在何许，郁郁万松林。","永日门阑静，东风花木深。","主公今素发，野服遂初心。","时与乡人醉，高歌散百金。"]},{"t":"寄题宇文中允所居","f":"词","c":["孤宦行直道，栖栖良可悲。","谁能拂衣去，不待挂冠期。","经史乃吾友，云山为已知。","世间青紫贵，尽付两佳儿。"]},{"t":"寄题李水部浐水别业","f":"词","c":["茅茨临素浐，沃野带长林。","日永一堂静，草生三径深。","消忧何用酒，为乐不须琴。","扰扰市朝客，无人知此心。"]},{"t":"寄题李舍人蒲中新斋","f":"词","c":["陇上家声勇气殊，边庭卧鼓欲安居。","非同王剪私求宅，更似甘宁晚好书。","剑倚寒窗风淅沥，门无杂客柳萧疏。","蒲州风土平生爱，为问旁邻地有馀。"]},{"t":"寄题洪州慈济师西轩","f":"词","c":["登临传胜绝，怅息未成游。","山气高凌霁，湖光碧照秋。","烟疏茶灶迥，灯冷竹房幽。","安得聊凭槛，萧然洗客愁。"]},{"t":"寄题济源李少卿园亭","f":"词","c":["县僻人事少，土肥风物殊。","杖刊灵寿木，轮裹溴梁蒲。","竹不减淇水，花仍似洛都。","主公眉雪白，游览未尝扶。"]},{"t":"寄题钱君倚明州重修众乐亭","f":"词","c":["横桥通废岛，华宇出荒榛。","风日逢知已，湖山得主人。","使君如独乐，众庶必深颦。","何以知家给，笙歌满水滨。"]},{"t":"寄题常州东山亭二首 其二","f":"词","c":["阀阅崔嵬动四方，入门鸾鹤自成行。","青緺旧已临佳郡，墨客新归耀故乡。","醉舞几应摧屐齿，对棋正欲赌香囊。","阶庭玉树寒相照，更使东山逸气长。"]},{"t":"寄题常州东山亭二首 其一","f":"词","c":["谢傅英声高可攀，结茅积土想东山。","常忧胜概一朝尽，岂信风流千古还。","麈尾蒲葵供永日，酒樽棋局奉欢颜。","贤侯心迹遥相望，不使兰陵风月闲。"]},{"t":"寄题傅钦之济源别业","f":"词","c":["县郭遥相望，脩篁百亩馀。","林间清济水，门外太行车。","道胜随宜足，身闲与世疏。","何时容命驾，采蕨钓肥鱼。"]},{"t":"悼静照堂僧","f":"词","c":["宝阁灰寒静照新，马啼从此踏京尘。","金门乞得诗千首，萧寺归时老一身。","弟子去来浑领袖，交朋存殁半簪绅。","西风又剪梧桐叶，不见蒲团旧主人。"]},{"t":"探花桥","f":"词","c":["桥边春意近，五马屡徘徊。","湖水旦暮渌，林花早晚开。","适因尝酒到，又为赋诗来。","借问双华表，经过日几回。"]},{"t":"五哀诗 斛律丞相","f":"词","c":["君臣日荒宴，歌舞讳言愁。","老相犹当国，强邻不敢谋。","谣言虽未出，奸谤已先流。","谁察忠臣意，通宵抱膝忧。"]},{"t":"晚春病起呈择之治臣","f":"词","c":["风日正和柔，身轻喜病瘳。","懒抛残蠹简，暖脱弊貂裘。","值客开青眼，逢花忘白头。","家家好春色，何处可同游。"]},{"t":"晨发故关寄逢吉","f":"词","c":["画戟衣中趋绛帐，驿亭门外拂征鞍。","已嗟漂泊三年别，更负从容十日欢。","暖席未穷谈笑乐，陟冈相望滞留难。","扬鞭策马几多意，原上秋风作晓寒。"]},{"t":"望日示康广宏","f":"词","c":["清晨三绿袍，罗拜北堂高。","积善因先烈，馀光及尔曹。","勿矜从事早，当念起家劳。","修立皆由己，何人可佩刀。"]},{"t":"梅圣俞挽歌二首 其二","f":"词","c":["漆灯无复曙，柏径不知春。","南纪光华减，中朝俊秀贫。","凄清千古韵，寂寞一丘尘。","异日昭亭下，方多沥酒人。"]},{"t":"梅圣俞挽歌二首 其一","f":"词","c":["兵形穷胜负，史法贯兴衰。","落落虽殊众，恂恂不迕时。","位卑名自重，才大命须奇。","世俗那能识，伤嗟止为诗。"]},{"t":"梧桐","f":"词","c":["紫极宫庭阔，扶疏四五栽。","初闻一叶落，知是九秋来。","实满风前地，极添雨后苔。","群仙傥来会，灵凤必徘徊。"]},{"t":"清风台","f":"词","c":["太守金闺客，天朝应对才。","非因板舆恋，宁驾使车来。","水鉴秋毫尽，霜锋错节开。","清风偏千里，不独此高台。"]},{"t":"清燕亭","f":"词","c":["波澄荫群木，永日湛清华。","碧筱静秋色，白蘋低晚花。","松声工醒酒，泉味最便茶。","外事付丞掾，无妨风景嘉。"]},{"t":"渔父","f":"词","c":["楚岸橘花香，扁舟泛渺茫。","短蓑冲密雨，素发净秋霜。","烟外鸣桹远，波间掷线长。","无人识名姓，击楫入沧浪。"]},{"t":"野庙","f":"词","c":["古庙崩榱在，墙间杂树荒。","依稀设馀像，寂寞閟祠堂。","旧日牲豭地，今晨狐兔乡。","英灵如未灭，何以度凄凉。"]},{"t":"野菊","f":"词","c":["野菊未尝种，秋花何处来。","羞随众草没，故犯早霜开。","寒蝶舞不去，夜蛬吟更哀。","幽人自移席，小摘泛青杯。"]},{"t":"阍吏","f":"词","c":["弊车羸马犯尘泥，愁到朱门遍遍辞。","相国舍人难骤见，将军马监岂相知。","因循岁月劳何补，颠倒风埃辱固宜。","惆怅东冈旧陂在，素心空负白云期。"]},{"t":"雪中寻友人不遇","f":"词","c":["拥袖犯风雪，驱车行诣谁。","朱门不可入，素友复难期。","依世诚多拙，迷方忽自悲。","褊心终寡合，吾道易参差。"]},{"t":"雪霁登普贤阁","f":"词","c":["积雪明朝日，山河坐可分。","崭岩初解冻，片段未归云。","阔望穷人境，高寻俯雁群。","开门枝鸟散，玉絮堕纷纷。"]},{"t":"馆宿遇雨怀诸同舍","f":"词","c":["佳雨濯烦暑，翛然生晓凉。","森沈殿瓦碧，羃历井苔苍。","院静杉篁秀，人闲钟鼓长。","凭谁同把酒，清兴窅相望。"]},{"t":"黄甘","f":"词","c":["黄金缀缥蒂，摇落楚江涯。","采助杯盘胜，羞将橘柚偕。","时移香不变，物远味尤佳。","欲种沧洲树，何年此意谐。"]},{"t":"喜才元过洛小诗招饮","f":"词","c":["素发各垂领，旧交相见稀。","不唯春物好，况是锦衣归。","洛社冻醪熟，伊鲂丝鲙肥。","南轩已洒扫，命驾不须违。"]},{"t":"喜张圣民得登州","f":"词","c":["昼日少闲暇，中宵梦亦劳。","符移空浩浩，榜楚镇謷謷。","敢说今求郡，番思昔坐曹。","羡君乘五马，东去一何高。"]},{"t":"喜孙器之来自共城","f":"词","c":["取友不无人，爱君天性真。","远寻穷巷宅，未拂满衣尘。","主礼贫尤重，交情别更亲。","谁家酿醇酒，尽醉准衣巾。"]},{"t":"喜雨三首呈景仁侍郎兼献大尹宣徽 其一","f":"词","c":["累日增烦暑，通宵结薄阴。","苍茫变风色，散漫作春霖。","野店垂杨重，僧房绿筱深。","疏慵尤得趣，闭户拥重衾。"]},{"t":"喜雨三首呈景仁侍郎兼献大尹宣徽 其三","f":"词","c":["麦田正尘坌，桑径忽滂沱。","比屋起相告，荷锄行且歌。","园林半扃锁，车马绝经过。","大尹爱民物，何妨喜更多。"]},{"t":"寒食御筵口号二首 其二","f":"词","c":["圣主褒优鼎轴臣，金觞玉醴照青春。","万家烟火朝来静，九陌风光雨后新。","高燕翔飞惊紫绶，馀光点缀托朱轮。","问牛因得观民俗，不独嬉游惜令辰。"]},{"t":"寒食御筵口号二首 其一","f":"词","c":["雨意沉沉泼火馀，夔龙盛集退朝初。","酒殽络绎来丹禁，冠剑参差下玉除。","紫凤归飞云烂漫，黄鹂新啭柳扶疏。","麦禾满野边烽息，佳节何妨赋乐胥。"]},{"t":"寒食许昌道中寄幕府诸君","f":"词","c":["原上烟芜淡复浓，寂寥佳节思无穷。","竹林近水半边绿，桃树连村一片红。","尽日解鞍山店雨，晚天回首酒旗风。","遥知幕府清明饮，应笑驱驰羁旅中。"]},{"t":"寒食南宫夜饮","f":"词","c":["积旬留省署，容易度春华。","芳草踏青晚，长楸行乐赊。","云疏时送雨，风细暗飞花。","直有黄金百，无因过酒家。"]},{"t":"寓泊郑圃寄献昌言舍人","f":"词","c":["旅食缁衣馆，飘蓬恍自迷。","树横寒雾远，山隐古原低。","愁暮空庭雀，惊晨别墅鸡。","故人何处在，依约玉绳西。"]},{"t":"御制后苑赏花钓鱼七言四韵诗一首奉圣旨次韵","f":"词","c":["馺娑蜚廉次第开，鸣鞘传跸自天来。","云随綵仗低临幄，柳压金堤翠入杯。","槛倚柔风丝缥渺，花翻丽日影徘徊。","上林春色长如旧，玉辇嬉游岁岁陪。"]},{"t":"御宴送李宣徽知真定府口号","f":"词","c":["匈奴旧畏李将军，今日重来几代孙。","旗尾飘扬山烧裂，马啼腾踏塞尘昏。","降王稽颡朝南阙，天子垂衣御北门。","幕府事闲刁斗静，碧潭佳景日开樽。"]},{"t":"御筵送李宣徽知真定府","f":"词","c":["秋风萧瑟引华旌，祖宴高张出斗城。","玉馔芳菲罗百铁，绣衣照耀拥千兵。","骊歌未阕长杨苑，骑吹先临细柳营。","雨露醲恩何以报，沙场不惜树功名。"]},{"t":"景仁书云去冬因酒病耳病牙遂不入洛以诗寄呈","f":"词","c":["许昌携手尽时英，况复新开甲第成。","醉里都将春作达，老来不向酒藏情。","齿疏无废衔杯趣，耳病犹分度曲声。","旧友昔游浑忘却，可怜寂寂洛阳城。"]},{"t":"景仁招游东园马上口占","f":"词","c":["适野自可爱，况逢佳主人。","马穿官柳影，衣拂帝城尘。","物外谁知乐，樽前别有春。","年华己消歇，历历见松筠。"]},{"t":"御沟 未开木芙蓉","f":"词","c":["木末采芙蓉，骚人歌所无。","何言霜花艳，不与水芝殊。","香苞麝脐结，茂叶桐阴敷。","岂若龟巢类，飘零老五湖。"]},{"t":"景福东厢诗 夜意","f":"词","c":["清夜四无哗，深严上帝家。","星翻珠网白，斗挂玉楼斜。","风静虚成韵，霜轻未作花。","还疑汉津客，浩荡寄流槎。"]},{"t":"御沟 读武士策","f":"词","c":["汉家求猛士，云集未央宫。","天外朝星淡，山西将种空。","奇谋纷并进，壮节凛生风。","八阵纵横势，依然见目中。"]},{"t":"御沟 菊","f":"词","c":["琐琐南阳菊，秋潭岁自开。","孤根拥红叶，落蕊媚苍苔。","正以参灵药，因之植紫台。","愿兼金掌露，同入柏梁杯。"]},{"t":"御沟","f":"词","c":["万户郁相钩，枝分瑟瑟流。","萦纡通桂观，隐见带龙楼。","碧映千林曙，红飘一叶秋。","寒波长不竭，岁岁奉宸游。"]},{"t":"御沟 赐酒","f":"词","c":["和气盈金榼，恩光湛玉觞。","应知北山羽，犹怯上林霜。","醇味回秋色，清都近醉乡。","山茅沾雨露，誓极寸心长。"]},{"t":"游三门开化寺","f":"词","c":["山石古来色，河流无尽声。","行船自往返，群木几枯荣。","狂象调难伏，空华灭复生。","我来何所得，聊此濯尘缨。"]},{"t":"游山呈景仁","f":"词","c":["我禄多龚舍，君年少孔戣。","道心闲始见，世路老方知。","山水不相厌，风光难豫期。","嬉游不可缓，花卉即离披。"]},{"t":"游延安宿马太博东馆","f":"词","c":["高馆寂无哗，安闲胜在家。","暮烟凝塞上，堠火落天涯。","坐久笔生冻，夜阑灯作花。","主人意未尽，归路不为赊。"]},{"t":"游李卫公平泉庄","f":"词","c":["相国已何在，空山馀故林。","向时堪炙手，今日但伤心。","陵谷尚未改，门阑不可寻。","谁知荆棘地，鹤盖旧成阴。"]},{"t":"游瀍上刘氏园","f":"词","c":["日暖孤台迥，露浓幽径微。","茅斋举白饮，沙溆踏青归。","照水清满眼，穿林香湿衣。","莫言春尚浅，已有杏花飞。"]},{"t":"湖上村家","f":"词","c":["万顷寒烟外，茅茨枕碧流。","枫林巢乳鹤，沙溆乱鸣鸥。","漠漠菰蒲晚，苍苍芦荻秋。","欲过南浦去，篱下出渔舟。"]},{"t":"答刘原父贺庞公惠炭","f":"词","c":["东郭先生履半穿，禦冬深愧主人贤。","应怜道上雪欲积，意使炉中灰复然。","曲糵暗添寒酒力，图书共免湿薪烟。","茅斋斗似饶光彩，客至何忧腊后天。"]},{"t":"答张伯常之郢州涂中见寄","f":"词","c":["适意遗轩冕，轻于鸿一毛。","扁舟千里远，佳句百篇豪。","酒饮宜城美，歌闻白雪高。","家林已春色，慎勿滞江皋。"]},{"t":"答陈进士谓之忆江东旧游见赠","f":"词","c":["客路今东去，亭皋木叶飞。","居然不堪恨，况与赏心违。","顾渚烟波阔，长洲草树微。","江边好春色，行望锦标归。"]},{"t":"紫微石舍人挽歌二首 其二","f":"词","c":["顾我非君比，最为相得欢。","平生游处久，美行始终完。","长夜忍埋玉，秋霜不借兰。","西风湿襟袖，空有泪阑干。"]},{"t":"紫微石舍人挽歌二首 其一","f":"词","c":["地胜岷峨秀，时清隽乂生。","扬雄晚得禄，何武少知名。","性有图书癖，心忘绂冕荣。","前年归谕蜀，不使里人惊。"]},{"t":"塞上 其四","f":"词","c":["剑客苍鹰队，将军白虎牙。","分兵逻圁水，纵骑猎鸣沙。","浪有书藏袖，难凭信达家。","不堪闻晓角，吹尽落梅花。"]},{"t":"塞上 其一","f":"词","c":["节物正防秋，关山落叶稠。","霜风壮金鼓，雾气湿旌裘。","未得西羌灭，终为大汉羞。","惭非班定远，弃笔取封侯。"]},{"t":"塞上 其三","f":"词","c":["瀚海秋风至，萧萧木叶飞。","如何逢汉使，犹未寄征衣。","不叹千里远，难甘一信稀。","年年沙漠雁，随意得南归。"]},{"t":"塞上 其二","f":"词","c":["鸿雁秋先到，牛羊夕未还。","旌旗遥背水，亭堠远依山。","落日衔西塞，阴烟澹北关。","何时献戎捷，鞍甲一朝闲。"]},{"t":"感兴寄聂之美","f":"词","c":["平生百无可，强为一官縻。","世味偏予薄，心期独子知。","林猿愁玉琐，枥马患金羁。","年事今华发，求荣欲为谁。"]},{"t":"感物","f":"词","c":["朝看新燕飞，暮听子规啼。","尺蠖身藏叶，神龟尾曳泥。","韝鹰何用掣，枥马不当嘶。","自伐憎狙巧，颓然忧木鸡。"]},{"t":"新买叠石溪庄再用前韵招景仁","f":"词","c":["一溪清水佩声寒，两岸莓苔锦绣斑。","三径谁来卜邻舍，千峰我已作家山。","鹿裘藜杖偏宜老，紫陌红尘不称闲。","早挈琴书远相就，放歌烂醉白云间。"]},{"t":"睢阳五老图","f":"词","c":["图谋已就乐时闲，晓向田园喜脱冠。","心志不灰犹有策，星长还在尚无桓。","朝阳鸣凤身轻暖，赴壑刚蛇齿健寒。","仪表珍藏传不朽，每于清士敬持看。"]},{"t":"辞坟","f":"词","c":["十年一展墓，旬浃复东旋。","岂负襁褓爱，横遭章绶缠。","更来知几日，遗恨恐终天。","恸哭出松径，悲风为飒然。"]},{"t":"鄜州怀聂之美","f":"词","c":["何言内外家，忧患两如麻。","别泪行三岁，思心各一涯。","海边昏雾雨，塞外惨风沙。","安得云飞术，乘空去不遐。"]},{"t":"酪羹","f":"词","c":["军厨重羊酪，飨士旧风传。","不数紫莼滑，徒誇素鲔鲜。","?蠡烦挏取，勺药助烹煎。","莫与吴儿说，还令笑茂先。"]},{"t":"酬不疑雪中书怀见寄","f":"词","c":["直道免三黜，敢云羞小官。","盘餐红粟涩，衣桁黑貂寒。","画府容身易，侯门曲意难。","荆扉盈尺雪，有客问袁安。"]},{"t":"酬师道雪夜见寄","f":"词","c":["玉树交横雪后天，银河沉着斗栏干。","笔峰微结冰丝涩，灯晕初成花烬残。","太学先生毡苦薄，公车倦客履仍单。","欲吟佳句到清晓，夜寂愁闻金石寒。"]},{"t":"酬君贶和景仁对酒见寄三首 其一 上宣徽","f":"词","c":["懒拙无时用，耆朋独我思。","乘闲同把酒，道旧各成诗。","高义刮眼膜，清风生鬓丝。","方将激衰俗，贱子实何为。"]},{"t":"酬君贶和景仁对酒见寄三首 上侍中","f":"词","c":["何事挂冠客，至今留帝台。","红尘终可厌，青眼不长开。","春路半消雪，寒枝初破梅。","南园虚客席，洒扫望公来。"]},{"t":"酬君贶和景仁对酒见寄三首 其二 上宣徽","f":"词","c":["北阙黄金印，西山白发翁。","吁谟帝廷异，小筑洛川同。","晴野峰峰碧，霜林叶叶红。","无因侍樽席，惆怅又秋风。"]},{"t":"酬宋叔达卜居洛城见寄","f":"词","c":["离群四十一春风，纵有相逢似梦中。","幸得相逢作邻舍，但嗟彼此是衰翁。","汉文前席人将去，庾信诛茅橐未充。","怅望金堤碧芜阔，杖藜携手几时同。"]},{"t":"酬张二十五秀才南园遣意","f":"词","c":["花卉日相续，朝昏兴寄新。","露荷香入坐，风竹净无尘。","啸咏皆群从，喧嚣远四邻。","须知轩冕客，富贵不关身。"]},{"t":"酬张三十秀才见赠","f":"词","c":["朴学居人后，清涂忝众先。","瓠因无用弃，木为不才全。","比得林泉趣，仍依邑里贤。","自惭头半白，方解赋归田。"]},{"t":"酬邵尧夫见示安乐窝中打乖吟","f":"词","c":["安乐窝中自在身，犹嫌名字落红尘。","醉吟终日不知老，经史满堂谁道贫。","长掩柴荆避寒暑，只将花卉记冬春。","料非空处打乖客，乃是清朝避世人。"]},{"t":"酬终南阎谏议见寄","f":"词","c":["齿衰心力耗，揣分乞西台。","微禄供多病，闲官养不才。","弊庐容啸傲，清洛伴归来。","故友犹相念，寒光生死灰。"]},{"t":"酬仲通初提举崇福宫见寄","f":"词","c":["富寿安民旧学违，符移拥笔素心非。","青云有路那足顾，白发满头胡不归。","永日杜门无俗客，临风隐几得天机。","西山爽气秋应好，恨不相从上翠微。"]},{"t":"臧郎中挽歌二首 其二","f":"词","c":["素履存诚厚，虚怀待物真。","乡闾昔相接，朋友世弥亲。","遗札蝇头细，长阡马鬣新。","九原那可作，空复想音尘。"]},{"t":"臧郎中挽歌二首 其一","f":"词","c":["积庆承前烈，呈才会圣时。","践杨朝有籍，治行吏为师。","僚友皆亲誉，黎民每去思。","惜哉违世早，志业未全施。"]},{"t":"题传灯录","f":"词","c":["呷著声闻酒便狂，它州浪走不归乡。","谁曾缚汝安用解，彼自无创勿误伤。","探月拾针传妄语，安居暇食赖先王。","但令时世如三代，达磨从他面向墙。"]},{"t":"题杨中正供奉洗心堂","f":"词","c":["阀阅盛山西，朱门飏戟衣。","雅知名教乐，深笑宴游非。","一室琴书隘，三年园圃稀。","异时论事业，肯复让轻肥。"]},{"t":"题陈秀才园林","f":"词","c":["剧谈惊满座，音貌独琅然。","可惜郦生老，谁知苏季贤。","青囊世外药，碧幕醉中天。","不佩黄金印，都缘负郭田。"]},{"t":"题致仕李太傅园亭","f":"词","c":["汉家飞将种，气概耿清秋。","解去金貂贵，来从洛社游。","清商拥高宴，华馆带长流。","可笑班超老，崎岖万里侯。"]},{"t":"赠太子太傅康靖李公挽歌词二首 其二","f":"词","c":["卤簿去悠悠，西郊乱叶秋。","旐翻寒日薄，笳咽断云愁。","吊客门飞鹤，佳城山卧牛。","灵车今不返，洧水日东流。"]},{"t":"赠太子太傅康靖李公挽歌词二首 其一","f":"词","c":["黄发今彫丧，苍生欲奈何。","散金才极乐，曳杖已成歌。","十郡馀恩在，三台故吏多。","位崇仍有后，五福更为多。"]},{"t":"赠吴之才","f":"词","c":["胜冠自立艰难里，大器由来贵晚成。","松柏傥非生磊落，岩崖何易出峥嵘。","苏秦游困羞妻嫂，主父居贫厌弟兄。","六印佗年拥车骑，会须重过洛阳城。"]},{"t":"赠学仙者","f":"词","c":["微径透重峦，茅堂竹叶冠。","方瞳映骨静，秀气逼人寒。","夜火装丹灶，晴霜醮石坛。","不须惊浅俗，轻举入云端。"]},{"t":"赠河中通判朱郎中","f":"词","c":["陟屺今将老，扶床昔未行。","旨甘无所展，朱紫不为荣。","里巷传呼入，比邻失涕惊。","方知贯金石，何以易精诚。"]},{"t":"赠狄节推","f":"词","c":["天马云孙在，终然骨相奇。","泥涂辱虽久，霜雪志难移。","白发无嗟老，青衫莫厌卑。","为山已九仞，高节肯中衰。"]},{"t":"赠清衍","f":"词","c":["我厌俗缘苦，空为薄宦牵。","如师真达者，于世亦超然。","敝笠冲尘陌，寒云拥雪天。","崎岖远相顾，深愧此心专。"]},{"t":"赠楚法曹叔度","f":"词","c":["夫君能直节，不耻杨曹轻。","道果因时屈，官无当已荣。","松杉虽偃蹇，霜霰苦峥嵘。","会有良工识，终观大器成。"]},{"t":"魏忠献公挽歌辞三首 其三","f":"词","c":["恻怛动旒扆，鸿胪葬老臣。","箫铙震淦口，绋翣隘漳滨。","久大英名在，哀荣异礼陈。","丰碑纪遗烈，长泣邺城人。"]},{"t":"魏忠献公挽歌辞三首 其二","f":"词","c":["爱物威容悴，忧公宿疹加。","孤忠贯白日，美志掩丹霞。","行路皆惆怅，闻风悉叹嗟。","英灵觐宗祖，犹想佑皇家。"]},{"t":"魏忠献公挽歌辞三首 其一","f":"词","c":["瀛海吁谟定，宗祧指顾安。","鸿勋柱石壮，劲节雪霜寒。","翼亮三朝久，初终一德完。","如何未黄发，垄柏已丸丸。"]},{"t":"八月十六日过天街怀景仁","f":"词","c":["秋潦收四野，晴云无一斑。","忽惊龙门缺，远见鸣皋山。","凉飙入毛发，颢气清心颜。","悠然念吾友，逍遥城阙间。","思陪篮舆尾，共此登临闲。"]},{"t":"又和惜春谣","f":"词","c":["朝来风雨歇，春意漠然收。","去我不辞诀，凭谁能借留。","杓星渐西转，洛水自东流。","曲渚撤华幄，芳园罢彩毬。","雉鸣丘麦秀，蚕起野桑柔。","乱絮天涯满，晴阳草际浮。","已嗟心绪减，况复鬓丝稠。","赖听新翻曲，非为负胜游。"]},{"t":"三月十五日宿魏云夫山庄","f":"词","c":["先生嫌俗宾，犹与故乡亲。","不惜烟霞地，暂容缰锁身。","林庐深有径，鸡犬四无邻。","蔌蔌闇花堕，苍苍古柏春。","饭炊松粒细，盘采蕨芽新。","静觉精神健，闲知气味真。","溪泉冷毛发，山翠湿衣巾。","竹色消酲易，林声破梦频。","客轮来去辙，驿路古今尘。","明日空回首，白云应笑人。"]},{"t":"太行","f":"词","c":["象帝胚浑散，愚公辙迹开。","横行四极外，蟠据九河隈。","岪郁天阍近，峥嵘地轴回。","阳崖明草树，阴壑转风雷。","波沓群峰涌，云奔峭壁来。","猿岩垂磊落，龙窟斗喧豗。","喷雨惊湍洒，跳垒巨石颓。","平途忧屐折，跬步戒轮摧。","覆顶千春雪，缘潭万古苔。","谷盘容国士，髓裂饵仙才。","晋市飞樵札，燕郊落烧煤。","棋图分冀野，蚁壤认丛台。","在昔王涂塞，尝闻霸略恢。","严关阴伏甲，间道夜衔枚。","挟诈挥金斗，贪功袭墨缞。","战场空爝火，京观悉蒿莱。","险易曾何变，兴亡只可哀。","隆平方恃德，襟带自崔嵬。"]},{"t":"用前韵再呈","f":"词","c":["旧友今馀几，追思鼻可酸。","休论身外事，且尽目前欢。","薜荔垂堤面，酴醾拥席端。","舞精抽茧绪，弦妙落珠盘。","醇酒回春易，灵丹却老难。","扶归不复记，酩酊上金鞍。"]},{"t":"亨杞下第作诗示之","f":"词","c":["清白君家旧，文章时态新。","何妨偶蹉跌，未必遂沈沦。","莫叹科名晚，惟忧道谊贫。","进修专在已，得失尽由人。","孝友亦为政，箪瓢足养亲。","那将少年泪，容易辄伤春。"]},{"t":"员村坂","f":"词","c":["穹谷郁盘纡，河濒陜北隅。","泉流涓不绝，冈势俨相扶。","初旭纷高下，空烟似有无。","石滩醒耳快，峤树脊云孤。","天霁岚光活，人稀草色苏。","牧儿歌自若，樵子远相呼。","坏道傍连传，空城右指虞。","穷岩今寂寞，蔓草只荒芜。","野店寒餐涩，山程瘦马瘏。","物华供兴趣，亦是慰崎岖。"]},{"t":"和任屯田感旧叙怀","f":"词","c":["结交英俊乐如何，风谊敦明寄咏歌。","自致青云今有几，化为异物已居多。","椟中本自沽良价，毫末安能滑至和。","邻笛不堪频叹息，酒炉那得重经过。","年华易度窗尘影，人事难期海水波。","贤业著鞭犹可在，况君壮齿未蹉跎。"]},{"t":"和君贶宴张氏梅台","f":"词","c":["京洛春何早，凭高种岭梅。","纷披百株密，烂漫一朝开。","青女工黏缀，霜娥巧剪裁。","昆山云满谷，蓬堵浪成堆。","势拥樽前合，香从席下来。","蜺旌羾天起，练甲洗兵回。","不使光风散，曾无夜色催。","人稠衣馥郁，地狭舞徘徊。","民服召公化，时推何逊才。","淹留文酒乐，璧月上瑶台。"]},{"t":"和君贶清明与上巳同日泛舟洛川十韵","f":"词","c":["繁华两佳节，邂逅适同时。","雅俗共为乐，风光如有期。","晓烟新里巷，春服满津涯。","已散汉宫烛，仍浮洛水卮。","占花分设席，爱柳就张帷。","华毂争门去，轻帘夹路垂。","三川云锦烂，四座玉山攲。","叠鼓传遥吹，轻桡破直漪。","清谈何衮衮，和气益熙熙。","想见周南俗，当年播逸诗。"]},{"t":"和吴冲卿病中偶书呈诸同舍光时亦卧疾","f":"词","c":["病来门不扫，秋草翳吾庐。","弃置贤人酒，萧条长者车。","冥迷床斗蚁，润溽箧生鱼。","药物从无继，箪瓢自有馀。","形神寂可吊，身世邈相疏。","何事文园客，痟中亦著书。"]},{"t":"和叔度独登天台水亭","f":"词","c":["郊外灵潭阔，新亭占曲堤。","戏鱼迎坠絮，惊雉出荒蹊。","绿倒杨梢乱，光翻芰叶齐。","雨馀纤月偃，野迥断云低。","水气常喷薄，天风助惨悽。","何知尘外境，近在郡楼西。"]},{"t":"和河阳王宣徽九日平嵩阁宴集","f":"词","c":["九日英僚集，千秋胜赏同。","飞桥贯河渚，危阁压霜风。","金散黄花泛，雷惊叠鼓通。","百峰高鸟外，万里寸眸中。","槛底临丹叶，杯中倒碧嵩。","来云低拂座，去雁远沈空。","吹帽陪游阻，摇旌结想丛。","风流免堙灭，邹湛倚羊公。"]},{"t":"和君贶暮秋四日登石家寺阁晓泛洛舟 泛舟","f":"词","c":["叶下宫槐老，云飞洛浦秋。","复陪元礼棹，却望仲宣楼。","曲岸迷频转，遥山碎不流。","夷犹聊寓赏，浩荡得忘忧。","晨出露渐径，昏归月满舟。","星河散寥廓，珠贝映汀洲。","林馆回车入，壶觞秉烛游。","山公兴未尽，徒御且番休。"]},{"t":"和潞公伏日宴府园示座客","f":"词","c":["盛阳金气伏，华宇玉樽开。","真率除烦礼，耆英集上才。","炎蒸疑远避，流景忘西颓。","幸忝俊游并，仍惭右席陪。","蒲葵参执扇，冰果侑传杯。","相国方留客，如何务早回。"]},{"t":"和潞公游天章楚谏议园宅","f":"词","c":["名卿新治第，上宰旧连墙。","槐荫青青叶，星邻两两光。","林花裂锦狭，门路筑沙长。","共引庭间水，交生壁外篁。","鱼窥荐琴石，萤散读书床。","玉帐方怀远，松斋欲就荒。","旌幢今少憩，兰蕙不徒芳。","早晚平狼望，同来举寿觞。"]},{"t":"奉和始平公酬大资政吴侍郎 其一","f":"词","c":["道盛经纶业，文高翰墨场。","雍容偃藩地，密迩钓璜乡。","回首红尘远，清心白日长。","山形抱城堞，溪影照公堂。"]},{"t":"钓鱼有感 其一","f":"词","c":["垂竿临晚岸，坚坐据莓苔。","饵落萍初散，鱼惊荷暂开。","有求虽琐细，未获且低回。","君识磻溪老，曾垂绿发来。"]},{"t":"南园杂诗六首 明叔家瑞莲","f":"词","c":["君家得莲种，远自浙江湄。","明烛然深盌，浓朱画细丝。","盛开尤菡萏，到落不离披。","岂独夏花好，仍兼秋实奇。","味长包石蜜，壳嫩剥燕脂。","况复芬芳久，霜前殊未衰。"]},{"t":"南园雨霁景物粗佳有怀正叔安之","f":"词","c":["洛阳秋雨阕，荒圃物华饶。","白鹤寒尤盛，红薇晚未彫。","鸟惊朱实堕，云灭翠岑遥。","扬子方嘲白，相如尚苦痟。","徘徊瞻望近，邂逅笑谈辽。","官冷惭无具，相思不敢招。"]},{"t":"奉和大夫同年张兄会南园诗","f":"词","c":["露浓秋过半，气爽雨收馀。","取酒邀嘉客，呼儿扫弊庐。","生涯数亩地，官业一轩书。","竹结垂纶屋，泉分入座渠。","惬心皆乐事，容膝即安居。","梁静栖无燕，波澄戏有鱼。","茂林穿缭绕，微径步虚徐。","果落方知熟，莎长不忍除。","过从当苦远，接侍每惭疏。","不厌茅茨陋，时迂长者车。"]},{"t":"秋夕不寐呈谏长乐道龙图","f":"词","c":["雨气生灯晕，霜寒入漏声。","疏篱过萤影，腐叶掩虫鸣。","丘壑违初愿，簪裾徇外荣。","丹心终夜苦，白发诘朝生。","恩与乾坤大，身如草木轻。","何阶见明主，垂拱视升平。"]},{"t":"追和张学士从沂公游广固城","f":"词","c":["苍鹅集宋幕，游鹿上燕台。","霸气山河尽，王师江汉来。","重围经岁合，严锁夜深开。","废殿馀沙砾，颓墙蘙草莱。","清时间千岁，良牧借三台。","狱市乘馀暇，芜城赋上才。"]},{"t":"送丁秘丞知雍丘","f":"词","c":["古县跨河流，人繁军市稠。","羽飞朝暮驿，鳞叠往来舟。","兄擅才华久，时推政治尤。","足犹妨老骥，目不碍全牛。","从道西来近，能无东望愁。","时因趋上府，穷巷一相求。"]},{"t":"送邵不疑知常州","f":"词","c":["宦学不营身，京华费十春。","非贪为郡乐，意欲与民亲。","祖帐青门道，归帆扬子津。","江山旧游在，烟火故乡邻。","敢惜离群阔，欣闻得吏循。","嗟余一囊米，溟负鬓丝新。"]},{"t":"送王待制知陜府","f":"词","c":["畴昔诚相契，间关分不渝。","绝弦悲宿草，抚首念诸孤。","位略尊荣间，年忘德齿殊。","清阴容息足，重语辱嘘枯。","鶠阁骞云表，虹旌拂海隅。","明光新出綍，陜陌重分符。","丰润还桑梓，欢讴复路衢。","宁须更条教，耆旧已箪壶。"]},{"t":"送史馆唐祠部江南西路转运使","f":"词","c":["豪杰争唐鹿，江南号富强。","明时虽混一，馀俗尚彫伤。","税版诛求急，词曹牒诉忙。","皇心悯颓弊，使节付才良。","贫吏先投绂，奸民尽越乡。","闾阎无插笔，田亩有栖粮。","汉阁归期阔，隋河去驿长。","风高片帆疾，钲鼓入秋光。"]},{"t":"送导江李主簿君俞","f":"词","c":["学海无涯富，辞锋一战勋。","声华掩终贾，赋颂继渊云。","五斗为边吏，千仓饱戍军。","明恩美尤异，优秩赏能勤。","黄祖阴怀怒，张汤巧用文。","折虽因木秀，烧不变兰薰。","迹有穷通异，心无得丧分。","龙蛇宁久蛰，玉石岂俱焚。","蜀国花饶思，临邛酒易醺。","西风时有意，尺纸慰离群。"]},{"t":"送次道通判西京","f":"词","c":["相府新承檄，兰台旧校文。","题舆荣得士，把袂惜离群。","首夏郊原秀，晴阳草树曛。","觚棱日边远，关塞雾中分。","翠岭林端出，飞泉竹外闻。","金羁游烂熳，珠履醉缤纷。","人服声光重，官无薄领勤。","归期肯留滞，汉主待渊云。"]},{"t":"送吴耿先生","f":"词","c":["儒服若烟海，几人潜圣心。","难才成自昔，贱学况于今。","夫子独神解，明时何陆沉。","大羹无和味，至乐寡知音。","磳磴貂裘弊，飘萧鹤发侵。","游秦不得意，思越动长吟。","甑米难求玉，经囊益少金。","拂衣谢宾友，纵棹指云岑。","积叶迷幽径，荒藤络旧林。","涧猿惊重至，野老喜相寻。","山色犹当户，弦声不变琴。","人生贵适意，何必慕华簪。"]},{"t":"送张少卿学士知洪州","f":"词","c":["相府典刑在，朝闺望实高。","紬书荣史观，典乐重卿曹。","夷路迎飞鞚，桑林应奏刀。","家籯传旧学，庙鼎刻前劳。","袨服屯千骑，连樯阅万艘。","剑芒冲夜气，阁影动秋涛。","风色传花信，烟光拂酒膏。","使君专问俗，无意在游遨。"]},{"t":"送祖泽之守陜","f":"词","c":["声教空岩穴，夫君集帝庭。","辞华动丹扆，光价塞青冥。","俊德争推毂，荣涂易建瓴。","陆离寒水玉，磊落曙天星。","得丧谁先识，艰虞困屡经。","蹉跎渥洼足，漂泊凤凰翎。","粉署疏恩纪，甘棠寄典刑。","仁风思布濩，疲俗待绥宁。","贱子良多愧，馀光每乞灵。","题名联士版，占籍备民丁。","种种颠毛白，萧萧垄柏青。","陌头瞻皂盖，独立涕飘零。"]},{"t":"送高陟归金陵","f":"词","c":["之子秣陵去，悠悠天堑东。","帆开晓风疾，潮落夜江空。","在昔才华盛，至今人物丰。","山川气虽尽，龙虎势犹雄。","卞玉已三献，齐禽会一冲。","当令关下吏，洗目认终童。"]},{"t":"送韩直讲郓州宁亲","f":"词","c":["车马俨何之，东冈旧有陂。","三年别亲意，千里达家时。","去仕元戎幕，来为太学师。","宁须负斗米，不复断机丝。","物色迎归鞚，光辉入寿卮。","人生无此乐，此乐独君知。"]},{"t":"寄题张著作善颂堂","f":"词","c":["玉垒老先生，逍遥乐太平。","门阑百客盛，冠盖一乡荣。","国族招邀近，堂皇指顾成。","江山对平远，图史散纵横。","止水中心适，秋毫物外轻。","鲤庭新露冕，闾巷不须惊。"]},{"t":"宝鉴贻开叔","f":"词","c":["流尘集宝鉴，尘昏鉴不昏。","纤泥落清水，泥浑非水浑。","人能辨二物，相与自忘言。","二物不能辨，悠悠何足论。","无为舍其内，逐外取烦冤。"]},{"t":"喜雨八韵呈明叔","f":"词","c":["蕴隆亦太甚，荟蔚不朝隮。","直可忧秋廪，非徒病夏畦。","民心或能彻，天造固难稽。","黯淡云才蔟，滂沱日未西。","衣襟坐来冷，城阙望中迷。","园笋新梢活，庭蕉湿叶低。","响从窗破纸，行喜屐生泥。","昨旦烦相报，凭君谢竹鸡。"]},{"t":"景仁将归颖昌辄为诗二十韵纪赠","f":"词","c":["秀发西南美，挺生河岳灵。","雕龙蔚文采，老鹤瑩仪形。","落笔高时隽，飞緌侍帝庭。","英声轶云汉，远势击沧溟。","苦节专忧国，嘉谋每据经。","温虽比圭璧，直不避雷霆。","道胜轩裳薄，神和气体宁。","忠诚怀畎亩，乐事寄林坰。","藻鉴评随月，过从德应星。","苦吟金出矿，确论木衔钉。","贱子叨流辈，高风仰典刑。","巨川容滴水，馀景借流萤。","久别眉俱白，重来眼更青。","淹留弦与晦，游集醉还醒。","有酒须相就，无歌不共听。","奇花喧夕市，叠鼓咽春亭。","扬袂行辞洛，回车去望陉。","往还天表雁，离合浪间萍。","异日期同传，穷泉约互铭。","古今难得事，交分保颓龄。"]},{"t":"答师道对雪见寄","f":"词","c":["阴风一夕惊，晓雪满都城。","气覆千家白，光连万象清。","恋空飞不下，弄态舞相萦。","历乱看无定，飘飖转未成。","缀垣时缺剥，压竹乍攲倾。","细隙过无滞，寒窗拂有声。","园林匀结练，观阁巧彫琼。","草木情先喜，乾坤意亦荣。","营魂顿疏健，病目暂虚明。","郢曲高谁和，羞将叩缶并。"]},{"t":"赏花钓鱼二首 其二","f":"词","c":["日丽芙蓉阙，春荣太液波。","苑门鸣玉集，辇路翠华过。","芳树周阿密，嘉鱼在渚多。","浮英入樽斝，颁首出蒲荷。","人乐熙熙德，臣赓旦旦歌。","万生同鼓舞，相与醉天和。"]},{"t":"赏花钓鱼二首 其一","f":"词","c":["飞廉通上苑，鳷鹊带天渊。","树色含春雾，波光静晓烟。","香飘仙仗外，花舞御卮前。","籊籊文竿袅，筛筛素鲔鲜。","误陪金马籍，愧奉柏梁篇。","愿献南山寿，宸游侍亿年。"]},{"t":"遣兴","f":"词","c":["京洛红尘里，闭门常独居。","虽无守道愧，终与趣时疏。","文举徒飞表，曹丘懒挟书。","谁怜从宦久，不及策名初。","待兔谋真拙，屠龙艺亦虚。","何当治归计，松菊绕吾庐。"]},{"t":"赠外兄吴之才","f":"词","c":["何须亲始重，友分固非疏。","况复羁孤极，同经忧患馀。","晚成应大器，先得类凡鱼。","游衍陪严忌，声华诵子虚。","蒲轮诏枚叔，驷马宠相如。","莫忘西都日，寒窗夜读书。"]},{"t":"宿南园 九月十一日夜雨宿南园韩秉国寄酒兼见招以诗谢之","f":"词","c":["雨多秋草盛，浓绿拥寒阶。","吾庐奥且曲，退缩如晴蜗。","小园已自隘，欲往泥沾鞋。","体羸畏风冷，室处门常䦱。","九日古所重，负此时节佳。","缅想使君宴，绮席临高斋。","肥羜堆玉盘，飞觞酒如淮。","楚舞陵湖波，茱萸落金钗。","神醒鼓吹喧，百叠疑倾崖。","欢馀忽我思，牙兵星火差。","潩泉耻独醉，醇味相与偕。","我饮虽不多，和气浩无涯。","梧子拾为果，拒霜伐为柴。","沼中数寸鱼，烹煎足为鲑。","谁言无以侑，绕渚多鸣蛙。","交道久衰薄，岿然见吾侪。","奈何数舍遥，晤语积年乖。","况乃辱嘉招，私心岂不怀。","轘辕石道涩，重以阴云埋。","虽有果下马，款段非渥洼。","临风徒竦踊，志愿焉能谐。","狂诗寄一笑，聊用当诙俳。"]},{"t":"二月中旬虑问过景灵宫门始见花卉呈君倚","f":"词","c":["贱生参府僚，勉强踰半岁。","终非性所好，出入意如醉。","讼庭敲扑喧，众草绝生意。","不知有青春，倏忽已改燧。","周章连日忙，烂漫数宵睡。","轩窗岌飞举，风雨颇恣睢。","谓言芳菲物，狼藉应扫地。","今晨呼马出，历狱问囚系。","窈窕清宫深，仓琅朱门闭。","广殿肃层阴，虚庭蔼佳气。","长杨委嫩绿，老柏净新翠。","薜荔垂蜿延，奇石立赑屃。","豁然愁愤开，精神四面至。","事役难少留，马去尚回睇。","亦足慰无聊，年华不都弃。"]},{"t":"八月十七日夜省直纪事呈同舍","f":"词","c":["穷秋直省舍，大雨吁可畏。","九河翻层空，入夜愈恣睢。","置床东壁根，时有涂塈坠。","飒飒势将摧，怵惕不成寐。","中宵抱衾立，呼烛久方至。","徙之近西偏，裯帐不能备。","飞蚊胡不仁，忍此加啄噬。","避烦只深藏，悒悒面蒙被。","须臾漏转剧，枕褥亦沾渍。","虽起欲何之，室中无燥地。","展转遂达旦，耿耿负忧悸。","因思闾井民，糊口仰执技。","束手已连旬，妻儿日憔悴。","囊钱与盎米，薪木同时匮。","败衣不足准，搏手坐相视。","予今幸已多，敢不自知愧。","无谋忝肉食，念尔但增欷。"]},{"t":"八月十五日夜宿南园怀王君贶","f":"词","c":["昔公在洛师，未尝弃嘉节。","今宵秋半分，空羡西园月。","天色湛澄清，风声冷骚屑。","笑言不可亲，引领望金阙。","赖有箧中诗，端居数披阅。"]},{"t":"八月十五日夜寄友人","f":"词","c":["故人音信绝，对月动相思。","清露滴红叶，此怀当告谁。","秋风广陵郭，正是望涛时。"]},{"t":"又代孙检讨作二首 其一","f":"词","c":["湖澄翠岫孤，胜地古东吴。","气象常时秀，英灵何世无。","金闺演王綍，玉帐绾兵符。","炜烨照乡曲，从兹益重儒。"]},{"t":"又和并寄杨乐道十二韵","f":"词","c":["圣主乐忠谏，曲从如转圜。","玉色粹阳春，至仁生自然。","所惭群臣愚，无以称开延。","贱生何为者，侧足青规前。","顽石不可鍊，安能补高天。","狂简昧大体，所依官长贤。","有如骖之靷，左右随周旋。","庶几助山甫，衮职无尤愆。","缅思老成人，阻亲函丈筵。","岂不寸心劳，动为缠徽牵。","何当执寿卮，跪起得差肩。","相顾藐无期，瞻望徒悁悁。"]},{"t":"又和岳祠谢雪题岳寺平法华庵","f":"词","c":["宴坐几何年，庭芜与砌连。","焚修真谛苦，功行得无圆。","阙里诗三百，赖乡文五千。","厌烦犹不读，何况淤泥莲。"]},{"t":"又和南园真率会见赠","f":"词","c":["白头难入少年场，林下相招莫笑狂。","绿筱影侵棋局暗，黄梅花渍酒卮香。","任真自愧殽羞薄，假寐初便枕簟凉。","酬应诗豪困牵率，从来懒放似稽康。"]},{"t":"又和雪","f":"词","c":["四檐冰管未全晞，一夕阴风雪又飞。","客卧牛衣忧死别，人留玉塞望生归。","公车岁晚怜东郭，辽海云深失令威。","颇忆当年映书否，物华如旧鬓毛非。"]},{"t":"又和夜雨宿村舍","f":"词","c":["积雨久未阕，岂徒行客忧。","夜闻屋中人，叹息悲田畴。","方春播殖时，种食皆外求。","鞭诃犯赤日，酷烈惭羸牛。","草秽竞禾长，从人借锄耰。","晨薅戴星起，日闇未能休。","岂无一时勤，所觊岁有秋。","今兹昏垫灾，大野成洪流。","直疑沧海溢，茧栗浮陵丘。","昔时百丈原，汎汎皆挐舟。","乔木失端杪，饥鸟下无投。","黍稷沉黄泥，圭合安可收。","嗟予乏技能，无以易糠麰。","贩鬻固所昧，敢托市井游。","欲依盗贼群，懦不闲戈矛。","已哉任天地，无益徒为愁。","一身无死所，况为妻儿谋。","之美爱物者，凄然涕沾裘。","一夫有不获，伊尹为深羞。","何当富斯民，比屋囷仓稠。","惜哉禄秩卑，此志终宜酬。"]},{"t":"三月三十日微雨偶成诗二十四韵书怀献留守开府太尉兼呈真率诸公","f":"词","c":["春尽少欢意，昏昏睡思添。","正忧花意索，更用雨声兼。","乍语莺喉涩，慵飞柳絮黏。","落英红没砌，茂草碧侵帘。","宝相锦铺架，酴醾雪拥檐。","沼萍浮钿靥，林笋露犀尖。","坐惜光风驶，行愁畏日炎。","追随任尘甑，歌笑望霜髯。","落笔诗情放，飞觥酒令严。","金丹呼胜彩，玉烛擢新签。","傲岸冠巾侧，淋浪襟袖沾。","饥仍留瘦马，归必待清蟾。","筋力虽无几，娱游亦未厌。","脱身离簿领，适性得闾阎。","多病非辞贵，无才岂养恬。","清涂诚愧忝，微禄已伤廉。","日费须三爵，年支仰数缣。","糇粮粗能足，蓍蔡不烦占。","河洛今为盛，图书昔所潜。","家家花启户，处处酒飘帘。","温饱资兼爱，安平倚具瞻。","愚夫犹乐育，下客愈撝谦。","落拓形骸逸，优游岁月淹。","馀生信多幸，狂醉亦无嫌。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其三","f":"词","c":["塞下春寒在，东风雪满须。","河阳机上妇，知我苦辛无。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其五","f":"词","c":["空外游丝转，飘扬似妾心。","别来今几日，彷佛近雕阴。"]},{"t":"之美访及不获展奉以诗为谢","f":"词","c":["昔君来阙下，定馆必吾庐。","今者虽相值，依然是索居。","不堪休沐少，便使往还疏。","深愧原思巷，空回长者车。"]},{"t":"子厚先生哀辞","f":"词","c":["先生负材气，弱冠游穷边。","麻衣揖钜公，决策期万全。","谓言叛羌背，坐可执而鞭。","意趣小参差，万金莫留连。","中年更折节，六籍事精研。","羲农讫周孔，上下皆贯穿。","造次循绳墨，儒行无少愆。","师道久废阕，模范几无传。","先生力振起，不绝尚联绵。","教人学虽博，要以礼为先。","庶几百世后，复睹三王前。","释老比尤炽，群伦将荡然。","先生论性命，指示令知天。","声光动京师，名卿争荐延。","寘之石渠阁，岂徒修简编。","丞相正自用，立有荣枯权。","先生不可屈，去之归卧坚。","孤嫠聚满室，糊口耕无田。","欣欣茹藜藿，皆不思肥鲜。","近因诏书起，寻取病告旋。","旧庐不能到，丹旐风翩翩。","人生会归尽，但问愚与贤。","借令阳虎寿，讵足骄颜渊。","况于朱紫贵，飘忽如云烟。","岂若有清名，高出太白巅。","门人俱绖带，雪涕会松阡。","厚终信为美，继志仍须专。","读经守旧学，勿为利禄迁。","好礼效古人，勿为时俗牵。","修内勿修外，执中勿执偏。","当令洙泗风，郁郁满秦川。","先生傥有知，无憾归重泉。"]},{"t":"小园晚饮","f":"词","c":["公府丰暇豫，真成弃掷春。","招邀俱胜友，烂漫醉芳辰。","花艳秾无敌，文锋健有神。","犹胜拥朱墨，终日坐埃尘。"]},{"t":"小雨","f":"词","c":["云日互出没，数朝飞雨清。","曈昽似欲止，廉纤还未晴。","映空轻丝乱，著物细珠明。","叶端危未落，荷心重忽倾。","喜凉高燕舞，便湿群蛙鸣。","于予亦有得，药畹胡麻生。"]},{"t":"不寐","f":"词","c":["思梦久不效，良夜行已阑。","此心如杯水，扰易澄苦难。","百年能几何，万虑谁能殚。","弃置勿复寻，专取形神安。"]},{"t":"云","f":"词","c":["晴空碧于水，那得片云飞。","映日成丹凤，随风变白衣。","去来皆绝迹，隐显两忘机。","天理谁能测，终然何所归。"]},{"t":"介甫巫山高命光属和勉率成篇真不知量","f":"词","c":["巫山高，巫山之高高不极。","寒江西来曳练长，群峰森罗十二戟。","清狖悲号裂翠崖，老蛟怒斗摧丹壁。","轻生重利三巴客，一叶直冲高浪白。","船头吟啸坐自如，仰视长天不盈尺。","丛祠象设俨山椒，巫祝纷纷非一朝。","云是高唐神女之所处，至今暮雨常萧萧。","我闻神理明且直，兴亡唯观恶与德。","安肯来从楚国君，凭依梦寐为淫昏。","襄王之心自荒惑，引领日望阳台云。","独不思怀王西行不复返，甲光照地屯秦军。","蚕食黔中下荆门，陵园宗庙皆烧焚。","社稷飘零不复存，嗟嗟若敖鼢冒时，筚路蓝缕皆辛勤。"]},{"t":"从始平公城西大阅","f":"词","c":["沧溟浴日照春台，组练光中玉帐开。","汾水腾凌金鼓震，西山宛转旆旌回。","逍遥静散晴空雨，叱咤横飞迥野雷。","坐镇四夷真汉相，武侯空复道英才。"]},{"t":"友人楚孟德过余纵言及神仙余谓之无孟德谓之有伊人也非诞妄者盖有以知之矣然余俗士终疑之故作游仙曲五章以佐戏笑云 其五","f":"词","c":["柂师知子能操舟，稳过茫茫沧海流。","白浪驾天千万里，真令挂骨长鲸齿。"]},{"t":"友人楚孟德过余纵言及神仙余谓之无孟德谓之有伊人也非诞妄者盖有以知之矣然余俗士终疑之故作游仙曲五章以佐戏笑云 其二","f":"词","c":["仙术有无终未知，眼看白发乱如丝。","何时得接浮丘袂，沧海横飞万馀里。"]},{"t":"友人楚孟德过余纵言及神仙余谓之无孟德谓之有伊人也非诞妄者盖有以知之矣然余俗士终疑之故作游仙曲五章以佐戏笑云 其一","f":"词","c":["神仙谓无还似有，秦汉可怜空白首。","会须一蹑青云梯，与子同祛千古疑。"]},{"t":"友人楚孟德过余纵言及神仙余谓之无孟德谓之有伊人也非诞妄者盖有以知之矣然余俗士终疑之故作游仙曲五章以佐戏笑云 其四","f":"词","c":["仙家不似人间欢，瑶浆琅菜青玉盘。","乘醉东游憩阳谷，酒瓢闲挂扶桑木。"]},{"t":"双竹","f":"词","c":["但有岁寒心，两三竿也足。","虬腾双角直，鲸喷两须长。"]},{"t":"双竹诗","f":"词","c":["上苑通丹禁，脩林绕玉堂。","周阿纡镂槛，并干擢新篁。","萧洒骈瑶甃，连翩拂璧珰。","虬腾双角直，鲸喷两须长。","晓泊烟华重，晴留雨气凉。","分音成律吕，齐秀待鸾凰。","碧借云霞润，清依日月光。","物情知有谓，天造固无方。","比节群诚合，虚心至道彰。","吾君愈勤德，不敢有嘉祥。"]},{"t":"天马歌","f":"词","c":["大宛汗血古共知，青海龙种骨更奇。","网丝旧画昔尝见，不意人间今见之。","银鞍玉镫黄金辔，广路长鸣增意气。","富平公子韩王孙，求买倾家不知贵。","芙蓉高阙北向开，金印紫绶从天来。","路人回首无所见，流风瞥过惊浮埃。","如何弃置归皂栈，踠足垂头困羁绊。","精神惨澹筋骨羸，举目双睛犹璀璨。","伏波马式今已无，子阿肉腐骨久枯。","举世无人相骐骥，憔悴不与驽骀殊。","神兵淬砺精芒在，宝鉴游尘肯终晦。","君今鬋剔被鸣鸾，尚能腾踏昆崙外。"]},{"t":"忆同寻上阳故宫路","f":"词","c":["上阳门外云连草，车马遥遥往来道。","昔王游豫几何年，今人岂识当时好。","明珠翠羽已成尘，道上行人几番老。","当时秋天落宫槐，今此婆娑皆合抱。"]},{"t":"王书记以近诗三篇相示各摭其意以诗赓之 其三 呈景仁","f":"词","c":["剑山中断融为川，清江双流郁回旋。","沟塍阡陌粲如绣，香粳紫芋皆良田。","地灵物秀气淑美，由来衮衮生英贤。","朝家文明所及远，于今台阁尤蝉联。","猎缨鸣佩走声望，出入金马如云烟。","奈何应辰独壈坎，华发未得离宾筵。","玙璠悬黎已为宝，结绿岂得偏弃捐。","愿君弹冠自重惜，邑人行诵子虚篇。"]},{"t":"王书记以近诗三篇相示各摭其意以诗赓之 其二 投圣俞","f":"词","c":["圣俞精为诗，坚重比白玉。","至宝识之希，未必谐众目。","应辰仰高风，跂耸自西蜀。","平生未相识，歉歉不自足。","薄游困京师，旅食止脱粟。","得官当入秦，行李未结束。","先求圣俞门，执贽请所欲。","九衢季冬月，风沙正惨黩。","羸马惮远行，毛鬣寒瑟缩。","旅拒不肯前，一步九刺蹙。","饥童袖拥口，手足尽皲瘃。","论诗久未出，窃骂怨满腹。","归来面扬扬，气若饫粱肉。","累累数十字，疏淡不满幅。","自谓获至珍，呼儿谨藏蓄。","长安十五驿，重复问川陆。","置诗怀袖间，勌懑辄披读。","高吟桑野阔，目瞑即投宿。","自可忘羁愁，行瞻灞陵曲。"]},{"t":"王书记以近诗三篇相示各摭其意以诗赓之 其一 感遇","f":"词","c":["白鹄出江渚，刷羽何鲜新。","志陵青霞端，欲饮天汉津。","清飙未我与，陂泽聊逡巡。","偶为虞罗获，远趣无由伸。","樊笼厌局促，野性那能驯。","庭除数惊顾，惨惨常畏人。","皓素不入俗，众目谁为珍。","稻粱不充腹，日与鸡鹜邻。","举头畏太高，俛啄空愁辛。","萧萧敛六翮，憔悴伤精神。","男儿五十不如意，青衫华发游埃尘。","向为盐官北如晋，今为幕吏西适秦。","慨然遂欲抛手板，拂衣高蹈锦水滨。","长竿短艇入烟雨，放歌酣饮攲乌巾。","方今圣朝清似水，林空谷静无隐沦。","吾君梦卜偶未到，勿学君平与子真。"]},{"t":"王君贶宣徽垂示嵩山祈雪诗十章合为一篇以酬之","f":"词","c":["今秋少雨冬不雪，麦寄浮埃根欲绝。","圣主焦心闵万民，负扆不怡常膳撤。","诏书朝下遍九州，岳渎百神俱祷求。","西都留守虔君命，促驾不敢须臾留。","嵩高万仞蟠地中，海内众山无与雄。","前驱大旆拥千骑，波腾云涌来祠宫。","牲肥酒香笾豆洁，盛服斋明荐毛血。","有司执事皆肃然，宝帐神来风窣屑。","公心犹畏九阍遥，丹诚不能通青霄。","分留导从屯林麓，别张醮具登山椒。","山椒迢遰峻无极，行挽枯藤蹋危石。","万室嗷嗷愁死饥，敢惮劬劳爱馀力。","天门上出俄坦平，下视一世尘杳冥。","焚香拜手倾恳恻，左右前后皆列星。","公今三守三川地，咫尺嵩高未尝至。","诘朝既毕祠事严，暂转鸣珂历诸寺。","少林昔为达摩居，达摩英灵今有无。","瘦辞流散满天下，竞以两手扪空虚。","法王魏氏离宫旧，玉刻狻猊向犹有。","子孙宗庙皆尘灰，止见伽蓝存不朽。","会善庭隅千岁松，一根二股凌寒空。","势如鼎足争秀出，泠泠永夜吟霜风。","少室先生乐闲暇，弃官来家玉峰下。","昔为浪泊据鞍人，今结东陵卖瓜舍。","溪上有堂名挂冠，四垣重复皆林峦。","呼儿扫地喜公到，随分弦歌留尽欢。","周王太子名闻久，相传羽化缑山首。","鹤飞笙远窅无迹，遗庙今人空沥酒。","公来本不事遨嬉，周流闾里询疲羸。","亲呼令长嘱赤子，勿贪荣利穷鞭笞。","境中群望无不走，回辔仍过凿龙口。","奉先暮投林日曛，浥涧晨征辙冰厚。","归来新诗盈一编，明珠大贝相属联。","此行虽不从公后，历历胜游皆目前。"]},{"t":"长垣道中作","f":"词","c":["极目王畿四坦然，方舆如地盖如天。","始知恃险不如德，去杀胜残已百年。"]},{"t":"风林石歌","f":"词","c":["闻君家有风林石，镌刻无痕画无迹。","靡然合势俱左倾，偃蹇常如负风力。","置之坐侧野意生，静听若有飕飕声。","忽疑身世在丘壑，使我萧然无俗情。","黄金白璧岂非好，子直视之不为宝。"]},{"t":"风雪数日不见叔度晚约公明共诣之 其二","f":"词","c":["南荣卮酒罢，君返道东居。","坐作三朝别，杳疑千里馀。","闲门嗟雀网，深泞怯柴车。","向晚开帘喜，彤云稍觉疏。"]},{"t":"冬夜","f":"词","c":["冬夜何其永，寒光四泬寥。","雁横星历历，人静漏迢迢。","破屋霜应重，荒庭雪未消。","不眠何所念，达晓思无憀。"]},{"t":"出都日涂中成","f":"词","c":["贱生习山野，愚陋出于骨。","虽为冠带拘，性非樊笼物。","扬鞭出都门，旷若解徽绋。","是时天风恶，灵沼波荡汩。","龙鬣互骞腾，鸥群远浮没。","川原寖疏豁，烟火稍萧瑟。","草木虽未荣，春态先彷佛。","桑稀林已斜，柳弱条可屈。","蛛丝罥晴阳，鼠土壅新窟。","徐驱款段马，放辔不呵咄。","与尔同逍遥，红尘免蓬勃。"]},{"t":"去岁与东郡幕府诸君同游河亭望太行雪饮酒赋诗今冬罢归京邑怅然有怀","f":"词","c":["畴昔追清景，狂吟忘苦寒。","河冰塞津口，山雪照林端。","健笔千篇富，醇醪一醉欢。","困犹挥落麈，瞑不顾归鞍。","多是光阴驶，离群会合难。","谁知尘满袖，今日客长安。"]},{"t":"古坟","f":"词","c":["茫茫野田平极目，历历古坟如夏屋。","碑板无文荆棘深，石兽沈沦松柏秃。","问人虽不知姓名，昔皆高官仍厚禄。","子孙流落何所之，凶吉当年非不卜。","我来正值寒食天，祭膰不设无人哭。"]},{"t":"古诗赠兴宗","f":"词","c":["穷达有常分，得丧难豫言。","古今浩茫茫，倚伏安可原。","轩裳彼自荣，举俗同崩奔。","锱铢校重轻，冰火殊凉温。","君子固无愧，立身明本根。","度矩苟不愆，宠辱徒喧喧。","有如清济流，横贯长河浑。","景公马千驷，南面雄东藩。","陶青刘舍徒，位为丞相尊。","当时非不显，磨灭何足论。","颜回在陋巷，藜藿甘盘飧。","原宪结弊衣，蓬蒿塞其门。","当时岂不穷，至今荣名存。","况君齿方壮，德业素所敦。","安知拓翅归，不作凌云翻。","要之白首期，壮烈施元元。","为君画善策，洒扫清前轩。","长舒四五榻，客来辄开樽。","群愁喜伺人，稍醒必烦冤。","拒之亦无佗，体中常昏昏。"]},{"t":"圣俞惠诗复以二章为谢 其一","f":"词","c":["我得圣俞诗，于身亦何有。","名字托文编，佗年知不朽。"]},{"t":"圣俞惠诗复以二章为谢 其二","f":"词","c":["我得圣俞诗，于家果何如。","留为子孙宝，胜有千年珠。"]},{"t":"归田诗 其五","f":"词","c":["桑柘绿无际，田间戴胜飞。","清醪迎社熟，鸣雉向春肥。","执耒时将急，衔杯日渐稀。","四邻能共乐，招饮莫相违。"]},{"t":"正月三日与广渊同出南薰门分趋斋宫涂中有作","f":"词","c":["并辔出都门，葱茏日欲昕。","野寒馀宿雪，树闇湿春云。","未望郊宫近，先愁马首分。","一朝犹恋恋，可复久离群。"]},{"t":"用安之韵招君从安之正叔不疑二十六日南园为真率会 其一","f":"词","c":["榆钱零乱柳花飞，枝上红英渐渐稀。","莫厌衔杯不虚日，须知共力惜春晖。"]},{"t":"用安之韵招君从安之正叔不疑二十六日南园为真率会 其二","f":"词","c":["真率春来频宴聚，不过东里即西家。","小园容易邀嘉客，馔具虽无亦有花。"]},{"t":"田家","f":"词","c":["未塞豪人夺，何言公赋收。","皇心虽恻隐，蓬户或焦愁。","为吏空多禄，无人能此忧。","知君坐公府，佗日富民侯。"]},{"t":"石昌言学士宰中牟日为诗见寄久未之答今冬罢武成幕来京师此诗谢之","f":"词","c":["昔年三月浪，鳞翼化云雷。","竹箭流俱上，芙蓉幕对开。","瀵泉扬沸渭，泰华耸崔嵬。","捧檄容归省，飞觞复屡陪。","芬芳袭芝室，嘉庆侍兰阶。","吴璧评残笔，隋碑读渍苔。","清阴依玉树，和气乐春台。","薄宦俄成别，私门忽遇灾。","一朝捐綵服，五载泣粗缞。","季路还从仕，任安独见哀。","近畿须健令，剧邑试长才。","过目全牛解，迎锋巨蘖摧。","雉留乘荫伏，蝗避境苗回。","时得鸣琴暇，仍飞丽句来。","正知荣箧笥，无足报璿瑰。","紞鼓俄攀邓，安车已召枚。","赋成平乐馆，燕奉柏梁杯。","自顾诚驽缓，于今尚草莱。","履穿羞路雪，盖敝怯京埃。","傥借馀光便，炎风动死灰。"]},{"t":"示道人","f":"词","c":["天覆地载如洪炉，万物死生同一涂。","其中松柏与龟鹤，得年稍久终摧枯。","借令真有蓬莱山，未免亦居天地间。","君不见太上老君头似雪，世人浪说驻童颜。"]},{"t":"乌栖曲二首 其一","f":"词","c":["风破金铺结绮钱，穿帘入幌舞垂莲。","可怜无人夜不晓，起视西窗月华皎。"]},{"t":"兴宗南园草盛不剪仆过而爱之为诗以赠","f":"词","c":["君家在何许，远与南城邻。","车马不甚繁，门前无俗尘。","有园废锄治，绕舍皆荆榛。","入夏益滋蔓，鬖鬖高没人。","岂无旧桃李，芜杂与之均。","谓言彼草木，于我奚疏亲。","于间置取舍，岂得完天真。","不若任其然，同受雨露仁。","物性且不违，人心何缁磷。","闭户不迎客，箕踞无冠巾。","苟忘轩冕心，何异巢居民。"]},{"t":"再使河北","f":"词","c":["桑麦青青四月初，皇华使者又脂车。","为臣岂得辞王事，寿昌侍郎巽之子。"]},{"t":"华星篇","f":"词","c":["凉风净扫云无迹，海月未生星历历。","贝联珠贯拱北辰，三五纵横此何夕。","重楼叠榭出秋空，鳷鹊露寒连桂宫。","瑶井迥临丹阙外，玉绳斜挂琐窗中。","征人远别空闺悄，钟漏萧疏天不晓。","碧纱展转无复眠，卧视寒光度华沼。","汉家贤将戍临洮，结发从军今二毛。","谁怜身老心犹壮，深入长占太白高。","丰城古剑沉沦久，匣中夜半双龙吼。","乃知神物不自藏，紫气依稀见牛斗。","有客离居望所亲，遥知清夜会荀陈。","堤繇未息无由去，不及浮槎河畔人。"]},{"t":"华州祗役往冯翊留别楚正叔","f":"词","c":["芳菲不得驻，会取馀春还。","欲知回首处，渭曲苍茫间。"]},{"t":"同子骏题和乐亭","f":"词","c":["春禽弄晴朝，秋虫吟雨夕。","风和振兰芳，露寒滋菊色。","万物苟得所，随时各有适。","矧伊人最灵，胡为长戚戚。","圣人垂大训，灿烂著方册。","至乐和无声，大礼简无迹。","心专守中庸，身不蹈邪僻。","造次常在前，须臾不离侧。","穷通虽百变，何往不自得。","兹亭聊寓名，和乐在胸臆。"]},{"t":"同圣民过杨之美听琵琶女奴弹啄木曲观诸公所赠歌明日投此为谢","f":"词","c":["坐曹据案心目疲，出门上马行何之。","阙然久不见之美，率意共往初无期。","正逢揽辔欲有适，为我却解连环羁。","闲轩适足容数客，夏木初繁有佳色。","呼儿取次具杯盘，青眼相逢喜无极。","檀槽锦带小青娥，妙质何须誇绮罗。","按弦运拨惊四座，当今老手谁能过。","弹为幽鸟啄寒木，园林飒飒风雨和。","喙长爪短跃更上，丁丁取蠹何其多。","曲终拂羽忽飞去，不觉酒尽朱颜酡。","已闻啄木曲，又观啄木歌。","雄文更复值绝艺，有如天际倾长河。","今朝壮观诚极乐，去此将奈寂寞何。","归来解带豁胸腹，坐踞胡床仰看屋。","从今三日不洗耳，耳内泠泠有残曲。","人间何物号富贵，纡紫怀金尽虚器。","如君自处真得策，身外百愁都掷置。","太学餐钱月几何，客来取酒同醒醉。"]},{"t":"同君倚过圣俞","f":"词","c":["王畿天下枢，薄领日填积。","自非奉朝请，九衢未尝识。","今兹到东城，胥靡暂逃役。","近指圣俞居，安能不往觌。","一室静萧然，昏碑帖古壁。","叩阶读新诗，迷闇得指擿。","笑言殊未足，黯然日将夕。","呼马涉归涂，灯火已历历。","又知几何时，更有重来迹。"]},{"t":"同舍会饮金明沼上书事","f":"词","c":["日华骀荡金明春，波光净绿生鱼鳞。","烟深草青游人少，道路苦无车马尘。","石渠诸君职事简，载酒撷花畏花晚。","浮舟逐胜任所之，箕踞狂歌叩舷板。","眼花耳热气愈豪，掷杯击案声嗷嗷。","惊沙飒飒绕洲渚，鱼龙迁去避我曹。","人生大料无百岁，贵贱贤愚同一致。","在家殽蓛馀几何，一日风光不宜弃。"]},{"t":"延安道中作","f":"词","c":["羁旅兼边思，川原蹀血新。","烟云长带雨，草树不知春。","细水淘沙骨，惊飙转路尘。","今朝见烽火，白首太平人。"]},{"t":"戏下歌","f":"词","c":["项王初破函关兵，气压山河风火明。","旌旗金鼓四十万，夜泊鸿门期晓战。","关东席卷五诸侯，沛公君臣相视愁。","幸因项伯谢前过，进谒不敢须臾留。","椎牛高会召诸将，宝剑泠泠舞席上。","咸阳灰烬义帝迁，分裂九州如指掌。","功高意满思东归，韩生受诛不复疑。","区区蜀汉迁谪地，纵使倒戈何足为。"]},{"t":"早春戏作呈范景仁","f":"词","c":["闰馀春意早，卉木先有思。","嘤嘤群鸟翔，东西各求类。","伊予忝谏垣，动息抱忧悸。","衮职旷不补，言责真可畏。","况复禁过从，陋巷若囚系。","茅茨庇风雨，偏隘无馀地。","时于坏垣隙，历历生新荠。","君侯乃比邻，跬步难自致。","常思去岁初，西轩学歌吹。","座客皆故人，欢笑无拘忌。","平生不喜酒，是日成烂醉。","岂言长揖归，良会难再值。","东风忽复来，时华一何驶。","丛竹固无恙，夭桃作花异。","朝廷正清明，讵肯容窃位。","何当遂废放，欢饮还自恣。"]},{"t":"旬虑十七韵呈同舍","f":"词","c":["府官无旬休，虑问乃游息。","诏书禁从诣，还舍始朝食。","缓带对藜羹，下箸免促迫。","门前吏卒散，却扫谢来客。","北轩有藤床，今晨始拂拭。","蓬发乱宜梳，霜髭闲可摘。","开囊晒药物，发笥出书册。","菊畦亲灌浸，茶器自涓涤。","于时孟秋末，天晴色绀碧。","林叶虽未零，风声已淅沥。","神明还九藏，清气袭百脉。","征夫解甲胄，疲马脱羁靮。","蜚鸟开樊笼，跳鱼出鼎鬲。","形骸尽我有，不复为物役。","虽非久安逸，幸得少顷适。","讼庭止敲扑，咫尺异喧寂。","明朝不能然，顾盼愁月夕。"]},{"t":"次韵和邵不疑假书江邻几知方酣寝为诗通意","f":"词","c":["江翁顺天和，心迹两夷简。","虽如边韶寝，且异宰予懒。","平居无时闲，经史自课限。","高歌慕翰林，鸣琴写中散。","翛然物外人，强为章绶绾。","官舍苦秋霖，瞬息聊休眼。","勤勚已有馀，宴安何愧赧。","借书谁敢惊，攲枕尚未暖。","不疑神骥才，垂耳困皂栈。","碌碌随吾侪，拜揖把手版。","毋嫌朱墨倦，腾举已为晚。","慎勿思山林，山林付愚孱。"]},{"t":"次韵和吴冲卿秋意四首 其一 扫枣好草倒","f":"词","c":["槐花满庭除，籍籍不可扫。","稍疏召平瓜，渐熟王阳枣。","失时团扇弃，新进袷衣好。","日暮益愁思，寒螀起幽草。","忽闻秋兴篇，叹赏几绝倒。"]},{"t":"次韵和吴冲卿秋意四首 其四 后牖有朽柳","f":"词","c":["弱植生川泽，托根北堂后。","昔时青春姿，扶疏映轩牖。","风霜日消落，憔悴复何有。","蠹穿枯节断，雨渍虚心朽。","幸不夭天年，犹得胜凡柳。"]},{"t":"次韵和吴冲卿秋意四首 其三 偏眠船舷边","f":"词","c":["纵棹下清溪，波静地仍偏。","日夕水风凉，萧洒成安眠。","兀兀但高枕，悠悠还进船。","中流忽惊寤，渔父歌扣舷。","山川非向时，回首云霞边。"]},{"t":"次韵和吴冲卿秋意四首 其二 窥梨卑枝垂","f":"词","c":["端居倦烦暑，园圃久不窥。","雨馀秋气新，红叶生紫梨。","形骸得萧散，不知环堵卑。","何能效流俗，把酒须菊枝。","登高已可醉，四野青云垂。"]},{"t":"次韵和邻几秋雨十六韵","f":"词","c":["气象殊朝夕，兴居错晦明。","混元初不宰，霪雨浩无程。","蛰隘宁天意，咨嗟固物情。","曣㬈方有望，荟蔚已随生。","杲杲升还隐，悽悽断复行。","乱莎长被径，荒藓绿缘甍。","辙迹康庄绝，潢污垄亩平。","茅茨不足庇，禾黍若为成。","蟋蟀颓墙泣，蛜蝛坏灶盈。","乘时众鸥舞，得意怒蛙鸣。","牛马谁分异，萧兰已混并。","居闲犹叵度，负重况遐征。","舟泊川无渚，轮摧路有坑。","轑羹愁病妇，炀灶拥寒婴。","灾不妨明德，神应格至诚。","淳光终下烛，时藿久心倾。"]},{"t":"次韵和韩子华寒食休沐与诸公同会赵令园暮归马上偶成","f":"词","c":["冠盖连翩陌上来，风光烂漫拥楼台。","玉卮贮酒随宜饮，绮席寻花触处开。","小雨前宵先拨火，季春明日又吹灰。","须知胜集人间少，惆怅金羁容易回。"]},{"t":"自用前韵","f":"词","c":["耿耿寐不成，迢迢夜未阕。","良朋悔不留，负此当轩月。","怀想空郁陶，眺听转清绝。","佗时重见过，馀樽犹可洁。"]},{"t":"西台诗二十四韵","f":"词","c":["翰苑昔陪侍，天光辱顾瞻。","宠虽承涣汗，功不立毫纤。","山鹿缨频顿，铅刀砺不铦。","拭花眸子缺，撚雪颔髭添。","局影惭尸素，胡颜处禁严。","辞盈虽免戾，取少讵因廉。","定鼎分都异，张官执法兼。","剡章愚恳尽，出綍茂恩沾。","原宪非无粟，胡威尚有缣。","求田近瀍洛，买宅混闾阎。","地僻宜花卉，儿勤付米盐。","倦游良足悔，居吉不烦占。","裘葛肤无见，囷仓饭属餍。","僧居闲可借，野步静无嫌。","行乐筇枝瘦，延宾稻醴甜。","麦田泥试屐，桑荫帽低檐。","爱竹忙犹种，贪书老未厌。","松烟溪石润，檀烬博山尖。","笺启来慵拆，衣冠脱怕拈。","紫毫斜倚架，黄卷密垂签。","涸辙犹蒙润，寒灰免附炎。","所忧资秩满，但愿岁时淹。","自是散无用，非为智养恬。","圣朝英彦富，幸许一夫潜。"]},{"t":"观僧室画山水","f":"词","c":["画精禅室冷，方暑久徘徊。","不尽林端雪，长青石上苔。","心闲对岩岫，目净失尘埃。","坐久清风至，疑从翠涧来。"]},{"t":"齐山诗呈王学士","f":"词","c":["江上有奇山，群峰矗如剪。","昔闻齐刺史，置酒升绝巘。","其人有惠政，嘉名自兹远。","君来踵其迹，词牒日清简。","骊驹时入谷，胜地穷搜选。","问俗复怀人，非徒事游衍。"]},{"t":"初见白发慨然感怀","f":"词","c":["万物壮必老，性理之自然。","我年垂四十，安得无华颠。","所悲道业寡，汨没无佗贤。","深惧岁月颓，宿心空弃捐。","视此足自儆，拔之乃违天。","留为鉴中铭，晨夕思乾乾。"]},{"t":"钱君倚示诗有归吴之兴为诗三十二韵以赠","f":"词","c":["吴越为君土，崤函是我家。","濯缨从吏事，倾盖聚京华。","奕世交朋重，同僚分谊加。","声光尝耳剽，臭味辱肩差。","选士参县石，烝髦应椓罝。","帝畿围日月，蓬堵积烟霞。","咨访倾肝胆，推褒借齿牙。","后来惭瓦砾，旁倚愧蒹葭。","谈论寥天一，诙谐老柏槎。","虚舟坦莫逆，璞玉瑩无瑕。","信美陪游衍，胡为起咄嗟。","劳歌尽乡思，旅梦各天涯。","诚厌簪绅累，难堪狱讼哗。","缿筒朝插猬，贯索暮如麻。","霢霂沾朝服，蜩螗沸尹衙。","宿奸牢窟宅，弊俗费鞭挝。","鲚鲙思吹絮，羊羹忆卧沙。","梅林连雨熟，梨味得霜佳。","秋色城临水，春风路入花。","稻肥初断蟹，桑密不通鸦。","蹙衄浮盘芡，钩联卧垄瓜。","江莼半卷叶，石蕨乍舒芽。","风物随乡乐，山川苦道遐。","若人才有裕，修已德无邪。","正恐临髋髀，安能舍镆铘。","怒飞期寖逼，肥遁迹犹赊。","不比沟中木，微同井底蛙。","果能真引去，谁复强邀遮。","旋结蜗牛舍，还乘下泽车。","闭门常反拒，醉帻任攲斜。","林野游如鹿，泥涂蛰似蛇。","故人时记忆，阳羡致新茶。"]},{"t":"吴冲卿直舍阎士安画墨竹歌","f":"词","c":["阎生画竹旧所闻，望中一见遥可分。","伊予不甚少佳画，犹爱气骨高出群。","狂枝怒叶凌绢素，势若飞动争纷纭。","蟠根数节出地底，上有积年苍藓纹。","森然直干忽孤耸，意恐出屋排浮云。","秋风飒飒生左右，耳目洒落遗尘氛。","乃知良工自神解，昧者仿习徒艰勤。","子猷昔者得收玩，不患终朝无此君。"]},{"t":"园中书事二绝 其一","f":"词","c":["芳洲晚日鲜，曲岸新雨好。","红薇点圆荷，金䔲出幽草。"]},{"t":"寿安杂诗十首 永济渡二首 其二","f":"词","c":["清波见白鸥，静林闻啄木。","泉细入平沙，云闲出幽谷。"]},{"t":"寿安杂诗十首 永济渡二首 其一","f":"词","c":["洛水寒可涉，长汀柳飞叶。","节物先无期，自与幽怀惬。"]},{"t":"寿安杂诗十首 喷玉泉","f":"词","c":["苍崖双起秋云齐，乱峰迸出如攒犀。","石棱涩不容马蹄，下马步入荆榛蹊。","瀑泉沃雪拖白霓，落潭横引成清溪。","老木长藤咫尺迷，兴阑欲出忘东西。"]},{"t":"寿安杂诗十首 灵山寺","f":"词","c":["神林兴尽谋早归，草间露裛行径微。","忽思灵山去不远，马首欲东还向西。","垂鞭纵辔寻山足，洛水逶迤过数曲。","渐闻林下飞泉鸣，未到已觉神骨清。","入门拂去衣上土，先爱娑罗阴满庭。","庭下双渠走清澈，罗縠成纹日光彻。","寒声淅沥入肝髓，乱影彯萧动毛发。","寺僧引我观泉源，堂东周回百步宽。","碧颇梨色湛无底，想象必有虬龙蟠。","泉南高山名凤翅，宛转抱泉张远势。","岸旁脩竹踰万竿，飒飒长含风雨气。","寺门下望情豁然，桑柘纷披满一川。","嵩高女几列左右，王屋太行来掌前。","昔为孔氏悬泉庄，岩洞犹存荆棘荒。","到今其下多怪石，熊蹲豹攫争轩昂。","嗟予归来苦不早，汨没朝市行欲老。","扪萝蹑屣须数游，筋力支离难自保。"]},{"t":"寿安杂诗十首 藏珠石","f":"词","c":["水齧东山根，土色渥如丹。","危峰忽摧脱，半崖衔石丸。","阴阳昔融结，神化不可原。","初疑偓佺养灵药，魑魅触之无故落。","又疑蛟龙伏巨卵，雷电击之从此毈。","或者女娲补天馀，却下青冥遗耳珠。","不然盘古戏为乐，聊取天弧弹朱雀。","物理万状终难知，巧心推求徒自疲。","不如引客坐石上，好奇且醉手中卮。"]},{"t":"张明叔兄弟雨中见过弄水轩投壶赌酒薄暮而散诘朝以诗谢之","f":"词","c":["喜君午际来，凉雨正纷泊。","呼奴扫南轩，壶席谨量度。","轩前红薇开，壶下鸣泉落。","必争如五射，有礼异六博。","求全怯垂成，倒置畏反跃。","虽无百骁巧，且有一笑乐。","交飞觥酒满，强进盘餐薄。","苟非兴趣同，珍殽徒绮错。"]},{"t":"杨白华","f":"词","c":["劝君勿嫌杨花太轻薄，篱下沟中纷漠漠。","翠鬟婢子不胜愁，扫尽还飞满朱阁。","晚来风雨送行春，天无游丝地无尘。","雪狂絮乱安可得，孤树青青愁杀人。"]},{"t":"穷兔谣二首 其二","f":"词","c":["兔营三窟定何在，棘间堑底高丘巅。","却行百步方跃入，未免馀踪留雪田。","少年何为无恻隐，解鹰纵犬薰以烟。","人言兔狡非兔狡，窘急偷生真可怜。"]},{"t":"穷兔谣二首 其一","f":"词","c":["鹘翅崩腾来九霄，兔命迫窄无所逃。","秋毫就死忽背跃，鹘拳不中还飞高。","安知韩卢复在后，力屈但作婴儿号。","少年只取一快乐，谁念草根腥血毛。"]},{"t":"花庵诗寄邵尧夫 其一","f":"词","c":["洛阳四时常有花，雨晴颜色秋更好。","谁能相与共此乐，坐对年华不知老。"]},{"t":"苏门先生","f":"词","c":["长啸苏门石，行藏世莫知。","逍遥心迹远，寂寞姓名谁。","乡在无何有，时方不可为。","麒麟本神物，安得系而羁。"]},{"t":"走索","f":"词","c":["伎儿欲誇众，喜占衢路交。","系组不厌长，缚竿不厌高。","空中纷往来，巧捷如飞猱。","却行欠肤寸，倒絓连秋毫。","参差有万一，齑粉安可逃。","钱刀不盈掬，身世轻鸿毛。","徒资旁观好，曹偶相称褒。","岂知从事者，处之危且劳。"]},{"t":"邵不疑厅薜荔及竹","f":"词","c":["脩竹非俗物，薜荔亦嘉草。","树之君子庭，人来见逾好。","侵阶鹤胫细，缘壁龙鳞老。","纷披两疏翠，烟色宜秋早。","主人日封植，清风庶长保。"]},{"t":"闰正月十五日夜监直对月怀诸同舍 其一","f":"词","c":["雾净金波溢，天开碧幕空。","夜寒虽料峭，春意自冲融。","熠熠枝上露，翛翛竹杪风。","暂还林野兴，不似畜樊笼。"]},{"t":"和人苇花","f":"词","c":["葭菼迷河曲，高秋一番荣。","齐纨张野白，楚练照川明。","不夜月长皎，踰时雪未晴。","万仙霓帔合，千亩玉苗生。","漠漠波澜偃，茫茫沙碛平。","际空盐海竭，垂地塞云横。","日暖鸥无色，风高鹤有声。","逢君得嘲赋，岂愧束薪并。"]},{"t":"和之美二贫诗","f":"词","c":["君子尚仁义，宝用为身资。","其人苟不贤，富饶亦胡为。","所以回宪徒，不厌糠与藜。","当时万金产，令名传者谁。","之美初解褐，为吏长河湄。","月得数斗禄，仅足供饘糜。","谓言家无宝，不必修藩篱。","囊衣不自暖，乃为偷意窥。","穿墉入其室，探取无纤遗。","从事借之带，同列乞其衣。","日高服未具，不敢踰门畿。","萧条四壁寒，独立空自嗤。","援毫引幅纸，书作二贫诗。","上言运命邅，温饫无时期。","下嗟职事劳，旧学日以隳。","乃知贤者心，不独忧寒饥。","壈坎虽益多，志业终无衰。","我实甚贫者，视君犹白圭。","行年三十馀，碌碌无佗奇。","庇身太学官，旦夕唯盐齑。","读君二贫作，我事借君词。","君诚士林秀，不免青衫卑。","满腹岂无才，抱蓄未有施。","不用固为小，用之活蒸黎。","如君有此富，岂必藏珠玑。","财贫非道贫，已矣何嗟咨。"]},{"t":"和之美舟行杂诗八首 其一 舟中夜坐","f":"词","c":["风柳动萧疏，寒星浸寥落。","中宵四寂然，时有游鱼跃。"]},{"t":"和之美舟行杂诗八首 都门路","f":"词","c":["红尘昼夜飞，车马古今迹。","独怜道傍柳，惨淡少颜色。"]},{"t":"和之美河西列岫亭 其一","f":"词","c":["秋山对疏牖，羁客倦登临。","雨后岚光活，晴初落照深。","素波明别浦，赤叶照衰林。","伫目寂无语，何人知此心。"]},{"t":"和之美河洲四诗 其三","f":"词","c":["寂寂河洲夜，芦花绕墟舍。","孤客久未眠，窗灯落寒灺。"]},{"t":"和之美河洲四诗 其四","f":"词","c":["漠漠河洲雨，依稀辨村聚。","时哉鸥鸟群，凌乱争鸣舞。"]},{"t":"和子华喜潞公入觐归置酒游诸园赏牡丹","f":"词","c":["介圭成礼下中天，春物虽阑色尚妍。","园吏望尘皆辟户，肩舆回步即开筵。","波涛凌乱靴旁锦，风雨纵横拨底弦。","洛邑衣冠陪后乘，寻花载酒愿年年。"]},{"t":"和子华游君贶园 其二","f":"词","c":["小桃似喜相君来，争发新花继落梅。","更仗环溪醒残酒，没篙春水绿于苔。"]},{"t":"和子骏秋意","f":"词","c":["好风自远来，小雨初濡地。","虽当未夏半，已有清秋意。","新蝉乍孤吟，病叶或先坠。","顿觉愈沉疴，暂喜濯炎炽。","彩笔动高兴，瑶徽发幽思。","贱子独何为，宵凉甘熟寐。"]},{"t":"和不疑送虏使还道中闻江邻几梅圣俞长逝作诗哭之","f":"词","c":["昨夕邮吏来，叩门致书函。","呼奴取以入，就火开其缄。","不疑赋长篇，发自燕之南。","痛伤江与梅，继踵良人歼。","噫嗟知其二，尚未知其三。","请从北辕后，覼缕为君谈。","邻几虽久病，始不妨朝参。","饮歠寖衰少，厥逆生虚痰。","逮于易箦辰，皮骨馀崆嵌。","遗书属清俭，终始真无惭。","圣俞食寒冰，外以风邪兼。","愚医暴下之，结轖候愈添。","惙惙气上走，不复容针砭。","自言从良友，地下心亦甘。","钦圣体素彊，药石性所谙。","平居察举措，敢以不寿占。","一朝暂归卧，簿领不废签。","讣来众皆愕，未信犹窥觇。","兴言念三子，举袂涕已沾。","英贤能几何，逝者迹相衔。","君疑天上才，难得帝所贪。","我疑人间美，多取神所嫌。","茫茫幽明际，蓍蔡难穷探。","忧来不可忘，终日心厌厌。"]},{"t":"和公达过潘楼观七夕市","f":"词","c":["织女虽七襄，不能成报章。","无巧可乞汝，世人空自狂。","帝城秋色新，满市翠帟张。","伪物踰百种，烂漫侵数坊。","谁家油壁车，金碧照面光。","土偶长尺馀，买之珠一囊。","安知杼轴劳，何物为蚕桑。","纷华不足悦，浮侈真可伤。"]},{"t":"和王介甫明妃曲","f":"词","c":["胡雏上马唱胡歌，锦车已驾白橐驼。","明妃挥泪辞汉主，汉主伤心知奈何。","宫门铜环双兽面，回首何时复来见。","自嗟不若住巫山，布袖蒿簪嫁乡县。","万里寒沙草木稀，居延塞外使人归。","旧来相识更无物，只有云边秋雁飞。","愁坐泠泠调四弦，曲终掩面向胡天。","侍儿不解汉家语，指下哀声犹可传。","传遍胡人到中土，万一佗年流乐府。","妾身生死知不归，妾意终期寤人主。","目前美丑良易知，咫尺掖庭犹可欺。","君不见白头萧太傅，被谗仰药更无疑。"]},{"t":"和王介甫烘虱","f":"词","c":["天生万物名品夥，嗟尔为生至么么。","依人自活反食人，性喜覆藏便垢涴。","晨朝生子暮生孙，不日蕃滋踰万个。","透疏缘隙巧百端，通夕爬搔不能卧。","我归彼出疲奔命，备北惊南厌搜逻。","所擒至少所失多，舍置薰烧无术奈。","加之炭上犹晏然，相顾未知亡族祸。","大者洋洋迷所适，奔走未停身已堕。","细者懦怯但深潜，乾死缝中谁复课。","黑者抱发亦忧疑，逃入幧头默相贺。","腥烟腾起远袭人，袖拥鼻端时一唾。","初虽快意终自咎，致尔歼夷非尔过。","吾家箧笥本自贫，况复为人苦慵惰。","体生鳞甲未能浴，衣不离身成脆破。","朽缯坏絮为渊薮，如麦如麻寖肥大。","虚肠不免须侵人，肯学夷齐甘死饿。","醯酸蜹聚理固然，尔辈披攘我当坐。","但思努力自洁清，群虱皆当远迩播。"]},{"t":"和王秀才以光始自陜右游山归复将登少室为诗见寄","f":"词","c":["瘦马飘飖屡往还，疲劳专为访名山。","须知筋力行将老，渐恐峰峦不可攀。","蜡屐早能寻胜概，弹冠悔更落尘寰。","幸依贤者为东道，大得逍遥水石间。"]},{"t":"和梅圣俞咏昌言五物 白鹘图","f":"词","c":["白鹘日边来，一息万里遥。","横飞碧海晴，六翮寒萧萧。","轻如朔雪花，迥与长风飘。","倾身叠绀爪，吟啸何哓哮。","瞥来疾惊电，欻起先扶摇。","遂令狐与狸，不敢矜凶妖。","罻罗不可取，灭影还云霄。","世人莫得见，粉绘图轻绡。","凛然堂牖间，霜气生春朝。","风雨夜如墨，古木无鸣枭。"]},{"t":"和梅圣俞咏昌言五物 怀素书","f":"词","c":["上人工书世所稀，于今散落无复遗。","君从何处获数幅，败绢苍苍不成轴。","云流电走何纵横，昏醉视之双目明。","烈火烧林虎豹慄，疾雷裂地龙蛇惊。","须臾挂壁未收卷，阴风飒飒来吹面。","秪疑神物在闇中，宝秘不令关俗眼。","嗟余平生不识书，但爱意气豪有馀。","欲求数字置座侧，安得满斗千金珠。"]},{"t":"和梅圣俞咏昌言五物 括苍石屏","f":"词","c":["主人小石屏，得之括苍山。","括苍道里远，致此良亦难。","层崖万仞馀，腾出浮云端。","吴儿采石时，萝蔓愁攀缘。","石文状松雪，毫发皆天然。","置之坐席旁，清风常在颜。","愿君善藏蓄，永日供馀闲。","慎勿示要人，坐致求者繁。","将使括苍民，吁嗟山谷间。"]},{"t":"和梅圣俞咏昌言五物 淡树石屏","f":"词","c":["昔行巩洛间，马瘦天复阴。","寒烟淡不收，一拂横长林。","当时无画工，负此清赏心。","今朝石上迹，历历皆可寻。","轻素已纷泊，老干仍萧森。","坐令高兴还，野气生衣襟。","丹青不耐久，风日易消侵。","何如造化真，更彼岁月深。","昌言家素贫，购此糜百金。","请镌好事名，千古无消沈。"]},{"t":"和梅圣俞咏昌言五物 缚虎图","f":"词","c":["孙生非画师，趣尚颇奇伟。","为人少谐合，不肯畜妻子。","时时入深山，信足动百里。","萧然坐盘石，尽日曾不起。","精心忽有得，纵笔何恢诡。","万象皆自然，神工相表里。","流传落人间，万金易寸纸。","君家缚虎图，用意尤精致。","虽云锁纽牢，观者犹披靡。","昔闻刘纲妻，制虎如犬豕。","系之床脚间，垂头受鞭箠。","孙生傥未见，画此亦何理。","明知非世人，羽化实不死。","愿君佗日归，置之成都市。","必有乘槎人，庶几能辨此。"]},{"t":"和兴宗夜直听雨","f":"词","c":["□茫冻雨来，入夜势增急。","纵横挟春风，飘洒相喷吸。","败窗端见欺，遽有万点入。","先生伏经编，眼冷倍昏涩。","夜分童仆倦，跛倚厌久立。","灯火为溟濛，诗书亦沾湿。","夫君储善价，未售不悁悒。","物华迎霁新，佳赏时将及。","囷中秫几何，营酿须汲汲。"]},{"t":"和吴冲卿崇文宿直睹壁上题名见寄并寄邵不疑","f":"词","c":["白袍昔纷纷，相与会东堂。","帝梧碧萧瑟，翔集皆鸾凰。","伊予素空疏，滥吹翰墨场。","不为群俊遗，出处联簪裳。","尔来凡六闰，转毂飞炎凉。","同歌太学下，共醉金马旁。","脩竹压窗寒，夭桃倚户芳。","金盘剖卢橘，玉壶分蔗浆。","惊呼局上急，嘲笑杯间狂。","神情一契会，形迹两俱忘。","欢馀叹薄宦，离合何能常。","濡毫纪岁时，挥霍素壁光。","去秋随相车，沿牒来东方。","城中未遍辞，不疑逐南荒。","奔波走郊外，取别何苍黄。","举觞未及尽，亟归还束装。","行行到官下，日积簿领忙。","文书拥笔端，胥史森如墙。","况当三伏深，沾汗尤淋浪。","细蝇绕眉睫，驱赫不可攘。","涔涔头目昏，始觉冠带妨。","诚知才智微，吏治非所长。","惧贻知已羞，敢不益自强。","因思瓯闽远，南走侵溟涨。","炎蒸异中县，从古无雪霜。","终朝坐茅屋，盐茗征行商。","欢哗费口舌，解囊收毫芒。","不疑性高介，此困安可当。","山川几千里，问讯谁能将。","冲卿居京邑，青云正腾骧。","寓直紫台上，风露澄东厢。","清夜不成寐，缓步聊彷徨。","拂此壁上尘，远怀同舍郎。","英辞欻感发，高义纷激昂。","泠泠宫殿虚，讽咏何琅琅。","手书成两通，贮之古锦囊。","一往泉山南，一致汶水阳。","坚重金璧体，光寒矛剑铓。","乃知贤隽心，浅俗未易量。","何尝用荣枯，遽尔分否臧。","居然激衰薄，更使清风扬。"]},{"t":"和孙器之清风楼","f":"词","c":["贤侯宴枚马，歌鼓事繁华。","晚吹来千里，清商落万家。","平原转疏雨，远树隔残霞。","宋玉虽能赋，还须念景差。"]},{"t":"和安之喜雨","f":"词","c":["吁嗟方请雨，润溽果如占。","黍稷固有望，来麰亦未嫌。","声繁清倦枕，气冷入疏帘。","蔓喜龙头举，泉惊虎爪添。","田畴诚最急，花药不妨兼。","诗伯才盈斛，聊应费笔尖。"]},{"t":"和利州鲜于转运公居八咏 山斋","f":"词","c":["幽蹊入桃李，危栈蟠林麓。","行行忽虚敞，高斋出山腹。","园圃近指掌，郊郭纷盈目。","春老酴醾香，夏浅筼筜绿。","条横喜罥衣，笋迸乍穿屋。","秋江澄可卷，冬岭翠如扑。","烟间渔艇小，塞外村居独。","烧转望畬田，响答聆伐木。","惊麇挺走险，鸣禽嘤出谷。","物华时变更，兴趣日相续。","谁知使者尊，常著野人服。","肯以驷马荣，区区诧乡族。"]},{"t":"会景亭","f":"词","c":["景物浩无穷，兹为一都会。","之人心若鉴，万状尽相对。","乔林拥砌底，脩岭倚窗背。","流云过席上，去鸟出天外。","徐徐杖屦整，蔼蔼郊原晦。","来往亦何为，逍遥真乐内。"]},{"t":"和利州鲜于转运公居八咏 巽堂","f":"词","c":["华堂选形胜，地直巽之隅。","主人心洁齐，公闲此燕居。","西来故乡客，东过朝大夫。","时逢志所惬，下榻同欢娱。","琴棋间壶觞，赋咏杂歌呼。","民间既羲皇，席上宜华胥。","每思就一醉，幸无官守拘。","奈何三千里，风埃与泥涂。"]},{"t":"和利州鲜于转运公居八咏 竹轩","f":"词","c":["兹轩最洒落，历历种琅玕。","正昼簿书稀，萧萧风雨寒。","翠阴凉宴坐，疏韵承清欢。","锦箨裁夏扇，玉笋供春槃。","晴蜗潜叶底，暝雀投林端。","幽兴遇物惬，高怀随处安。","且免一日无，何须千亩宽。"]},{"t":"闲燕亭","f":"词","c":["吏治正倥偬，夫君何燕闲。","茧丝既云寡，符移皆可删。","印封从事散，蹑屐升东山。","放杖坐危亭，清啸出云间。","无私席宾少，忘机林鸟还。","野人瞻翠微，稽首双眉斑。"]},{"t":"会景亭 宝峰亭","f":"词","c":["孤亭冠山椒，下视物不隔。","六合纵心赏，万家穷目力。","髻鬟乌奴翠，衣带嘉陵碧。","霞生白水尾，日没九陇脊。","烟凝朝夕市，尘飞往来驿。","虽复对纷纭，何尝改岑寂。","实兼观风远，非徒选胜适。","巴峡少平田，每苦天宇窄。","及兹伏棂槛，坐瞰南北极。","先君昔乘轺，名题古寺壁。","侍行尚垂髫，孤露今戴白。","读君登临诗，旧游皆历历。","永无膝下欢，终篇涕沾臆。"]},{"t":"和利州鲜于转运公居八咏 柏轩","f":"词","c":["凛然凌霜色，本自生丘壑。","徙之君子庭，栽培固不薄。","静夜声飂飂，清昼阴漠漠。","秀气逼檐楹，翠影通帘箔。","知君梁栋材，大匠偶未度。","但守岁寒心，闲轩亦不恶。"]},{"t":"和利州鲜于转运公居八咏 桐轩","f":"词","c":["朝阳升东隅，照此庭下桐。","菶菶复萋萋，居然古人风。","疏柯青玉耸，密叶翠羽蒙。","午景凝馀清，夕照当残红。","雨响甍栋外，风生户牖中。","主人政多暇，步赏常从容。","终当致威凤，览德鸣噰噰。","又将施五弦，解愠歌帝宫。"]},{"t":"和钱君倚日本刀歌","f":"词","c":["昆吾道远不复通，世传切玉谁能穷。","宝刀近出日本国，越贾得之沧海东。","鱼皮装贴香木鞘，黄白间杂鍮与铜。","百金传入好事手，佩服可以攘祅凶。","传闻其国居大岛，土壤沃饶风俗好。","其先徐福诈秦民，采药淹留童丱老。","百工五种与之俱，至今器用皆精巧。","前朝贡献屡往来，士人往往工辞藻。","徐福行时书未焚，逸书百篇今尚存。","令严不许传中国，举世无人识古文。","嗟予乘桴欲往学，沧波浩荡无通津。","令人感叹坐流涕，锈涩短刀何足云。"]},{"t":"和君倚藤床十二韵","f":"词","c":["嗟予仕京府，谋禄非谋身。","岂徒劳百骸，消铄侵天真。","所畏旷官诛，敢辞从事勤。","朝讯狱中囚，暮省案前文。","虽有八尺床，初无偃息痕。","比归暂解带，日没轩窗昏。","援枕未及就，扑面愁飞蚊。","未能习律令，何暇窥皇坟。","夫君天才秀，明颍排纠纷。","右曹况清简，剸裂奚足云。","未遇且坚卧，逢时将致君。","行当起经济，膏沐醒吾人。"]},{"t":"和吴冲卿三哀诗","f":"词","c":["天生千万人，中有一隽杰。","奈何丧三贤，前后才期月。","邻几任天资，浮饰耻澡刷。","朝市等山林，衣冠同布褐。","外无泾渭分，内有淄渑别。","逢时敢危言，慷慨谁能夺。","圣俞诗七千，历历尽精绝。","初无追琢勤，气质禀清洁。","负兹惊世才，未尝自标揭。","鞠躬随众后，侧足畏蹉跌。","钦圣渥洼驹，初生已汗血。","虽有绝尘踪，不失和鸾节。","宜为清庙器，俨雅应钟律。","众论仍共然，非从友朋出。","群才方大来，軮轧扶帝室。","谁云指顾间，联翩化异物。","吊缞哭未已，病枕气已竭。","同为地下游，携手不相失。","绅绂顿萧条，相逢但嗟咄。","诵君三哀诗，终篇涕如雪。","眉目尚昭晢，笑言犹彷佛。","肃然来悲风，四望气萧瑟。"]},{"t":"和吴省副梅花半开招凭由张司封饮","f":"词","c":["帝乡春色岭头梅，高压年华犯雪开。","正与嘉宾思共醉，不须芳物重相催。","从车贮酒传呼出，侧弁簪花倒载回。","风雨难期王事剧，未知休沐几旬来。"]},{"t":"和宋郎中孟秋省直","f":"词","c":["夜久残暑尽，好风来满襟。","床空唯置枕，冠小不施簪。","竹影乱凉月，林梢转晓参。","人心有喧寂，何必欲云岑。"]},{"t":"和张仲通学士苦暑思长安幕中望终南秋雪呈江邻几","f":"词","c":["秋云覆秦川，小雨野未湿。","谁言终南顶，已有霰雪集。","返景开新晴，孱颜照都邑。","初疑江津阔，远浪横风急。","又疑龙蜕骨，逶迤委原隰。","词客登高楼，四望清兴入。","当时应百篇，遗散不复拾。","今兹宦帝城，大暑困郁悒。","红尘满九衢，出入冠带袭。","家居宾旅来，俯偻烦拜揖。","回思幕中趣，引领安可及。","江翁养文采，正如玄豹蛰。","君往犯其严，腾起谁敢絷。","嗟予素恇怯，旁睨毛发立。","强复缀此章，庶几勇可习。"]},{"t":"和邵不疑校理蒲州十诗 其七 凉□","f":"词","c":["□□□□□，□□□□□。","清风满四境，岂独华榱下。","不若楚台人，披襟独萧洒。"]},{"t":"和邵不疑校理蒲州十诗 其九 惜花亭","f":"词","c":["春意复蹉蛇，园林日愁寂。","枝边绿阴重，砌下红英积。","兹亭花最繁，飘零尤可惜。"]},{"t":"和邵不疑校理蒲州十诗 其十 竹轩","f":"词","c":["茂密正当轩，攲垂欲侵案。","风枝忽交戛，月影争凌乱。","诚嘉君子心，匪直林亭玩。"]}]};